 const h=JSON.stringify(card?.header?.contents||[]);
 if(/ตั้งค่า|แก้ไข|แก้ข้อมูล|กรอกข้อมูล|เลือกสี|แบบฟอร์ม/u.test(h))return false;
 return /(?:^🏠 ครอบครัว|^👨‍👩‍👧‍👦 ครอบครัว|ภาพรวม|^💊|^📅|^🩺|^📄|^📁 รูปและเอกสาร|^💰)/u.test(a)
   ||/(?:ครอบครัว|ภาพรวมบุคคล|💊 ยา|📅 นัดหมาย|🩺 สุขภาพ|📄 เอกสาร|💰 ค่าใช้จ่าย)/u.test(h);
