 /* PHMS_LINE_POSTBACK_300_BYTE_WIRE_GUARD_V1: LINE action.data max 300 bytes. */
 function fixActionData(node:any,depth=0):void{
  if(!node||typeof node!=='object'||depth>45)return;
  if(Array.isArray(node)){for(const x of node)fixActionData(x,depth+1);return}
  const a=node.action;
  if(a?.type==='postback'&&typeof a.data==='string'&&E.encode(a.data).length>300){
   const raw=a.data;
   const parsed=raw.match(/^(เปิด(?:นัด|สุขภาพ)ครอบครัว\\s+[a-f0-9]{12})\\s+([^\\s]+)/i);
   let next=parsed?parsed[1]+' '+parsed[2]:null;
   if(next&&E.encode(next).length>300){
    let short=parsed![2];
    while(short.length>0&&E.encode(parsed![1]+' '+short).length>300)short=short.slice(0,-1);
    next=short?parsed![1]+' '+short:null;
   }
   if(!next)next='บุคคลในครอบครัว';
   console.error('phms_oversize_postback_repaired',E.encode(raw).length,E.encode(next).length);
   a.data=next;
  }
  for(const [key,value] of Object.entries(node))if(key!=='action')fixActionData(value,depth+1);
 }
