async function activeRichMenuId(u:string,k:string,key:'setup'|'main'){
 const r=await fetch(u+'/rest/v1/line_rich_menu_configs?key=eq.'+key+'&status=eq.active&select=rich_menu_id&limit=1',{headers:H(k)});
 const rows=await r.json().catch(()=>[]);return r.ok?String(rows?.[0]?.rich_menu_id||''):''}
async function forceRichMenu(u:string,k:string,t:string,id:string,key:'setup'|'main'){
 const menuId=await activeRichMenuId(u,k,key);if(!menuId)throw new Error('rich_menu_not_configured:'+key);
 const r=await fetch('https://api.line.me/v2/bot/user/'+encodeURIComponent(id)+'/richmenu/'+encodeURIComponent(menuId),{method:'POST',headers:{Authorization:'Bearer '+t}});
 if(!r.ok)throw new Error('rich_menu_link_failed:'+r.status+':'+await r.text());
 try{
   await fetch(u+'/rest/v1/line_identities?line_user_id=eq.'+encodeURIComponent(id),{
     method:'PATCH',headers:{...H(k),Prefer:'return=minimal'},
     body:JSON.stringify({rich_menu_key:key,rich_menu_id:menuId,rich_menu_synced_at:new Date().toISOString(),updated_at:new Date().toISOString()})
   })
 }catch{}
 return menuId
}
async function recordLineFollow(u:string,k:string,t:string,id:string){
 let profile:any=null;
 try{const r=await fetch('https://api.line.me/v2/bot/profile/'+encodeURIComponent(id),{headers:{Authorization:'Bearer '+t}});if(r.ok)profile=await r.json()}catch{}
 const now=new Date().toISOString();
 const existing=await fetch(u+'/rest/v1/line_identities?line_user_id=eq.'+encodeURIComponent(id)+'&select=id,user_id,onboarding_status&limit=1',{headers:H(k)});
 const rows=existing.ok?await existing.json():[];
 if(rows?.[0]){
   await fetch(u+'/rest/v1/line_identities?line_user_id=eq.'+encodeURIComponent(id),{
     method:'PATCH',headers:{...H(k),Prefer:'return=minimal'},
     body:JSON.stringify({is_active:true,last_follow_at:now,display_name:profile?.displayName||undefined,picture_url:profile?.pictureUrl||undefined,status_message:profile?.statusMessage||undefined,updated_at:now})
   });
   const desired=rows[0]?.user_id?'main':'setup';
   await forceRichMenu(u,k,t,id,desired);
   return desired
 }
 await fetch(u+'/rest/v1/line_identities',{
   method:'POST',headers:{...H(k),Prefer:'return=minimal'},
   body:JSON.stringify({line_user_id:id,display_name:profile?.displayName||null,picture_url:profile?.pictureUrl||null,status_message:profile?.statusMessage||null,is_active:true,onboarding_status:'new',last_follow_at:now})
 });
 await forceRichMenu(u,k,t,id,'setup');
 return 'setup'
}
async function recordLineUnfollow(u:string,k:string,id:string){
 const now=new Date().toISOString();
 await fetch(u+'/rest/v1/line_identities?line_user_id=eq.'+encodeURIComponent(id),{
   method:'PATCH',headers:{...H(k),Prefer:'return=minimal'},
   body:JSON.stringify({is_active:false,updated_at:now})
 }).catch(()=>null)
}
async function iden(u:string,k:string,id:string){const r=await fetch(u+'/rest/v1/line_identities?line_user_id=eq.'+encodeURIComponent(id)+'&select=user_id,display_name&limit=1',{headers:H(k)});return r.ok?(await r.json())[0]??null:null}async function name(u:string,k:string,id:string){try{const p=one(await rpc(u,k,'phms_get_line_self_profile',{p_line_user_id:id}));if(p?.display_name)return p.display_name;if(p?.nickname)return p.nickname}catch{}try{const st=one(await rpc(u,k,'phms_get_line_setup_state',{p_line_user_id:id}));if(st?.self_person_name)return st.self_person_name}catch{}return (await iden(u,k,id))?.display_name||'คุณ'}
function phmsRestrictedAppointmentCommand(cmd:string){
 const text=String(cmd||'');
 let m=text.match(/^(?:แก้ค่าใช้จ่ายนัด|แนบหลักฐานค่าใช้จ่าย|เปลี่ยนการชำระเงิน|ค่าใช้จ่ายหลังนัด)\s+#?([0-9a-fA-F-]{8,36})/i);
 if(m)return {code:String(m[1]||''),kind:'finance_edit'};
 m=text.match(/^(?:ค่าใช้จ่ายนัด|รายละเอียดค่ารักษา|ดูรายละเอียดค่ารักษา|รายการค่ารักษา|หลักฐานค่าใช้จ่าย)\s+#?([0-9a-fA-F-]{8,36})/i);
 if(m)return {code:String(m[1]||''),kind:'finance_view'};
 m=text.match(/^(?:ตั้งค่าแจ้งเตือนนัด|ผู้รับแจ้งเตือนนัด|เทมเพลตแจ้งเตือนนัด|สิ่งที่ต้องทำก่อนนัด|เชื่อมนัด|เมนูนัด)\s+#?([0-9a-fA-F-]{8,36})/i);
 if(m)return {code:String(m[1]||''),kind:'manage'};
 m=text.match(/^เลื่อนนัด\s+#?([0-9a-fA-F-]{8,36})/i);
 if(m)return {code:String(m[1]||''),kind:'reschedule'};
 return null
}
async function phmsBlockLimitedAppointmentDetail(rt:string,u:string,k:string,id:string,t:string,cmd:string){
 const req=phmsRestrictedAppointmentCommand(cmd);
 if(!req)return false;
 try{
  const caps=one(await rpc(u,k,'phms_line_record_capabilities',{p_line_user_id:id,p_resource:'appointment',p_record_code:req.code}))||{};
  if(req.kind==='finance_view'){
   if(caps?.can_view_finance===true||caps?.can_view_sensitive===true)return false;
   await reply(rt,'🔒 ส่วนนี้เป็นข้อมูลค่าใช้จ่าย\n\nค่าใช้จ่ายและหลักฐานการชำระเงิน ดูได้เฉพาะเจ้าของข้อมูลสุขภาพ ผู้ดูแลหลัก หรือผู้ช่วยดูแลที่ถูกมอบหมายในนัดนี้และมีสิทธิ์ดูนัด',t,[pb('📅 ดูรายละเอียดนัด','ดูนัด '+req.code)]);
   return true
  }
  if(req.kind==='finance_edit'){
   if(caps?.can_update_finance===true)return false;
   await reply(rt,'🔒 คุณมีสิทธิ์ดูค่าใช้จ่ายได้ แต่ยังไม่มีสิทธิ์แก้ไข\n\nการแก้ยอด ช่องทางชำระ ผู้จ่าย หรือแนบหลักฐานการชำระ ต้องมีสิทธิ์แก้ไขนัดของบุคคลนี้ด้วย',t,[pb('💰 ดูค่าใช้จ่าย','ค่าใช้จ่ายนัด '+req.code),pb('📅 ดูรายละเอียดนัด','ดูนัด '+req.code)]);
   return true
  }
  if(req.kind==='reschedule'){
   if(caps?.can_update===true)return false;
   try{
    const rr=one(await rpc(u,k,'phms_line_appointment_reschedule_get',{p_line_user_id:id,p_record_code:req.code}))||{};
    if(rr?.is_assignee===true)return false
   }catch{}
   await reply(rt,'🔒 การเลื่อนนัดทำได้เฉพาะคนที่จัดการนัดได้ หรือคนที่ได้รับมอบหมายให้เลื่อนนัดนี้',t,[pb('📅 ดูรายละเอียดนัด','ดูนัด '+req.code)]);
   return true
  }
  if(caps?.can_update===true)return false;
  await reply(rt,'🔒 ส่วนนี้เป็นเมนูจัดการนัด\n\nคุณยังดูรายละเอียด บันทึกหลังนัด และประวัติการแก้ไขได้ตามสิทธิ์ แต่การตั้งค่า/แก้ไขต้องเป็นคนที่จัดการนัดได้',t,[pb('📅 ดูรายละเอียดนัด','ดูนัด '+req.code)]);
  return true
 }catch{return false}
}

const hint='\n\n💡 กดปุ่มด้านล่างได้เลย หรือครั้งต่อไปกดจาก “เมนูอิ่มอุ่น” ก็ได้';const homeQ=[act('💊 ยา','ยา'),act('📅 นัด','นัดหมาย'),act('🩺 สุขภาพ','สุขภาพ'),act('📄 เอกสาร','เอกสาร'),act('📁 รูปและเอกสาร','รูปและเอกสาร'),act('👨‍👩‍👧 ครอบครัว','ครอบครัว'),act('👤 ข้อมูลของฉัน','ใช้ข้อมูลของฉัน')];async function state(u:string,k:string,id:string,key:string,data:any={},ttlMinutes?:number){await rpc(u,k,'phms_set_line_conversation_state',{p_line_user_id:id,p_state_key:key,p_state_data:data,p_ttl_minutes:ttlMinutes??(/^(?:smart_medication(?:_field)?|crud_add_(?:medication|appointment|health)|phms_add_(?:menu|field|review))$/.test(key)?1440:30)})}async function clear(u:string,k:string,id:string){try{await rpc(u,k,'phms_clear_line_conversation_state',{p_line_user_id:id})}catch{}}async function getState(u:string,k:string,id:string){try{return one(await rpc(u,k,'phms_get_line_conversation_state',{p_line_user_id:id}))}catch{return null}}
function phmsYesNo(v:any){
 const s=String(v||'').trim().toLowerCase();
 if(['ใช่','yes','y','true','1','เปิด','ให้','รับ'].includes(s))return true;
 if(['ไม่','ไม่ใช่','no','n','false','0','ปิด','ไม่ให้','ไม่รับ'].includes(s))return false;
 throw new Error('invalid_yes_no')
}
function phmsAccessLevel(v:any){
 const s=String(v||'').trim().toLowerCase();
 if(['ไม่มี','ไม่มีสิทธิ์','none','ปิด','ไม่'].includes(s))return 'none';
 if(['ดู','ดูอย่างเดียว','view','read'].includes(s))return 'view';
 if(['จัดการ','ดู/เพิ่ม/แก้','ดู เพิ่ม แก้','manage','แก้ไข'].includes(s))return 'manage';
 throw new Error('invalid_access_level')
}
function parsePhmsTemplate(text:string){
 const out:any={};
 for(const line of String(text||'').replace(/\r/g,'').split('\n')){
  const m=line.match(/^\s*([^:：=]+?)\s*[:：=]\s*(.*?)\s*$/);
  if(!m)continue;
  out[String(m[1]||'').trim()]=String(m[2]||'').trim()
 }
 return out
}
/* PHMS_PRIVATE_APPOINTMENT_HANDOFF_V1
 Server-only 15-minute reference. The user only sees "ดูรายละเอียดนัด".
 Never expose an appointment code in a LINE deep-link draft or a group message. */
async function phmsStorePrivateAppointmentHandoff(u:string,k:string,userId:string,code:string){
 if(!userId||!code)return false;
 try{
  const response=await fetch(u+'/rest/v1/phms_private_appointment_handoff?on_conflict=line_user_id',{
   method:'POST',headers:{apikey:k,Authorization:'Bearer '+k,'Content-Type':'application/json',Prefer:'resolution=merge-duplicates'},
   body:JSON.stringify({line_user_id:userId,record_code:code,expires_at:new Date(Date.now()+15*60*1000).toISOString(),updated_at:new Date().toISOString()})
  });
  return response.ok
 }catch{return false}
}
async function phmsConsumePrivateAppointmentHandoff(u:string,k:string,userId:string){
 if(!userId)return '';
 try{
  const url=u+'/rest/v1/phms_private_appointment_handoff?line_user_id=eq.'+encodeURIComponent(userId)+'&select=record_code,expires_at&limit=1';
  const headers={apikey:k,Authorization:'Bearer '+k};
  const response=await fetch(url,{headers});
  if(!response.ok)return '';
  const records=await response.json();
  const item=Array.isArray(records)?records[0]:null;
  if(!item||Date.parse(String(item.expires_at||''))<=Date.now())return '';
  await fetch(u+'/rest/v1/phms_private_appointment_handoff?line_user_id=eq.'+encodeURIComponent(userId),{method:'DELETE',headers});
  return String(item.record_code||'')
 }catch{return ''}
}
async function lineInviteDeepLink(t:string,command:string,fallback:string){
 try{
  const r=await fetch('https://api.line.me/v2/bot/info',{headers:{Authorization:'Bearer '+t}});
  if(!r.ok)return fallback;
  const d=await r.json();const basicId=String(d?.basicId||'');
  if(!basicId)return fallback;
  return 'https://line.me/R/oaMessage/'+encodeURIComponent(basicId)+'/?'+encodeURIComponent(command)
 }catch{return fallback}
}
async function lineOpenOfficialAccount(t:string,fallback:string){
 try{
  const r=await fetch('https://api.line.me/v2/bot/info',{headers:{Authorization:'Bearer '+t}});
  if(!r.ok)return fallback;
  const d=await r.json();
  const basicId=String(d?.basicId||'').trim();
  if(!basicId)return fallback;
  return 'https://line.me/R/ti/p/'+encodeURIComponent(basicId)
 }catch{return fallback}
}
async function sha256Hex(v:string){
 return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',E.encode(v))))
  .map(x=>x.toString(16).padStart(2,'0')).join('')
}
async function acceptPersonInviteDirect(u:string,k:string,id:string,token:string){
 let personName='บุคคลที่ได้รับคำเชิญ';
 try{
  const hash=await sha256Hex(token);
  const r=await fetch(
   u+'/rest/v1/person_claim_invitations?invitation_token_hash=eq.'+encodeURIComponent(hash)+
   '&status=eq.pending&expires_at=gt.'+encodeURIComponent(new Date().toISOString())+
   '&select=metadata&limit=1',
   {headers:H(k)}
  );
  const rows=r.ok?await r.json():[];
  personName=String(rows?.[0]?.metadata?.invite_person_name||personName)
 }catch{}
 const linked=one(await rpc(u,k,'phms_accept_line_person_invite_direct',{
  p_line_user_id:id,p_invitation_token:token
 }));
 return {...(linked||{}),person_name:personName}
}
async function acceptPersonInviteAsRequest(u:string,k:string,id:string,token:string){
 const hash=await sha256Hex(token);
 const r=await fetch(
  u+'/rest/v1/person_claim_invitations?invitation_token_hash=eq.'+encodeURIComponent(hash)+
  '&status=eq.pending&expires_at=gt.'+encodeURIComponent(new Date().toISOString())+
  '&select=id,person_id,family_id,metadata&limit=1',
  {headers:H(k)}
 );
 const rows=await r.json().catch(()=>[]);
 if(!r.ok||!Array.isArray(rows)||!rows[0])throw new Error('person_invite_invalid_or_expired');
 const inv=rows[0];
 const req=one(await rpc(u,k,'phms_request_existing_person_claim_from_line',{
  p_line_user_id:id,p_person_id:String(inv.person_id),p_family_id:String(inv.family_id)
 }));
 const li=await fetch(u+'/rest/v1/line_identities?line_user_id=eq.'+encodeURIComponent(id)+'&select=id,user_id&limit=1',{headers:H(k)});
 const lrows=li.ok?await li.json():[];
 await fetch(u+'/rest/v1/person_claim_invitations?id=eq.'+encodeURIComponent(String(inv.id)),{
  method:'PATCH',
  headers:{...H(k),Prefer:'return=minimal'},
  body:JSON.stringify({
   status:'accepted',
   accepted_by_user_id:lrows?.[0]?.user_id||null,
   accepted_by_line_identity_id:lrows?.[0]?.id||null,
   accepted_at:new Date().toISOString(),
   updated_at:new Date().toISOString()
  })
 });
 let personName=String(inv?.metadata?.invite_person_name||'').trim()||'บุคคลที่ได้รับคำเชิญ';
 if(personName==='บุคคลที่ได้รับคำเชิญ'){
  try{
   const pr=await fetch(u+'/rest/v1/persons?id=eq.'+encodeURIComponent(String(inv.person_id))+'&select=first_name,last_name&limit=1',{headers:H(k)});
   const rs=pr.ok?await pr.json():[];
   const pp=rs?.[0]||{};
   personName=[pp?.first_name,pp?.last_name].filter(Boolean).join(' ').trim()||'ยังไม่ได้ระบุชื่อจริง'
  }catch{}
 }
 return {request:req,person_name:personName,family_id:String(inv.family_id),person_id:String(inv.person_id)}
}
