function healthcareMasterFieldLabel(field:string){
 const m:any={
  name:'ชื่อ',branch_name:'สาขา',external_code:'รหัสย่อ',address_text:'ที่อยู่',phone:'เบอร์กลาง',email:'อีเมลกลาง',website_url:'เว็บไซต์',
  location_detail:'จุด/อาคาร/ชั้น',building_name:'อาคาร',floor_label:'ชั้น',contact_point:'จุดติดต่อ',
  contact_note:'หมายเหตุติดต่อ',reschedule_contact_phone:'เบอร์เลื่อนนัด',reschedule_contact_email:'อีเมลเลื่อนนัด',
  reschedule_hours_text:'เวลาติดต่อเลื่อนนัด',reschedule_instructions:'วิธี/เงื่อนไขเลื่อนนัด',
  reschedule_min_notice_minutes:'ต้องแจ้งล่วงหน้า'
 };
 return m[field]||field
}
function healthcareMasterNoticeMinutes(text:string){
 const s=normalizeAppointmentDigits(String(text||'').trim());
 if(!s||['-','—','ไม่มี','ลบ'].includes(s))return '';
 let m=s.match(/(\d+(?:\.\d+)?)\s*(?:สัปดาห์|อาทิตย์|week)/i);
 if(m)return String(Math.round(Number(m[1])*7*24*60));
 m=s.match(/(\d+(?:\.\d+)?)\s*(?:วัน|day)/i);
 if(m)return String(Math.round(Number(m[1])*24*60));
 m=s.match(/(\d+(?:\.\d+)?)\s*(?:ชั่วโมง|ชม\.?|hour)/i);
 if(m)return String(Math.round(Number(m[1])*60));
 m=s.match(/(\d+)\s*(?:นาที|น\.?|minute)/i);
 if(m)return String(Number(m[1]));
 if(/^\d+$/.test(s))return s;
 return null
}
function healthcareMasterNoticeLabel(v:any){
 const n=Number(v||0);if(!n)return '—';
 if(n%(7*1440)===0)return String(n/(7*1440))+' สัปดาห์';
 if(n%1440===0)return String(n/1440)+' วัน';
 if(n%60===0)return String(n/60)+' ชั่วโมง';
 return String(n)+' นาที'
}
