async function replyHealthcareMasterHospital(rt:string,u:string,k:string,id:string,t:string,code:string){
 const r=await healthcareMasterOverview(u,k,id);
 const hs=Array.isArray(r?.hospitals)?r.hospitals:[];
 const h=hs.find((x:any)=>String(x?.record_code||'')===String(code))||hs.find((x:any)=>String(x?.record_code||'').startsWith(String(code)));
 if(!h)throw new Error('healthcare_master_hospital_not_found');
 const units=Array.isArray(h?.units)?h.units:[];
 const lines=[
  '🏥 '+phmsHospitalShortLabel(h?.hospital_name||'โรงพยาบาล')+(h?.external_code&&!phmsHospitalShortLabel(h.hospital_name).includes('('+String(h.external_code)+')')?' ('+String(h.external_code)+')':''),
  h?.branch_name?'สาขา: '+String(h.branch_name):'',
  h?.phone?'☎️ เบอร์กลาง: '+String(h.phone):'',
  h?.email?'✉️ อีเมลกลาง: '+String(h.email):'',
  '',
  'แผนกที่มี: '+units.length
 ].filter(Boolean);
 const q:any[]=units.slice(0,9).map((x:any)=>pb(
  phmsNormalizeActionLabel('🏢 '+String(x?.code||x?.name||'แผนก')),
  'เปิดฐานแผนก '+String(x?.record_code||'')
 ));
 if(r?.can_edit===true)q.push(pb('✏️ แก้ข้อมูล รพ.','แก้ฐานรพ '+String(h?.record_code||'')));
 q.push(pb('↩️ รายการ รพ.','ข้อมูลสถานพยาบาล'));
 await reply(rt,lines.join('\n'),t,q.slice(0,13))
}
async function replyHealthcareMasterUnit(rt:string,u:string,k:string,id:string,t:string,code:string){
 const r=await healthcareMasterOverview(u,k,id);
 const hs=Array.isArray(r?.hospitals)?r.hospitals:[];
 let h:any=null,u0:any=null;
 for(const x of hs){
  const units=Array.isArray(x?.units)?x.units:[];
  const found=units.find((z:any)=>String(z?.record_code||'')===String(code))||units.find((z:any)=>String(z?.record_code||'').startsWith(String(code)));
  if(found){h=x;u0=found;break}
 }
 if(!u0)throw new Error('healthcare_master_unit_not_found');
 const lines=[
  '🏢 '+String(u0?.name||'แผนก')+(u0?.code?' ('+String(u0.code)+')':''),
  '🏥 '+phmsHospitalShortLabel(h?.hospital_name||'โรงพยาบาล'),
  '',
  '📍 จุด/อาคาร/ชั้น: '+String(u0?.location_detail||'—'),
  '☎️ เบอร์ติดต่อ: '+String(u0?.phone||'—'),
  '✉️ อีเมล: '+String(u0?.email||'—'),
  u0?.contact_note?'🗒 ติดต่อ: '+String(u0.contact_note):'',
  '',
  '🔄 ข้อมูลเลื่อนนัด',
  '☎️ เบอร์: '+String(u0?.reschedule_contact_phone||u0?.phone||'—'),
  '✉️ อีเมล: '+String(u0?.reschedule_contact_email||u0?.email||'—'),
  '🕐 เวลาติดต่อ: '+String(u0?.reschedule_hours_text||'—'),
  '⏳ แจ้งล่วงหน้า: '+healthcareMasterNoticeLabel(u0?.reschedule_min_notice_minutes),
  '📝 วิธี/เงื่อนไข: '+String(u0?.reschedule_instructions||'—')
 ].filter(Boolean);
 const q:any[]=[];
 if(r?.can_edit===true)q.push(pb('✏️ แก้ค่ากลาง','แก้ฐานแผนก '+String(u0?.record_code||'')));
 q.push(pb('↩️ กลับ รพ.','เปิดฐานรพ '+String(h?.record_code||'')));
 await reply(rt,lines.join('\n'),t,q)
}
