/* PHMS_HOME_PERMISSION_LAYOUT_RULE_V1
 Single source of truth for the LINE home screen and its text fallback.
 If a category has no view/create/update/delete right for any accessible person,
 it must not be rendered. Settings and own profile are account-level features,
 not household administration. Never infer finance access from appointment view.
*/
async function phmsHomePermissionSnapshot(u:string,k:string,id:string){
 const resources=['medications','appointments','health'];
 const permissions:any={medications:false,appointments:false,health:false,documents:false,expenses:false};
 const viewed=await Promise.all(resources.map(x=>listAccessibleResourcePeopleAction(u,k,id,x,'view')));
 let hasOther=viewed.some((rows:any)=>Array.isArray(rows)&&rows.some((x:any)=>x?.is_self!==true));
 for(let i=0;i<resources.length;i++){
  permissions[resources[i]]=Array.isArray(viewed[i])&&viewed[i].length>0;
 }
 // View-only checks are insufficient for someone who can add or manage a record
 // without a separate view grant. Check additional actions only for missing tiles.
 for(const action of ['create','update','delete']){
  const missing=resources.filter(x=>permissions[x]!==true);
  if(!missing.length)break;
  const rows=await Promise.all(missing.map(x=>listAccessibleResourcePeopleAction(u,k,id,x,action)));
  for(let i=0;i<missing.length;i++)if(Array.isArray(rows[i])&&rows[i].length>0)permissions[missing[i]]=true;
 }
 try{
  hasOther=hasOther||(await rpc(u,k,'phms_line_has_accessible_other_person',{p_line_user_id:id})===true)
 }catch(err){console.error('home_family_permission_check_failed',String(err))}
 if(permissions.medications||permissions.appointments||permissions.health){
  try{
   const g=one(await rpc(u,k,'phms_list_line_medical_gallery_v2',{
    p_line_user_id:id,p_category:'all',p_days:30,p_limit:1,p_offset:0
   }));
   permissions.documents=!!g&&typeof g==='object'&&g?.flow_state!=='permission_denied'&&g?.can_view!==false;
  }catch(err){console.error('home_documents_permission_check_failed',String(err))}
 }
 if(permissions.appointments){
  try{
   const f=one(await rpc(u,k,'phms_line_appointment_expense_summary',{p_line_user_id:id,p_limit:1}));
   permissions.expenses=!!f&&typeof f==='object'&&f?.flow_state!=='permission_denied'&&f?.can_view_finance!==false;
  }catch(err){console.error('home_finance_permission_check_failed',String(err))}
 }
 return {permissions,hasOther}
}
function phmsHomeVisibleCategories(permissions:any){
 const all=[
  {label:'💊 ยา',data:'ยา',resource:'medications'},
  {label:'📅 นัด',data:'นัดหมาย',resource:'appointments'},
  {label:'🩺 สุขภาพ',data:'สุขภาพ',resource:'health'},
  {label:'📁 เอกสาร',data:'รูปและเอกสาร',resource:'documents'},
  {label:'💰 ค่ารักษา',data:'สรุปค่าใช้จ่ายนัด',resource:'expenses'},
  // All linked users can configure their own account; household settings are
  // separately protected by the canonical owner/admin permission guard.
  {label:'⚙️ ตั้งค่า',data:'ตั้งค่า',resource:'settings'}
 ];
 return all.filter(x=>x.resource==='settings'||permissions?.[x.resource]===true)
}
function phmsHomeCategoryRows(categories:any[]){
 const rows:any[]=[];
 // Slice AFTER permission-filtering. An odd last tile fills the entire row.
 for(let i=0;i<categories.length;i+=2){
  const pair=categories.slice(i,i+2);
  rows.push({type:'box',layout:'horizontal',spacing:'sm',contents:pair.map((x:any)=>({
   type:'button',style:'primary',height:'sm',flex:1,
   action:{type:'postback',label:x.label,data:x.data}
  }))})
 }
 return rows
}
/* AIM_HOME_ACTIONABLE_V2: permission-scoped live alert summary, direct record navigation. */
async function phmsActionableHomeAlerts(u:string,k:string,id:string){
 const ap:any[]=[];
 const personColors=new Map<string,string>();
 try{
  const cp=one(await rpc(u,k,'phms_line_person_card_colors',{p_line_user_id:id}));
  for(const p of Array.isArray(cp?.items)?cp.items:[]){if(p?.person_code&&/^#[0-9a-f]{6}$/i.test(String(p.card_color||'')))personColors.set(String(p.person_code),String(p.card_color))}
 }catch(err){console.error('home_person_color',String(err).slice(0,120))}
 try{
  const x=one(await rpc(u,k,'phms_line_appointment_explorer',{p_line_user_id:id,p_scope:'all',p_mode:'upcoming',p_dimension:null,p_group_key:null,p_limit:100}));
  const now=Date.now();
  for(const a of Array.isArray(x?.items)?x.items:[]){
   const pc=String(a?.person_code||''),rc=String(a?.code||'');
   if(!/^[a-f0-9]{12}$/i.test(pc)||!/^[a-f0-9-]{8,36}$/i.test(rc))continue;
   const date=a?.visit_mode==='walk_in'&&a?.visit_time_known===false&&a?.planned_visit_date?String(a.planned_visit_date)+'T12:00:00+07:00':String(a?.appointment_at||'');
   const time=new Date(date).getTime();
   if(!Number.isFinite(time)||time<now-43200000||time>now+604800000)continue;
   ap.push({type:'appointment',title:'📅 '+phmsPersonCardShortThaiDate(date)+' • '+appointmentCountdownLabel(date),
    person:String(a.person_name||'คนในบ้าน'),personColor:personColors.get(pc)||'',detail:String(a.title||a.care_topic||'นัดพบแพทย์'),hospital:a.hospital_name?phmsHospitalShortLabel(a.hospital_name):'',
    action:'เปิดนัดแจ้งเตือน '+pc+' '+rc,time})
  }
 }catch(err){console.error('home_action_appt',String(err).slice(0,150))}
 ap.sort((a:any,b:any)=>a.time-b.time);
 return ap
}
/* AIM_HOME_ALERT_BUTTON_V3: only real Flex buttons are actionable, never generic box postbacks. */
/* AIM_HOME_TAP_ALERT_V4: compact two-line tappable notice; record action lives on its entire box. */
/* PHMS_HOME_SOFT_ALERT_THEME_V1: keep category identity with an elderly-friendly near-white background. */
function phmsHomeAlertTheme(type:any){
 const key=String(type||'');
 const k:keyof typeof PHMS_CATEGORY_THEME=key==='appointment'?'appointments':key==='medication'?'medications':key==='health'?'health':key==='document'?'documents':key==='expense'?'expenses':'appointments';
 const theme=PHMS_CATEGORY_THEME[k];
 const bg=theme.background;
 const blend=(v:number)=>Math.round(v*0.35+255*0.65).toString(16).padStart(2,'0');
 const soft=/^#[0-9a-f]{6}$/i.test(bg)?'#'+[1,3,5].map(i=>blend(parseInt(bg.slice(i,i+2),16))).join('').toUpperCase():'#F8FAFC';
 return {background:k==='appointments'?'#FFFBF1':soft,color:theme.color};
}
function phmsActionableAlertRow(a:any,showHint=false){
 const appointment=String(a?.type||'')==='appointment';
 const theme=phmsHomeAlertTheme(a?.type);
 return {type:'box',layout:'horizontal',alignItems:'center',spacing:'sm',
  paddingAll:'12px',cornerRadius:'lg',backgroundColor:theme.background,
  action:{type:'postback',label:appointment?'📅 ดูนัดนี้':'🔎 ดูเรื่องนี้',
   data:String(a.action||''),displayText:appointment?'📅 ดูนัดนี้':'🔎 ดูเรื่องนี้'},
  contents:[
   {type:'box',layout:'vertical',flex:10,spacing:'xs',contents:[
    {type:'text',text:String(a.title||''),size:'md',weight:'bold',color:'#263649',wrap:true,maxLines:2},
    {type:'box',layout:'horizontal',alignItems:'center',spacing:'sm',contents:[
     ...(/^#[0-9a-f]{6}$/i.test(String(a.personColor||''))?[{type:'text',text:'●',size:'md',color:String(a.personColor),flex:0}]:[]),
     {type:'text',text:String(a.person||'คนในบ้าน'),size:'md',weight:'bold',color:'#263649',wrap:true,maxLines:1,flex:1}
    ]},
    {type:'text',text:'นัดเพื่อ: '+String(a.detail||'นัดพบแพทย์'),size:'sm',color:'#344054',wrap:true,maxLines:2},
    ...(appointment&&a.hospital?[{type:'text',text:'🏥 '+String(a.hospital),size:'sm',color:'#475569',wrap:true,maxLines:2}]:[]),
    ...(appointment&&showHint?[{type:'text',text:'แตะเพื่อดูรายละเอียดนัด',size:'xs',color:'#315E7A',wrap:true,maxLines:1}]:[])
   ]},
   {type:'text',text:'›',size:'xl',color:theme.color,align:'end',flex:1}
  ]}
}

async function replyHomeAllAlerts(rt:string,u:string,k:string,id:string,t:string,page=0){
 const items=await phmsActionableHomeAlerts(u,k,id),size=7,offset=Math.max(0,Math.floor(page))*size;
 if(!items.length){await reply(rt,'🔔 ตอนนี้ไม่มีเรื่องที่ต้องติดตาม',t,[pb('🏡 หน้าเริ่มต้น','กลับหน้าเริ่มต้น')]);return}
 const rows=items.slice(offset,offset+size).map(x=>phmsActionableAlertRow(x));
 const nav:any[]=[];
 if(offset>0)nav.push({type:'button',action:{type:'postback',label:'⬅️ ก่อนหน้า',data:'ดูเรื่องสำคัญทั้งหมด '+String(Math.max(0,page-1))}});
 if(offset+size<items.length)nav.push({type:'button',action:{type:'postback',label:'➡️ ถัดไป',data:'ดูเรื่องสำคัญทั้งหมด '+String(page+1)}});
 nav.push({type:'button',action:{type:'postback',label:'↩️ หน้าเริ่มต้น',data:'กลับหน้าเริ่มต้น'}});
 await replyMessages(rt,t,[{type:'flex',altText:'🔔 เรื่องสำคัญทั้งหมด',contents:{type:'bubble',size:'mega',
  header:{type:'box',layout:'vertical',backgroundColor:'#E8F1FA',paddingAll:'16px',contents:[
   {type:'text',text:'🔔 เรื่องสำคัญทั้งหมด',size:'lg',weight:'bold',color:'#284F76'},
   {type:'text',text:'รายการ '+String(Math.min(offset+1,items.length))+'–'+String(Math.min(offset+size,items.length))+' จาก '+String(items.length),size:'sm',color:'#536A79',margin:'sm'}]},
  body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'14px',contents:rows},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'10px',contents:nav}}}])
}
async function phmsVisibleFamilyCount(u:string,k:string,id:string):Promise<number>{
 try{const x=await rpc(u,k,'phms_list_line_context_families',{p_line_user_id:id});return Array.isArray(x)?x.length:0}catch(err){console.error('phms_visible_family_count',String(err));return 0}
}
/* PHMS_HOME_ADMIN_MANAGEMENT_TEMP_GATE_V1
 Display the home management shortcut only for the acting LINE account's
 ACTIVE household role in the selected family (owner/admin).
 Fail closed; this is UI visibility, never a replacement for resource permissions.
 */
async function phmsHomeAdminManagementAllowed(u:string,k:string,id:string):Promise<boolean>{
 try{
  const context=one(await rpc(u,k,'phms_get_line_context_state',{p_line_user_id:id}));
  const userId=String(context?.user_id||'');
  if(!/^[0-9a-f-]{36}$/i.test(userId))return false;
  const familyRows=await rpc(u,k,'phms_list_line_context_families',{p_line_user_id:id});
  const families=Array.isArray(familyRows)?familyRows:[];
  const activeId=String(context?.active_family_id||'');
  const selected=families.find((f:any)=>String(f?.family_id||'')===activeId)||
    (families.length===1?families[0]:null);
  const familyId=String(selected?.family_id||'');
  if(!/^[0-9a-f-]{36}$/i.test(familyId))return false;
  const params=new URLSearchParams({
   select:'role',user_id:'eq.'+userId,family_id:'eq.'+familyId,
   status:'eq.active',role:'in.(owner,admin)',limit:'1'
  });
  const res=await fetch(u+'/rest/v1/family_role_assignments?'+params.toString(),{
   headers:{apikey:k,Authorization:'Bearer '+k}
  });
  if(!res.ok){console.error('phms_home_admin_gate_read',res.status);return false}
  const roles=await res.json();
  return Array.isArray(roles)&&roles.some((r:any)=>r?.role==='owner'||r?.role==='admin');
 }catch(err){console.error('phms_home_admin_gate_error',String(err).slice(0,140));return false}
}

