/* PHMS_PRIMARY_DATA_DIRECT_OPEN_V1
   กฎกลาง: เมนูข้อมูลหลักต้องเปิดข้อมูลทันทีเมื่อระบบระบุเจ้าของข้อมูลได้อย่างปลอดภัย
   - อยู่หน้าเริ่มต้น -> personal context -> เปิดข้อมูลของฉัน
   - อยู่หน้าบุคคล -> รักษา person context -> เปิดข้อมูลของคนนั้น
   - ไม่มี context -> ใช้ "ฉัน" ถ้ามีสิทธิ์; ถ้ามีเป้าหมายเดียวให้เลือกอัตโนมัติ
   - ถ้ายังคลุมเครือจริง ๆ เท่านั้นจึงเปิดหน้ารายชื่อให้เลือก
*/
function phmsDedupAccessiblePeople(rows:any[]){
 const out:any[]=[];const seen=new Set<string>();
 for(const x of (Array.isArray(rows)?rows:[])){
  const key=String(x?.person_id||x?.family_person_id||x?.person_selection_code||'');
  if(!key||seen.has(key))continue;
  seen.add(key);out.push(x)
 }
 return out
}
async function phmsSelectAccessiblePerson(u:string,k:string,id:string,row:any){
 if(row?.is_self===true){
  await rpc(u,k,'phms_set_line_personal_context',{p_line_user_id:id});
  return
 }
 if(row?.family_selection_code){
  await rpc(u,k,'phms_select_line_context_family',{p_line_user_id:id,p_selection_code:String(row.family_selection_code)})
 }
 if(row?.person_selection_code){
  await rpc(u,k,'phms_select_line_context_person',{p_line_user_id:id,p_selection_code:String(row.person_selection_code)})
 }
}
async function phmsRenderPrimaryResource(rt:string,u:string,k:string,id:string,t:string,resource:string){
 if(resource==='appointments'){await appointmentCards(rt,u,k,id,t);return}
 if(resource==='medications'){await medicationCards(rt,u,k,id,t,0);return}
 await healthCards(rt,u,k,id,t,0)
}
async function phmsOpenPrimaryResourceDirect(rt:string,u:string,k:string,id:string,t:string,resource:string){
 const commandKey=resource==='appointments'?'appointments':resource==='medications'?'medications':'health';
 let prep:any=null;
 try{
  prep=one(await rpc(u,k,'phms_prepare_line_main_command',{p_line_user_id:id,p_command_key:commandKey}))
 }catch(err){
  console.error('primary_direct_prepare',resource,String(err))
 }
 if(prep?.flow_state==='ready'){
  await phmsRenderPrimaryResource(rt,u,k,id,t,resource);
  return
 }
 const rows=phmsDedupAccessiblePeople(await listAccessibleResourcePeopleAction(u,k,id,resource,'view'));
 if(!rows.length){
  await phmsRenderPrimaryResource(rt,u,k,id,t,resource);
  return
 }
 const self=rows.find((x:any)=>x?.is_self===true);
 if(self){
  await phmsSelectAccessiblePerson(u,k,id,self);
  await phmsRenderPrimaryResource(rt,u,k,id,t,resource);
  return
 }
 if(rows.length===1){
  await phmsSelectAccessiblePerson(u,k,id,rows[0]);
  await phmsRenderPrimaryResource(rt,u,k,id,t,resource);
  return
 }
 await replyResourcePersonPicker(rt,u,k,id,t,resource,0)
}

async function listGalleryCreatablePeople(u:string,k:string,id:string){
 const groups=await Promise.all([
  listAccessibleResourcePeopleAction(u,k,id,'appointments','create'),
  listAccessibleResourcePeopleAction(u,k,id,'medications','create'),
  listAccessibleResourcePeopleAction(u,k,id,'health','create')
 ]);
 const map=new Map<string,any>();
 for(const rows of groups)for(const x of rows){
  const key=String(x.family_id||'')+':'+String(x.family_person_id||'');
  if(!map.has(key))map.set(key,x)
 }
 return [...map.values()]
}
