function correctionSegment(text:string,re:RegExp){
 const m=text.match(re);if(!m)return undefined;
 return String(m[1]||'').trim().replace(/[|,;]+$/,'').trim()||undefined
}
function parseAppointmentCorrection(text:string,current:any):AppointmentPartial{
 const s=stripCorrectionPrefix(String(text||'').replace(/[“”"]/g,' ').replace(/\s+/g,' ').trim());
 if(/หมายเหตุ(?:เฉพาะ)?ผู้ดูแล\s*[:：=]/.test(s))throw new Error('private_caregiver_note_requires_separate_flow');
 const out:AppointmentPartial={};

 const date=parseAppointmentDate(s),time=parseAppointmentTime(s);
 if(date)out.date=date;if(time)out.time=time;

 const boundary='(?=\\s+(?:แผนก|คลินิก|หมอ|นพ\\.?|พญ\\.?|แพทย์|รายละเอียดนัด|รายละเอียดของนัด|รายละเอียด|หมายเหตุ|รพ\\.\\/คลินิก|สถานพยาบาล|โรงพยาบาล|รพ\\.?|วัน(?:ที่)?|เวลา)|$)';

 let m=s.match(new RegExp('(รพ\\.\\/คลินิก|สถานพยาบาล|โรงพยาบาล|รพ\\.?)\\s*(?:เป็น|คือ|:|=)?\\s*([^\\n]+?)'+boundary,'i'));
 if(m){
   let v=String(m[2]||'').trim();
   if(v){
     if(/^รพ\.\/คลินิก$/i.test(m[1]))v=v.replace(/^\/?คลินิก\s*[:：]?/i,'').trim();
      else if(/^รพ/i.test(m[1]))v='รพ.'+v.replace(/^รพ\.?\s*/i,'');
     else if(/^โรงพยาบาล/i.test(m[1]))v='โรงพยาบาล '+v.replace(/^โรงพยาบาล\s*/i,'');
     out.hospital_name=v.trim()
   }
 }

 m=s.match(new RegExp('(?:แผนก|คลินิก)\\s*(?:เป็น|คือ|:|=)?\\s*([^\\n]+?)'+boundary,'i'));
 if(m){
   let v=String(m[1]||'').trim().replace(/^คลินิก\s*/,'');
   if(v)out.department=normalizeAppointmentDepartmentInput(v)
 }

 m=s.match(new RegExp('(แพทย์หญิง|นายแพทย์|พ\\.?\\s*ญ\\.?|น\\.?\\s*พ\\.?|หมอ|แพทย์)\\s*(?:ชื่อ|เป็น|คือ|:|=)?\\s*([^\\n]+?)'+boundary,'i'));
 if(m){
   const v=String(m[2]||'').trim().replace(/^ชื่อ\s*/,'');
   if(v&&!/^(?:นัด|ตรวจ|ปัสสาวะ)/.test(v))out.doctor_name=normalizeAppointmentDoctorInput(String(m[1]||'')+' '+v)
 }

 m=s.match(new RegExp('(?:รายละเอียดนัด|รายละเอียดของนัด|นัดหมาย)\\s*(?:เป็น|คือ|:|=)?\\s*([^\\n]+?)'+boundary,'i'));
 if(m){
   const v=String(m[1]||'').trim();
   if(v)out.title=v
 }else{
   m=s.match(new RegExp('(?:^|\\s)นัด\\s*(?:เป็น|คือ|:|=)\\s*([^\\n]+?)'+boundary,'i'));
   if(m){const v=String(m[1]||'').trim();if(v)out.title=v}
 }

 m=s.match(/(?:เพิ่ม\s*)?หมายเหตุ(?:ทั่วไป)?\s*(?:เป็น|คือ|:|=)?\s*(.+)$/i);
 if(m){const v=String(m[1]||'').trim();if(v)out.note=v}

 m=s.match(/(?:สิทธิ(?:์|การรักษา)?|ใช้สิทธิ)\s*(?:เป็น|คือ|:|=)?\s*([^\n]+?)(?=\s+(?:สถานพยาบาล|โรงพยาบาล|รพ\.?|แผนก|คลินิก|หมอ|แพทย์|จุด|อาคาร|ตึก|ชั้น|ห้อง|หมายเหตุ|เตรียม|งด)|$)/i);
 if(m){const v=String(m[1]||'').trim();if(v)out.coverage_type=v}
 m=s.match(/(?:จุดนัด|สถานที่ย่อย|สถานที่|อาคาร|ตึก|ชั้น|ห้อง|เคาน์เตอร์)\s*(?:เป็น|คือ|:|=)?\s*([^\n]+?)(?=\s+(?:สถานพยาบาล|โรงพยาบาล|รพ\.?|แผนก|คลินิก|หมอ|แพทย์|สิทธิ|หมายเหตุ|เตรียม|งด)|$)/i);
 if(m){const v=String(m[1]||'').trim();if(v)out.location_detail=v}
 m=s.match(/(?:เบอร์(?:ติดต่อ)?|โทร(?:ศัพท์)?|ติดต่อ)\s*(?:เป็น|คือ|:|=)?\s*(0\d(?:[\d\s-]{7,13}\d))/i);
 if(m){out.contact_phone=String(m[1]||'').replace(/\s+/g,' ').trim()}
 m=s.match(/(?:อีเมล|email|mail)\s*(?:เป็น|คือ|:|=)?\s*([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i);
 if(m)out.contact_email=String(m[1]||'').toLowerCase();
 m=s.match(/(?:การเตรียมตัว|เตรียมตัว|คำแนะนำก่อนนัด)\s*(?:เป็น|คือ|:|=)?\s*(.+)$/i);
 if(m){const v=String(m[1]||'').trim();if(v)out.preparation_notes=normalizeAppointmentPreparationInput(v)}
 m=s.match(/(?:\bHN\b|เลข\s*HN|เลขผู้ป่วย)\s*(?:เป็น|คือ|:|=)?\s*([A-Z0-9\/-]{2,40})/i);
 if(m)out.hospital_hn=String(m[1]).trim();
 m=s.match(/(?:\bVN\b|เลข\s*VN|เลขเยี่ยม|เลขครั้งรับบริการ)\s*(?:เป็น|คือ|:|=)?\s*([A-Z0-9\/-]{2,40})/i);
 if(m)out.hospital_vn=String(m[1]).trim();
 m=s.match(/(?:เรื่องที่รักษา|กลุ่มการรักษา\/โรค|กลุ่มการรักษา|หัวข้อการรักษา|โรค\/ปัญหา)\s*(?:เป็น|คือ|:|=)?\s*([^\n|;]+)/i);
 if(m){const v=String(m[1]||'').trim();if(v)out.care_topic=v}
 m=s.match(/(?:มาก่อนเวลานัด|ต้องไปถึงก่อนเวลานัด|ควรมาถึงก่อน|มาถึงก่อน|มาก่อน)\s*(?:เป็น|คือ|:|=)?\s*([^\n|;]+)/i);
 if(m){const n=parseAppointmentArrivalLead(m[1]);if(n!==undefined)out.arrival_lead_minutes=n}
 m=s.match(/(?:สถานะนัด|บันทึกเป็น)\s*(?:เป็น|คือ|:|=)?\s*([^\n|;]+)/i);
 if(m){const st=parseAppointmentHistoricalStatus(m[1]);if(st)out.status=st}
 if(/(?:follow[- ]?up|นัดติดตาม|นัดต่อ|ติดตามอาการ|โรคประจำตัว)/i.test(s))out.appointment_type='follow_up';
 if(/โรคประจำตัว/.test(s))out.followup_kind='chronic_routine';
 if(/walk[- ]?in|วอล์กอิน|ไม่ได้นัด|ไปพบเอง|คิว(?:นัด)?เต็ม/i.test(s))out.visit_mode='walk_in';
 if(/คิว(?:นัด)?เต็ม/.test(s))out.walk_in_reason='queue_full';

 // Common natural correction: "แก้เป็น ...", with no labels for every field.
 const fallback=parseAppointmentFreeText(s);
 for(const [k,v] of Object.entries(fallback)){
   if((out as any)[k]==null&&v!=null&&
      (k==='date'||k==='time'||k==='hospital_name'||k==='department'||k==='doctor_name'||k==='note'||k==='location_detail'||k==='contact_phone'||k==='contact_email'||k==='coverage_type'||k==='preparation_notes'||k==='appointment_type'||k==='visit_mode'||k==='walk_in_reason'||k==='followup_kind'||k==='followup_interval_months'||k==='hospital_hn'||k==='hospital_vn'||k==='arrival_lead_minutes'||k==='care_topic'||k==='status')){
     (out as any)[k]=v
   }
 }

 // Preserve the old title unless the user explicitly changed appointment/detail wording.
 if(!out.title&&/(?:รายละเอียดนัด|รายละเอียดของนัด|นัดหมาย\s*(?:เป็น|คือ|:|=)|(?:^|\s)นัด\s*(?:เป็น|คือ|:|=))/i.test(s)){
   const x=s.match(/(?:รายละเอียดนัด|รายละเอียดของนัด|นัดหมาย|(?:^|\s)นัด)\s*(?:เป็น|คือ|:|=)\s*(.+)$/i)?.[1];
   if(x)out.title=String(x).trim()
 }

 return out
}
function appointmentChangedFields(before:any,after:any){
 const keys=['date','time','title','hospital_name','hospital_hn','hospital_vn','care_topic','department','doctor_name','arrival_lead_minutes','note','location_detail','contact_phone','contact_email','coverage_type','preparation_notes','appointment_type','status'];
 const labels:any={date:'วันนัด',time:'เวลา',title:'รายละเอียดนัด',hospital_name:'โรงพยาบาล',hospital_hn:'HN',hospital_vn:'VN',care_topic:'โรค/เรื่องรักษา',department:'แผนก',doctor_name:'หมอ',arrival_lead_minutes:'มาก่อนเวลานัด',note:'หมายเหตุ',location_detail:'จุด/อาคาร/ชั้น',contact_phone:'เบอร์ติดต่อ',contact_email:'อีเมลติดต่อ',coverage_type:'สิทธิรักษา',preparation_notes:'การเตรียมตัว',appointment_type:'ประเภทนัด',status:'สถานะนัด'};
 return keys.filter(k=>String(before?.[k]??'')!==String(after?.[k]??'')).map(k=>labels[k])
}

const APPOINTMENT_EDIT_FIELDS=['date','time','planned_visit_date','visit_time','walk_in_reason','walk_in_note','title','appointment_type','hospital_name','hospital_hn','hospital_vn','care_topic','department','doctor_name','arrival_lead_minutes','location_detail','coverage_type','preparation_notes','note'] as const;
function appointmentEditFieldLabel(field:string){
 const m:any={
  date:'วันนัด',time:'เวลา',planned_visit_date:'วันที่จะไป',visit_time:'เวลา Walk-in',walk_in_reason:'เหตุผล Walk-in',walk_in_note:'อาการ/เหตุผลก่อนนัด',title:'นัดเพื่อ',appointment_type:'ประเภทนัด',hospital_name:'โรงพยาบาล',hospital_hn:'HN',hospital_vn:'VN',
  care_topic:'โรค/เรื่องรักษา',department:'แผนก',doctor_name:'หมอ',arrival_lead_minutes:'มาก่อนเวลานัด',location_detail:'จุดนัด / อาคาร / ชั้น',
  coverage_type:'สิทธิรักษา',preparation_notes:'การเตรียมตัว',contact_phone:'เบอร์ติดต่อ',
  contact_email:'อีเมล',note:'หมายเหตุ'
 };
 return m[field]||field
}
function appointmentEditCurrentValue(field:string,p:any){
 if(field==='doctor_name'&&p?.visit_mode==='walk_in')return appointmentWalkInDoctorLabel(p);
 if(field==='date')return p?.date||'—';
 if(field==='time')return p?.time||'—';
 if(field==='planned_visit_date')return appointmentTemplateDate(p?.planned_visit_date)||'—';
 if(field==='visit_time')return p?.visit_time_known===false?'ยังไม่ทราบเวลา':(p?.time||'—');
 if(field==='walk_in_reason')return appointmentWalkInReasonLabel(p?.walk_in_reason);
 if(field==='walk_in_note')return p?.walk_in_note||'—';
 if(field==='arrival_lead_minutes')return Number(p?.arrival_lead_minutes||0)>0?String(p.arrival_lead_minutes)+' นาที':'—';
 return p?.[field]||'—'
}
function appointmentSingleFieldPatch(field:string,input:string):AppointmentPartial{
 const raw=String(input||'').trim().replace(/^[“”"]|[“”"]$/g,'');
 const out:any={};
 if(!APPOINTMENT_EDIT_FIELDS.includes(field as any))throw new Error('unsupported_appointment_edit_field');
 if(!raw)throw new Error('appointment_edit_value_required');

 if(field==='planned_visit_date'){
   const v=parseAppointmentDate(raw);if(!v)throw new Error('appointment_edit_invalid_date');out.planned_visit_date=v;return out
 }
 if(field==='visit_time'){
   if(/^(?:unknown|ไม่ทราบ|ยังไม่ทราบ|ยังไม่รู้|-|—)$/i.test(raw)){out.visit_time='unknown';return out}
   const v=parseAppointmentTime(raw);if(!v)throw new Error('appointment_edit_invalid_time');out.visit_time=v;return out
 }
 if(field==='walk_in_reason'){
   const s=raw.toLowerCase();
   const v=['queue_full','hospital_advised','no_booking','urgent','other'].includes(s)?s:
    /คิว.*เต็ม/.test(raw)?'queue_full':
    /(?:รพ|โรงพยาบาล|หมอ|แพทย์).*(?:ให้|บอก|แนะนำ)/.test(raw)?'hospital_advised':
    /(?:ไม่ได้จอง|ไม่ได้นัด|ไม่มีนัด)/.test(raw)?'no_booking':
    /(?:อาการ|ผิดปกติ|ด่วน|เร่ง|รีบ|ก่อนนัด)/.test(raw)?'urgent':
    /อื่น/.test(raw)?'other':'';
   if(!v)throw new Error('invalid_walkin_reason');
   out.walk_in_reason=v;return out
 }
 if(field==='walk_in_note'){
   out.walk_in_note=/^(?:-|—|ลบ|ไม่มี)$/i.test(raw)?'':raw;return out
 }
 if(field==='appointment_type'){
   const v=normalizeAppointmentTypeInput(raw);
   if(!v)throw new Error('appointment_edit_invalid_type');
   out.appointment_type=v;return out
 }
 if(field==='date'){
   const v=parseAppointmentDate(raw);if(!v)throw new Error('appointment_edit_invalid_date');out.date=v;return out
 }
 if(field==='time'){
   const v=parseAppointmentTime(raw);if(!v)throw new Error('appointment_edit_invalid_time');out.time=v;return out
 }
 if(field==='arrival_lead_minutes'){
   const n=parseAppointmentArrivalLead(raw);if(n===undefined)throw new Error('appointment_edit_invalid_arrival_lead');
   out.arrival_lead_minutes=n;return out
 }
 if(field==='hospital_hn'){
   const v=raw.replace(/^(?:HN|เลข\s*HN|เลขผู้ป่วย)\s*[:：]?\s*/i,'').trim();
   if(v.length<2)throw new Error('appointment_edit_value_required');
   out.hospital_hn=v;return out
 }
 if(field==='hospital_vn'){
   const v=raw.replace(/^(?:VN|เลข\s*VN|เลขเยี่ยม|เลขครั้งรับบริการ)\s*[:：]?\s*/i,'').trim();
   if(v.length<2)throw new Error('appointment_edit_value_required');
   out.hospital_vn=v;return out
 }
 if(field==='care_topic'){
   const v=raw.replace(/^(?:กลุ่มการรักษา\/โรค|กลุ่มการรักษา|โรค\/ปัญหา)\s*[:：]?\s*/i,'').trim();
   if(v.length<2)throw new Error('appointment_edit_value_required');
   out.care_topic=v;return out
 }
 if(field==='contact_email'){
   const m=raw.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
   if(!m)throw new Error('appointment_edit_invalid_email');
   out.contact_email=String(m[0]).toLowerCase();return out
 }
 if(field==='contact_phone'){
   const m=raw.match(/0\d(?:[\d\s-]{7,13}\d)/);
   if(!m)throw new Error('appointment_edit_invalid_phone');
   out.contact_phone=String(m[0]).replace(/\s+/g,' ').trim();return out
 }
 if(field==='doctor_name'){
   const v=normalizeAppointmentDoctorInput(raw);
   const nameOnly=v.replace(/^(?:นพ\.|พญ\.)\s*/,'').trim();
   if(nameOnly.length<2)throw new Error('appointment_edit_value_required');
   out.doctor_name=v;return out
 }
 if(field==='department'){
   const v=normalizeAppointmentDepartmentInput(raw);
   if(v.length<2)throw new Error('appointment_edit_value_required');
   out.department=v;return out
 }
 if(field==='hospital_name'){
   const v=canonicalAppointmentHospitalInput(raw);
   if(v.length<2)throw new Error('appointment_edit_value_required');
   out.hospital_name=v;return out
 }
 if(field==='preparation_notes'){
   const v=normalizeAppointmentPreparationInput(raw);
   if(v.length<2)throw new Error('appointment_edit_value_required');
   out.preparation_notes=v;return out
 }
 if(field==='title'){
   const v=raw.replace(/^(?:นัด|รายละเอียดนัด)\s*[:：]?\s*/i,'').trim();
   if(v.length<2)throw new Error('appointment_edit_value_required');
   out.title=v;return out
 }
 out[field]=raw;
 return out
}
