function appointmentRoleLabel(v:any){
 return ({booker:'คนประสานงานนัด',caregiver:'ผู้ดูแลวันนัด',driver:'คนขับรถ / คนพาไป',companion:'คนไปด้วย',responsible:'ผู้รับผิดชอบหลัก',other:'หน้าที่อื่น'} as any)[String(v||'')]||String(v||'ผู้รับผิดชอบ')
}
function appointmentAssigneeStatusLabel(v:any){
 return ({assigned:'รอรับทราบ',accepted:'รับทราบแล้ว',declined:'รับไม่ได้',removed:'ถอดออกแล้ว'} as any)[String(v||'')]||String(v||'-')
}
function appointmentStatusLabel(v:any){
 return ({planned:'วางแผนจะไป',scheduled:'รอยืนยันนัด',confirmed:'ยืนยันแล้ว',arrived:'ถึงสถานพยาบาลแล้ว',completed:'จบนัดแล้ว',cancelled:'ยกเลิก',no_show:'ไม่ได้ไปตามนัด',rescheduled:'เลื่อนนัด'} as any)[String(v||'')]||String(v||'-')
}
function appointmentAckStatusLabel(v:any){
 return ({pending:'รอรับทราบ',requested:'รอรับทราบ',acknowledged:'รับทราบแล้ว',accepted:'รับทราบแล้ว',declined:'รับไม่ได้',cancelled:'ยกเลิกแล้ว'} as any)[String(v||'')]||String(v||'-')
}
function appointmentReminderDisplayLabel(offsets:any,post:any,postTime:any=null){
 const xs=Array.isArray(offsets)?offsets.map((x:any)=>Number(x)).filter((x:number)=>Number.isFinite(x)).sort((a:number,b:number)=>b-a):[];
 const before=xs.length?xs.map((m:number)=>m%1440===0?(m/1440)+' วัน':m%60===0?(m/60)+' ชั่วโมง':m+' นาที').join(' + '):'ปิดเตือนก่อนนัด';
 const time=String(postTime||'').slice(0,5),p=Number(post);
 const after=time?(time+' น. ของวันนัด'):Number.isFinite(p)&&p>0?(p%60===0?(p/60)+' ชั่วโมงหลังนัด':p+' นาทีหลังนัด'):'ปิด';
 return before+' • บันทึกหลังนัด '+after
}
function appointmentPostVisitEligible(item:any){
 return String(item?.status||'scheduled')==='completed'
}
function appointmentWorkspaceText(w:any){
 const x=w?.item||{},who=String(w?.person_name||'ผู้ใช้');
 const isWalkIn=String(x?.visit_mode||'')==='walk_in';
 const walkInDate=x?.planned_visit_date?String(x.planned_visit_date)+'T12:00:00+07:00':x?.appointment_at;
 const ass=Array.isArray(w?.assignees)?w.assignees:[];
 const docs=Array.isArray(w?.documents)?w.documents:[];
 const tasks=Array.isArray(w?.tasks)?w.tasks:[];
 const pendingTasks=tasks.filter((q:any)=>q?.status==='pending');
 const taskLines=tasks.map((q:any)=>{
  const mark=q?.status==='completed'?'☑️':q?.status==='skipped'?'↪️':'⬜';
  const done=q?.status==='completed'&&q?.completed_at?' • เสร็จ '+crudDate(q.completed_at):'';
  return mark+' '+String(q?.title||'รายการเตรียมตัว')+(q?.instruction?' — '+String(q.instruction):'')+done
 });
 const roleLine=(role:string,icon:string,label:string)=>{
  const xs=ass.filter((a:any)=>String(a?.role||'')===role);
  return xs.length?icon+' '+label+': '+xs.map((a:any)=>String(a?.display_name||'ผู้ใช้')+' — '+appointmentAssigneeStatusLabel(a?.status)).join(' • '):''
 };
 const assLines=[
  roleLine('responsible','✅','ผู้รับผิดชอบหลัก'),
  roleLine('caregiver','🧑‍⚕️','ผู้ดูแลวันนัด'),
  roleLine('driver','🚗','คนขับรถ / คนพาไป'),
  roleLine('companion','🤝','คนไปด้วย'),
  roleLine('booker','☎️','คนประสานงานนัด'),
  roleLine('other','👤','หน้าที่อื่น')
 ].filter(Boolean);
 const offs=Array.isArray(x?.reminder_offsets_minutes)?x.reminder_offsets_minutes:[];
 const before=offs.length?offs.map((m:any)=>Number(m)%1440===0?(Number(m)/1440)+' วัน':Number(m)%60===0?(Number(m)/60)+' ชม.':Number(m)+' นาที').join(' + '):'ปิด';
 let after='ปิด';
 if(x?.post_visit_followup_time_local)after='20:00 น. ของวันนัด';
 else if(Number(x?.post_visit_followup_minutes||0)>0){
  const p=Number(x.post_visit_followup_minutes);after=p%60===0?(p/60)+' ชม. หลังนัด':p+' นาทีหลังนัด'
 }
 const lines=[
  '📅 นัดของ '+who,
  '',
  '📌 นัดเพื่อ: '+String(x?.title||'นัดหมาย'),
  '📆 '+(isWalkIn?'วันที่จะไป':'วันนัด')+': '+appointmentDateOnlyLabel(isWalkIn?walkInDate:x?.appointment_at),
  '🕐 เวลา: '+(isWalkIn&&x?.visit_time_known===false?'ยังไม่ทราบเวลา':appointmentTimeOnlyLabel(x?.appointment_at)),
  ...(isWalkIn?['🚶 วิธีไป: Walk-in',
    ...(x?.walk_in_reason?['🏥 เหตุผล Walk-in: '+appointmentWalkInReasonLabel(x.walk_in_reason)]:[]),
    ...(x?.walk_in_note?['📝 อาการ/เหตุผล: '+String(x.walk_in_note)]:[])
  ]:[]),
  ...(x?.hospital_name?['🏥 รพ./คลินิก: '+phmsHospitalShortLabel(x.hospital_name)]:[]),
  ...(x?.hospital_hn?['🆔 HN: '+String(x.hospital_hn)]:[]),
  ...(x?.hospital_vn?['🔢 VN: '+String(x.hospital_vn)]:[]),
  ...(x?.care_topic?[String(x?.followup_kind||'')==='chronic_routine'?'🩺 โรคประจำตัวที่ติดตาม: '+String(x.care_topic):'🧭 เรื่องที่รักษา: '+String(x.care_topic)]:[]),
  ...(x?.department?['🏢 แผนก/คลินิก: '+String(x.department)]:[]),
  ...(isWalkIn?['👨‍⚕️ แพทย์ Walk-in: '+appointmentWalkInDoctorLabel(x)]:(x?.doctor_name?[appointmentDoctorEmoji(x.doctor_name)+' แพทย์: '+appointmentDoctorLabel(x.doctor_name)]:[])),
  ...(x?.location_detail?['📍 จุดนัด: '+String(x.location_detail)]:[]),
  ...(Number(x?.arrival_lead_minutes||0)>0?['⏱️ มาก่อนเวลานัด: '+String(x.arrival_lead_minutes)+' นาที']:[]),
  ...(x?.coverage_type?['🪪 สิทธิรักษา: '+String(x.coverage_type)]:[]),
  '',
  '✅ สถานะ: '+appointmentStatusLabel(x?.status),
  '',
  '👥 คนที่เกี่ยวข้องวันนัด',
  ...(assLines.length?assLines:['— ยังไม่ได้มอบหมาย']),
  '',
  '⏰ เตือนก่อนนัด: '+before,
  '📝 เตือนบันทึกหลังนัด: '+after,
  '📎 เอกสารของนัด: '+docs.length+' รายการ',
  '✅ เตรียมก่อนนัด: '+(tasks.length-pendingTasks.length)+'/'+tasks.length+' เสร็จ',
  ...(taskLines.length?['','🧾 รายการที่ต้องเตรียม',...taskLines]:[])
 ];
 if(x?.preparation_notes)lines.push('📝 คำแนะนำเพิ่มเติม: '+String(x.preparation_notes));
 if(x?.note)lines.push('🗒 หมายเหตุ: '+String(x.note));
 if(x?.diagnosis_summary||x?.treatment_summary||x?.next_steps||x?.medication_plan_notes||x?.test_results_summary){
  lines.push('','🩺 สรุปหลังนัด');
  if(x?.diagnosis_summary)lines.push('🔎 วินิจฉัย/ความเห็นแพทย์: '+String(x.diagnosis_summary));
  if(x?.treatment_summary)lines.push('🩹 การรักษาครั้งนี้: '+String(x.treatment_summary));
  if(x?.next_steps)lines.push('➡️ ต้องทำต่อ: '+String(x.next_steps));
  if(x?.medication_plan_notes)lines.push('💊 ยา/การเปลี่ยนยา: '+String(x.medication_plan_notes));
  if(x?.test_results_summary)lines.push('🧪 ผลตรวจ: '+String(x.test_results_summary))
 }
 return lines.join('\n')
}

async function appointmentShareOwnerName(u:string,k:string,w:any){
 if(w?.access?.has_person_view!==true)throw new Error('appointment_share_person_view_required');
 const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
 let pid=String(w?.item?.person_id||w?.person_id||w?.person?.id||'').trim();
 if(!uuid.test(pid)){
   const aid=String(w?.item?.id||w?.appointment_id||'').trim();
   if(uuid.test(aid)){
     const r=await fetch(u+'/rest/v1/appointments?id=eq.'+encodeURIComponent(aid)+'&select=person_id&limit=1',{headers:H(k)});
     if(!r.ok)throw new Error('appointment_share_appointment_lookup_failed');
     const xs=await r.json().catch(()=>[]);pid=String(Array.isArray(xs)?xs?.[0]?.person_id||'':'').trim()
   }
 }
 if(!uuid.test(pid)){
   const fid=String(w?.item?.family_person_id||w?.family_person_id||'').trim();
   if(uuid.test(fid)){
     const r=await fetch(u+'/rest/v1/family_persons?id=eq.'+encodeURIComponent(fid)+'&select=person_id&limit=1',{headers:H(k)});
     if(!r.ok)throw new Error('appointment_share_family_person_lookup_failed');
     const xs=await r.json().catch(()=>[]);pid=String(Array.isArray(xs)?xs?.[0]?.person_id||'':'').trim()
   }
 }
 if(!uuid.test(pid))throw new Error('appointment_share_person_id_unavailable');
 const r=await fetch(u+'/rest/v1/persons?id=eq.'+encodeURIComponent(pid)+'&select=first_name,last_name&limit=1',{headers:H(k)});
 if(!r.ok)throw new Error('appointment_share_legal_name_lookup_failed');
 const xs=await r.json().catch(()=>[]),p=Array.isArray(xs)?xs?.[0]||{}:{};
 const first=String(p?.first_name||'').trim().replace(/\s+/g,' '),last=String(p?.last_name||'').trim().replace(/\s+/g,' ');
 if(first&&last)return first+' '+last;
 if(first||last)return [first,last].filter(Boolean).join(' ')+' (ชื่อ–นามสกุลยังไม่ครบ)';
 return 'ยังไม่ได้บันทึกชื่อ–นามสกุลจริง'
}
function appointmentShareDateLabel(v:any){
 const d=new Date(String(v||''));if(Number.isNaN(d.getTime()))return 'ยังไม่ระบุวัน';
 try{return new Intl.DateTimeFormat('th-TH-u-nu-latn',{timeZone:'Asia/Bangkok',weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(d)}
 catch{return appointmentDateOnlyLabel(v)}
}
function appointmentShareTimeLabel(v:any){
 // PHMS_APPOINTMENT_SPOKEN_TIME_GLOBAL_V1
 return appointmentTimeOnlyLabel(v);
}
function appointmentShareText(w:any,fullName:string){
 const x=w?.item||{},clean=(v:any)=>String(v??'').trim().replace(/\s+/g,' ');
 const shown=(v:any)=>{const s=clean(v);return !!s&&!/^(?:-|—|ไม่ระบุ|ไม่มี|n\/a)$/i.test(s)};
 const lines:string[]=['📅 แจ้งนัดหมาย','━━━━━━━━━━━━━━','','👤 ผู้มีนัด',
   clean(fullName)||'ยังไม่ได้บันทึกชื่อ–นามสกุลจริง','',
   '🩺 นัดเพื่อ: '+(shown(x.title)?clean(x.title):'นัดหมาย'),'',
   '📆 วันนัด: '+appointmentShareDateLabel(x.appointment_at),
   '🕘 เวลา: '+appointmentShareTimeLabel(x.appointment_at)];
 const place:string[]=[];
 if(shown(x.hospital_name))place.push('🏥 รพ./คลินิก: '+phmsHospitalShortLabel(x.hospital_name));
 if(shown(x.department))place.push('🏢 แผนก: '+clean(x.department));
 if(shown(x.doctor_name))place.push(appointmentDoctorEmoji(x.doctor_name)+' แพทย์: '+appointmentDoctorLabel(x.doctor_name));
 if(shown(x.care_topic))place.push(String(x?.followup_kind||'')==='chronic_routine'?'🩺 โรคประจำตัว: '+clean(x.care_topic):'🩺 กลุ่มโรค: '+clean(x.care_topic));
 if(place.length)lines.push('',...place);
 const extras:string[]=[];
 if(Number(x?.arrival_lead_minutes)>0)extras.push('⏱️ ควรไปก่อนเวลา '+Number(x.arrival_lead_minutes)+' นาที');
 if(shown(x.coverage_type))extras.push('🪪 สิทธิรักษา: '+clean(x.coverage_type));
 if(extras.length)lines.push('',...extras);
 const pending=(Array.isArray(w?.tasks)?w.tasks:[]).filter((t:any)=>t&&String(t.status||'')==='pending');
 if(pending.length||shown(x.preparation_notes)){
   lines.push('','🧳 เตรียมตัวก่อนนัด');
   for(const t of pending)lines.push('☐ '+clean(t.title||'รายการเตรียมตัว')+(shown(t.instruction)?' — '+clean(t.instruction):''));
   if(shown(x.preparation_notes))lines.push('• '+clean(x.preparation_notes));
 }
 if(shown(x.note))lines.push('','📝 หมายเหตุ: '+clean(x.note));
 const roles:any={responsible:'ผู้รับผิดชอบหลัก',caregiver:'ผู้ดูแลวันนัด',driver:'ผู้พาไป',companion:'ผู้ไปด้วย',booker:'ผู้ประสานงาน',other:'หน้าที่อื่น'};
 const people=(Array.isArray(w?.assignees)?w.assignees:[]).filter((a:any)=>a&&!['removed','declined'].includes(String(a.status||''))&&shown(a.display_name));
 if(people.length){lines.push('','👥 คนที่เกี่ยวข้อง');for(const a of people)lines.push('• '+(roles[String(a.role||'')]||'ผู้เกี่ยวข้อง')+': '+clean(a.display_name))}
 const status=String(x?.status||'scheduled');
 const statusLabels:any={confirmed:'ยืนยันนัดแล้ว',arrived:'ถึงสถานพยาบาลแล้ว',completed:'เสร็จสิ้น',cancelled:'ยกเลิกนัด',no_show:'ไม่ได้ไปตามนัด',rescheduled:'เลื่อนนัดแล้ว'};
 if(status!=='scheduled')lines.push('','✅ สถานะ: '+(statusLabels[status]||clean(status)));
 if(status==='completed'){
   const after:string[]=[];
   for(const [key,label] of [['diagnosis_summary','ผลวินิจฉัย'],['treatment_summary','การรักษา'],['next_steps','สิ่งที่ต้องทำต่อ'],['medication_plan_notes','ยา/การเปลี่ยนยา'],['test_results_summary','ผลตรวจ']]){
     if(shown(x[key]))after.push('• '+label+': '+clean(x[key]));
   }
   if(after.length)lines.push('','🩺 สรุปหลังนัด',...after);
 }
 return lines.join('\n').trim()
}

function splitAppointmentEditReason(text:string){
 const s=String(text||'').trim();
 const m=s.match(/\s+(?:เพราะ|เนื่องจาก|เหตุผล(?:คือ|:)?|สาเหตุ(?:คือ|:)?)\s*(.+)$/i);
 if(!m)return {content:s,reason:''};
 return {content:s.slice(0,m.index).trim(),reason:String(m[1]||'').trim()}
}
function appointmentUpdatePatch(before:any,after:any){
 const patch:any={};
 if(String(before?.date||'')!==String(after?.date||'')||String(before?.time||'')!==String(after?.time||'')){
   if(after?.date&&after?.time)patch.appointment_at=after.date+'T'+after.time+':00+07:00';
 }
 for(const k of ['title','hospital_name','hospital_hn','hospital_vn','care_topic','department','doctor_name','arrival_lead_minutes','note','location_detail','contact_phone','contact_email','coverage_type','preparation_notes','appointment_type','organization_id','service_unit_id','clinician_id']){
   if(String(before?.[k]??'')!==String(after?.[k]??''))patch[k]=after?.[k]??null
 }
 return patch
}
function parseReminderPreset(text:string){
 const s=String(text||'').toLowerCase();
 if(/ปิด/.test(s))return {offsets:[],post:0};
 if(/มาตรฐาน|7.*3.*1/.test(s))return {offsets:[10080,4320,1440],post:null};
 if(/3.*1/.test(s))return {offsets:[4320,1440],post:null};
 if(/1\s*วัน/.test(s)&&!/3/.test(s)&&!/7/.test(s))return {offsets:[1440],post:null};
 const pre=s.split(/หลังนัด/)[0],offsets:number[]=[];
 for(const m of pre.matchAll(/(\d+)\s*วัน/g))offsets.push(Number(m[1])*1440);
 for(const m of pre.matchAll(/(\d+)\s*(?:ชม|ชั่วโมง)/g))offsets.push(Number(m[1])*60);
 const pm=s.match(/หลังนัด\s*(\d+)\s*(?:นาที|น\.|ชม|ชั่วโมง)/);
 let post:any=null;
 if(pm)post=/(?:ชม|ชั่วโมง)/.test(pm[0])?Number(pm[1])*60:Number(pm[1]);
 return {offsets:[...new Set(offsets.filter(x=>x>=30&&x<=40320))].sort((a,b)=>b-a),post}
}
function inferAppointmentTaskType(text:string){
 const s=String(text||'').toLowerCase();
 if(/เจาะเลือด|ตรวจเลือด|blood|lab/.test(s))return 'lab';
 if(/x[- ]?ray|เอกซเรย์|เอ็กซเรย์|รังสี/.test(s))return 'imaging';
 if(/ปัสสาวะ|urine/.test(s))return 'urine';
 if(/ความดัน|น้ำหนัก|อุณหภูมิ|ชีพจร|วัด/.test(s))return 'measurement';
 if(/เอกสาร|ใบส่งตัว|บัตร|ผลตรวจ|ใบรับรอง/.test(s))return 'document';
 if(/งดอาหาร|งดน้ำ|อดอาหาร|fast/.test(s))return 'fasting';
 if(/ยา|งดยา|กินยา|หยุดยา/.test(s))return 'medication_instruction';
 return 'other'
}
function appointmentSummary(p:any,personName:string,sourceCode?:string){
 let x='📅 สรุปนัดที่อ่านได้\n\n👤 นัดของ: '+personName+
   '\n📆 วันนัด: '+appointmentDateOnlyLabel((p as any)?.appointment_at||((p as any)?.date&&((p as any)?.time)?String((p as any).date)+'T'+String((p as any).time)+':00+07:00':null))+
   '\n🕐 เวลา: '+appointmentTimeOnlyLabel((p as any)?.appointment_at||((p as any)?.date&&((p as any)?.time)?String((p as any).date)+'T'+String((p as any).time)+':00+07:00':null))+
   '\n📌 นัดเพื่อ: '+String(p.title||'นัดหมาย')+
   '\n🏥 รพ./คลินิก: '+String(p.hospital_name||'—')+
   '\n🆔 HN: '+String(p.hospital_hn||'—')+
   '\n🔢 VN: '+String(p.hospital_vn||'—')+
   '\n'+(String(p?.followup_kind||'')==='chronic_routine'?'🩺 โรคประจำตัวที่ติดตาม: ':'🧭 เรื่องที่รักษา: ')+String(p.care_topic||'—')+
   '\n🏢 แผนก/คลินิก: '+String(p.department||'—')+
   '\n👨‍⚕️ แพทย์: '+String(p.doctor_name||'—')+
   '\n📍 จุด/อาคาร/ชั้น: '+String(p.location_detail||'—')+
   '\n⏱️ ควรมาถึงก่อน: '+(Number(p.arrival_lead_minutes||0)>0?String(p.arrival_lead_minutes)+' นาที':'—')+
   '\n🏷️ สถานะ: '+appointmentStatusLabel(p.status||'scheduled')+
   '\n🪪 สิทธิรักษา: '+String(p.coverage_type||'—')+
   (p.diagnostic_procedures?.length?'\n🔬 รายการตรวจ: '+p.diagnostic_procedures.map((v:any)=>v.name).join(', '):'')+
   '\n🧾 เตรียมตัว: '+String(p.preparation_notes||'—')+
   '\n📝 หมายเหตุ: '+String(p.note||'—');
 if(sourceCode)x+='\n\n⚠️ ตรวจอีกครั้งก่อนยืนยัน';
 return x
}
// PHMS APPOINTMENT CARD PRESENTATION V2: readable labels and muted secondary notes.
function appointmentCardValueParts(value:any){
 const raw=String(value??'—').trim()||'—';
 const m=raw.match(/^(.*?)\s*(\([^()]{1,90}\))(\s*(?:[•·]\s*)?.*)?$/u);
 if(!m||!m[1].trim())return {main:raw,sub:''};
 return {main:m[1].trim(),sub:(m[2]+(m[3]||'')).trim()}
}
function appointmentCardValueFlex(value:any,extra=''){
 const x=appointmentCardValueParts(value);
 const note=[x.sub,String(extra||'').trim()].filter(Boolean).join(' · ');
 return [
  {type:'text',text:x.main,size:'sm',color:'#222222',weight:'bold',wrap:true},
  ...(note?[{type:'text',text:note,size:'xs',color:'#8893A3',wrap:true,margin:'xs'}]:[])
 ]
}
function appointmentCardCompactRow(icon:string,label:string,value:any,extra=''){
 return {type:'box',layout:'horizontal',spacing:'sm',alignItems:'start',contents:[
  {type:'text',text:icon,size:'sm',flex:1},
  {type:'text',text:label,size:'xs',color:'#667085',flex:4,wrap:true},
  {type:'box',layout:'vertical',flex:8,contents:appointmentCardValueFlex(value,extra)}
 ]}
}
function appointmentDoctorCompactRow(doctor:any){const r=appointmentCardCompactRow(appointmentDoctorEmoji(doctor),'หมอ',appointmentDoctorShortLabel(doctor));const value:any=r.contents?.[2]?.contents?.[0];if(value){value.maxLines=1;value.wrap=true}return r}
function appointmentDoctorShortLabel(v:any){
 return appointmentDoctorLabel(v);
}
function appointmentFormRow(icon:string,label:string,value?:any){
 if(arguments.length===2){value=label;label=icon;icon='📋'}
 return {type:'box',layout:'horizontal',spacing:'sm',contents:[
  {type:'text',text:icon,size:'sm',flex:1},
  {type:'box',layout:'vertical',flex:8,contents:[
    {type:'text',text:label,size:'xs',color:'#777777',wrap:true},
    {type:'box',layout:'vertical',margin:'xs',contents:appointmentCardValueFlex(['โรงพยาบาล','รพ./คลินิก','สถานพยาบาล'].includes(String(label))?phmsHospitalShortLabel(value):value)}
  ]}
 ]}
}


function appointmentFollowupLabel(v:any){
 return v===true?'ใช่':v===false?'ไม่':'ยังไม่ทราบ'
}
