/* PHMS_APPT_TWO_LEVEL_UX_RULE: 1. choose broad type; 2. choose specific type.
 Show linked flows and rescheduling only if an accessible appointment exists.
 Walk-in means attending without advance booking, not necessarily a completed visit.
 Never interpret "no data" as "no permission"; never create duplicates on reschedule.
 Dark muted button variants + short explanations, no unlabeled icons or clipped names.
*/
async function phmsAppointmentHistoryPresence(u:string,k:string,id:string){
 try{const x=one(await rpc(u,k,'phms_line_appointment_care_map',{p_line_user_id:id,p_group_key:null}))||{};
 return {readable:x?.ok===true,hasAny:x?.ok===true&&Array.isArray(x?.groups)&&x.groups.some((g:any)=>Number(g.appointment_count||0)>0)}
 }catch{return {readable:false,hasAny:false}}
}
/* PHMS_IMOON_ELDER_LANGUAGE_POLICY_V1: All newly authored LINE text, cards, quick replies, and notifications use short, warm, gender-neutral Thai; no user-facing technical errors; labels describe real actions; hide unauthorized actions; keep health records and postback data unchanged. */
function phmsApptOption(label:string,command:string,explain:string){
 // Elder-friendly UI: a short action label with a separate plain-language hint.
 return {type:'box',layout:'vertical',spacing:'xs',contents:[
  {type:'button',style:'primary',height:'sm',action:{type:'postback',label,data:command,displayText:label}},
  ...(explain?[{type:'text',text:explain,wrap:false,size:'sm',color:'#24364B',margin:'none',maxLines:1}]:[])
 ]}
}
function phmsApptPickerCard(title:string,sub:string,options:any[],back=false,backData='เลือกประเภทนัดใหม่'){
 return {type:'flex',altText:title,contents:{type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',height:'76px',justifyContent:'center',spacing:'xs',paddingAll:'10px',backgroundColor:PHMS_CATEGORY_THEME.appointments.background,contents:[
   {type:'text',text:title,size:'xl',weight:'bold',color:'#111111',wrap:true,maxLines:1},
   {type:'text',text:sub,size:'md',weight:'regular',color:'#30343B',wrap:true,margin:'xs',maxLines:1}]},
  body:{type:'box',layout:'vertical',spacing:'xs',paddingAll:'8px',contents:options},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:[
   ...(back?[{type:'button',style:'primary',action:{type:'postback',label:'↩️ ย้อนกลับ',data:backData}}]:[]),
   {type:'button',style:'primary',action:{type:'postback',label:'❌ ยกเลิกเพิ่มนัด',data:'ยกเลิกเพิ่มนัด'}}]}}}
}
/* PHMS_SELECTED_PERSON_APPOINTMENT_CONTEXT_FIX: use existing selected person; no repeat selection. */
async function appointmentActivePersonName(u:string,k:string,id:string):Promise<string>{
 try{
  const d=one(await rpc(u,k,'phms_get_line_person_dashboard',{p_line_user_id:id}));
  const name=String(d?.display_name||d?.first_name||'').trim();
  return name||'บุคคลที่เลือก';
 }catch(err){
  console.error('appointment_person_context_lookup_failed',String(err));
  return 'บุคคลที่เลือก';
 }
}
/* PHMS_APPOINTMENT_CREATION_GLOBAL_4_GROUP_RULE_V1
  One bubble, four broad groups, no pagination; existing appointment_type codes remain unchanged.
  Navigation buttons are an explicit exception to the generic four-action overflow splitter.
*/
async function replyAppointmentTypePicker(rt:string,u:string,k:string,id:string,t:string,personName:string){
 const option=(label:string,data:string,help:string,bg:string)=>({
  type:'box',layout:'vertical',height:'60px',spacing:'none',justifyContent:'center',alignItems:'center',backgroundColor:bg,cornerRadius:'8px',action:{type:'postback',data,displayText:label},
  contents:[
   {type:'text',text:label,size:'md',weight:'regular',color:'#FFFFFF',align:'center',gravity:'center',wrap:false,maxLines:1},
   {type:'text',text:help,size:'sm',weight:'regular',color:'#FFFFFF',align:'center',gravity:'center',wrap:false,maxLines:1}
  ]
 });
 const action=(label:string,data:string,bg:string)=>({
  type:'box',layout:'vertical',height:'48px',spacing:'none',justifyContent:'center',alignItems:'center',backgroundColor:bg,cornerRadius:'8px',action:{type:'postback',data,displayText:label},
  contents:[{type:'text',text:label,size:'md',weight:'regular',color:'#FFFFFF',align:'center',gravity:'center',wrap:false,maxLines:1}]
 });
 const card:any=phmsApptPickerCard('📅 เพิ่มนัดหมาย','นัดของ '+String(personName||'ผู้ใช้')+' • ขั้นตอนที่ 1/8',[
  option('🩺 ไปพบหมอ','เลือกหมวดนัด รักษา','ตรวจตามนัด / ติดตามโรค','#5F5048'),
  option('🔬 ไปตรวจอย่างเดียว','เลือกหมวดนัด ตรวจ','ตรวจเลือด / เอกซเรย์ / ตรวจพิเศษ','#89765E'),
  option('💊 ไปรับยาอย่างเดียว','เลือกหมวดนัด ยา','รับที่ รพ. / ส่งยาถึงบ้าน','#496476'),
  option('📋 นัดเรื่องอื่น ๆ','เลือกหมวดนัด อื่น','ฉีดวัคซีน / ส่งต่อ / อื่น ๆ','#795A52')
 ],false);
 card.contents.header.height='68px';
 card.contents.body.paddingAll='8px';
 card.contents.body.spacing='6px';
 card.contents.footer.paddingAll='8px';
 card.contents.footer.spacing='6px';
 card.contents.footer.contents=[
  action('📝 กรอกข้อมูลเอง','เทมเพลตเพิ่มนัด','#5D6179'),
  action('❌ ยกเลิกเพิ่มนัด','ยกเลิกเพิ่มนัด','#933C4A')
 ];
 await replyMessages(rt,t,[card]);
}
