function medDateLabel(v:any){
 if(!v)return '—';
 try{return new Intl.DateTimeFormat('th-TH',{timeZone:'Asia/Bangkok',day:'numeric',month:'short',year:'numeric'}).format(new Date(String(v)+'T00:00:00+07:00'))}
 catch{return String(v)}
}
function medicationDoseLabel(p:any){
 if(p?.dose_text)return String(p.dose_text);
 return [p?.dose_value,p?.dose_unit].filter(x=>x!==undefined&&x!==null&&x!=='').join(' ')||'—'
}
function medicationFrequencyLabel(p:any){
 if(p?.schedule_kind&&p.schedule_kind!=='legacy')return medicationScheduleLabel(p);
 if(p?.frequency_type==='times_per_day'&&p?.frequency_value)return 'วันละ '+p.frequency_value+' ครั้ง';
 if(p?.frequency_type==='interval'&&p?.frequency_value)return 'ทุก '+p.frequency_value+' ชั่วโมง';
 return '—'
}
function medicationTimeLabel(p:any){
 const map:any={morning:'เช้า',noon:'กลางวัน',evening:'เย็น',bedtime:'ก่อนนอน'};
 const tod=Array.isArray(p?.time_of_day)?p.time_of_day.map((x:any)=>map[String(x)]||String(x)):[];
 const ex=Array.isArray(p?.exact_times)?p.exact_times:[];
 const mealMap:any={before_meal:'ก่อนอาหาร',after_meal:'หลังอาหาร',with_meal:'พร้อมอาหาร',empty_stomach:'ท้องว่าง'};
 return [...tod,...ex,mealMap[String(p?.meal_relation||'')]||''].filter(Boolean).join(' / ')||'—'
}
function medicationNameLabel(p:any){
 return [p?.generic_name||p?.medication_name||p?.name,p?.strength_value,p?.strength_unit].filter(x=>x!==undefined&&x!==null&&x!=='').join(' ')||'—'
}
function medicationSummary(p:any,personName:string,sourceCode?:string,recorderName?:string){
 let x='💊 สรุปยาที่อ่านได้\n\n👤 ข้อมูลของ: '+personName+
   (recorderName?'\n✍️ ผู้บันทึก: '+String(recorderName):'')+
   '\n💊 ชื่อยา: '+medicationNameLabel(p)+
   '\n🧴 รูปแบบยา: '+String(p.dosage_form||'—')+
   '\n🥄 ขนาดรับประทาน: '+medicationDoseLabel(p)+
   '\n🔁 ความถี่: '+medicationFrequencyLabel(p)+
   '\n⏰ เวลา: '+medicationTimeLabel(p)+
   '\n▶️ เริ่มใช้ยา: '+medDateLabel(p.start_date)+
   '\n⏹️ สิ้นสุดการใช้ยา: '+medDateLabel(p.end_date)+
   '\n🩺 สาเหตุ/อาการ: '+String(p.indication||'—')+
   '\n📝 หมายเหตุ: '+String(p.notes||'—');
 if(sourceCode)x+='\n\n⚠️ ตรวจอีกครั้งก่อนกดยืนยัน\nรหัสรับเข้า: #'+sourceCode;
 return x
}
