async function replyAppointmentPaymentMethodPicker(rt:string,u:string,k:string,id:string,t:string,recordCode:string,prefix=''){
 const code=String(recordCode||'');
 let context='';try{context=appointmentFinanceContextText(one(await rpc(u,k,'phms_line_appointment_finance',{p_line_user_id:id,p_record_code:code})))}catch{}
 await reply(rt,(prefix?prefix+'\n\n':'')+'💳 เลือกช่องทางการชำระเงิน'+(context?'\n\n📌 นัดที่กำลังบันทึก\n'+context:'')+'\n\nระบบเก็บเป็นรหัสมาตรฐาน ไม่ต้องพิมพ์เอง',t,[
  pb('📱 สแกนจ่าย / QR','เลือกช่องทางค่าใช้จ่าย '+code+' promptpay_qr'),
  pb('💵 เงินสด','เลือกช่องทางค่าใช้จ่าย '+code+' cash'),
  pb('💳 บัตรเครดิต','เลือกช่องทางค่าใช้จ่าย '+code+' credit_card'),
  pb('💳 บัตรเดบิต','เลือกช่องทางค่าใช้จ่าย '+code+' debit_card'),
  pb('🏦 โอนเงิน','เลือกช่องทางค่าใช้จ่าย '+code+' bank_transfer'),
  pb('📲 E-Wallet','เลือกช่องทางค่าใช้จ่าย '+code+' e_wallet'),
  pb('➕ อื่น ๆ','เลือกช่องทางค่าใช้จ่าย '+code+' other'),
  pb('❌ ยกเลิก','ดูนัด '+code)
 ])
}
async function replyAppointmentPayerPicker(rt:string,u:string,k:string,id:string,t:string,recordCode:string,offset=0,prefix=''){
 const out=one(await rpc(u,k,'phms_line_appointment_payer_options',{p_line_user_id:id,p_record_code:recordCode}));
 const items=Array.isArray(out?.items)?out.items:[],off=Math.max(0,Number(offset)||0),page=items.slice(off,off+8);
 const code=String(out?.record_code||recordCode);
 let financeContext='';try{financeContext=appointmentFinanceContextText(one(await rpc(u,k,'phms_line_appointment_finance',{p_line_user_id:id,p_record_code:code})))}catch{}
 if(!page.length){
  await reply(rt,'👤 ยังไม่มีสมาชิกหรือบุคคลในครอบครัวที่เลือกเป็นผู้จ่ายได้',t,[pb('↩️ กลับนัด','ดูนัด '+code)]);
  return
 }
 const lines=page.map((x:any,i:number)=>String(off+i+1)+'. '+String(x?.display_name||'สมาชิก')+(x?.relationship_label?' • '+String(x.relationship_label):'')).join('\n');
 const q:any[]=page.map((x:any)=>pb(
  phmsNormalizeActionLabel('👤 '+String(x?.display_name||'สมาชิก')),
  'เลือกผู้จ่ายค่าใช้จ่าย '+code+' '+String(x?.selection_kind||'person')+' '+String(x?.selection_id||'')
 ));
 if(off>0)q.push(pb('⬅️ ก่อนหน้า','เลือกผู้จ่ายค่าใช้จ่ายหน้า '+code+' '+String(Math.max(0,off-8))));
 if(off+page.length<items.length)q.push(pb('➡️ ถัดไป','เลือกผู้จ่ายค่าใช้จ่ายหน้า '+code+' '+String(off+8)));
 q.push(pb('❌ ยกเลิก','ดูนัด '+code));
 await reply(rt,(prefix?prefix+'\n\n':'')+'👤 เลือกคนที่เป็นผู้จ่าย'+(financeContext?'\n\n📌 นัดที่กำลังบันทึก\n'+financeContext:'')+'\n\n'+lines+'\n\nเลือกจากสมาชิก/บุคคลในครอบครัว เพื่อผูกประวัติผู้จ่ายกับคนจริงในระบบ',t,q.slice(0,13))
}
async function saveAppointmentFinanceParsed(u:string,k:string,id:string,recordCode:string,parsed:any,ctx:any){
 return one(await rpc(u,k,'phms_line_appointment_finance_upsert',{
  p_line_user_id:id,
  p_record_code:recordCode,
  p_paid_amount:parsed.paid_amount,
  p_coverage_used:parsed.coverage_used,
  p_coverage_type:parsed.coverage_type,
  p_covered_amount:parsed.covered_amount,
  p_payment_method:null,
  p_payer:null,
  p_notes:parsed.notes,
  p_items:parsed.items,
  p_payment_method_code:ctx?.payment_method_code||null,
  p_payer_user_id:ctx?.payer_user_id||null,
  p_payer_family_person_id:ctx?.payer_family_person_id||null
 }))
}
async function replyAppointmentFinanceInputPrompt(rt:string,u:string,k:string,id:string,t:string,recordCode:string,coverage:string,existing:any,ctx:any){
 const code=String(existing?.record_code||recordCode);
 const method=appointmentPaymentMethodLabel(ctx?.payment_method_code||existing?.expense?.payment_method_code||'');
 const payer=String(ctx?.payer_name||existing?.expense?.payer||'—');
 const context=appointmentFinanceContextText(existing);
 const info=[
  '💰 ค่าใช้จ่ายหลังนัด',
  ...(context?['','📌 นัดที่กำลังบันทึก',context]:[]),
  '',
  'หน่วยเงิน: ฿ (THB)',
  '💳 ช่องทาง: '+method,
  '👤 ผู้จ่าย: '+payer,
  '',
  'กรอกตัวเลขอย่างเดียวได้ เช่น 450 = ฿450',
  'พิมพ์ ฿450 / 450 บาท / THB 450 ก็เข้าใจเป็นจำนวนเดียวกัน',
  '',
  appointmentFinanceTemplateText(coverage,existing),
  '',
  'ถ้าแจกแจงรายการย่อย อิ่มอุ่นจะบวกตรวจให้ และยอดรวมรายการย่อยต้องเท่ากับ “ยอดที่จ่ายจริง” ก่อนจึงจะบันทึกได้',
  'ถ้าไม่ต้องการแจกแจงรายการย่อย ให้คง “-” ไว้',
  '',
  'ตัวอย่าง:',
  '- ค่ายา 320 | หมวดมาตรฐาน:03',
  '- ค่าตรวจเลือด 450 | หมวดมาตรฐาน:07 | รหัสมาตรฐาน:12345',
  '',
  'หมวดมาตรฐาน = หมวดค่ารักษาตามกรมบัญชีกลาง เช่น 07 คือค่าตรวจแล็บ',
  'รหัสมาตรฐาน = รหัสรายการบริการเฉพาะ ถ้ามีจากใบเสร็จหรือข้อมูลโรงพยาบาลค่อยใส่ ไม่มีก็ไม่ต้องเดา'
 ].join('\n');
 await reply(rt,info,t,[
  pb('💳 เปลี่ยนช่องทาง','เปลี่ยนการชำระเงิน '+code),
  pb('👤 เปลี่ยนผู้จ่าย','เปลี่ยนผู้จ่ายค่าใช้จ่าย '+code),
  pb('❌ ยกเลิก','ค่าใช้จ่ายนัด '+code)
 ])
}
async function replyAppointmentFinanceCard(rt:string,u:string,k:string,id:string,t:string,recordCode:string,prefix='',postVisitNext=false){
 const out=one(await rpc(u,k,'phms_line_appointment_finance',{p_line_user_id:id,p_record_code:recordCode}));
 const e=out?.expense||null,items=Array.isArray(out?.items)?out.items:[],docs=Array.isArray(out?.payment_documents)?out.payment_documents:[];
 const code=String(out?.record_code||recordCode),canUpdate=out?.can_update===true;
 if(!e){
  const flex:any={type:'flex',altText:'💰 ค่าใช้จ่ายของนัด',contents:{type:'bubble',size:'kilo',
   header:{type:'box',layout:'vertical',backgroundColor:'#FFF7E8',paddingAll:'18px',contents:[
    {type:'text',text:'💰 ค่าใช้จ่ายหลังนัด',weight:'bold',size:'xl',color:'#805B18'},
    {type:'text',text:appointmentFinanceContextText(out)||phmsHospitalShortLabel(out?.hospital_name||'นัดหมาย'),size:'xs',color:'#667085',margin:'sm',wrap:true}
   ]},
   body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'16px',contents:[
    ...(prefix?[{type:'text',text:prefix,size:'sm',weight:'bold',wrap:true,color:'#285943'}]:[]),
    {type:'text',text:'ยังไม่ได้บันทึกยอดที่จ่ายจริง',size:'md',weight:'bold',wrap:true},
    {type:'text',text:'ยอดเงินใช้หน่วย ฿ • กรอกแค่ตัวเลขก็ได้ • ถ้าใช้สิทธิและไม่เสียเงิน ให้บันทึกเป็น ฿0',size:'sm',color:'#666666',wrap:true}
   ]},
   footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:[
    ...(canUpdate?[{type:'button',style:'primary',action:{type:'postback',label:'✅ ใช้สิทธิ • ฿0',data:'ค่าใช้จ่ายหลังนัด '+code+' zero'}},
                   {type:'button',style:'primary',action:{type:'postback',label:'💳 มีค่าใช้จ่าย',data:'ค่าใช้จ่ายหลังนัด '+code+' paid'}}]:[]),
    {type:'button',action:{type:'postback',label:'↩️ กลับรายละเอียดนัด',data:'ดูนัด '+code}}
   ]}
  }};
  await replyMessages(rt,t,[flex]);return
 }
 const itemTotal=items.reduce((s:number,x:any)=>s+Number(x?.amount||0),0);
 const diff=Number(e?.paid_amount||0)-itemTotal;
 const body:any[]=[
  ...(prefix?[{type:'text',text:prefix,size:'sm',weight:'bold',wrap:true,color:'#285943'},{type:'separator',margin:'md'}]:[]),
  appointmentFormRow('💵','จ่ายจริง',moneyThai(e?.paid_amount)),
  appointmentFormRow('🪪','การใช้สิทธิ',e?.coverage_used?'ใช้สิทธิ'+(e?.coverage_type?' • '+String(e.coverage_type):''):'จ่ายเอง'),
  ...(e?.covered_amount!==undefined&&e?.covered_amount!==null?[appointmentFormRow('🏥','สิทธิ/ประกันออกให้',moneyThai(e.covered_amount))]:[]),
  ...(Number(e?.paid_amount||0)>0?[appointmentFormRow('💳','ช่องทางชำระ',appointmentPaymentMethodLabel(e?.payment_method_code||e?.payment_method)),appointmentFormRow('👤','ผู้จ่าย',String(e?.payer||'—'))]:[]),
  ...(items.length?[
   {type:'separator',margin:'md'},
   {type:'text',text:'🧾 รายละเอียดค่าใช้จ่าย',size:'sm',weight:'bold',wrap:true},
   ...items.slice(0,8).map((x:any)=>({type:'text',text:'• '+String(x?.label||appointmentExpenseCategoryLabel(x?.category))+' — '+moneyThai(x?.amount)+(x?.cgd_category_code?'\n  หมวดมาตรฐาน '+String(x.cgd_category_code)+(x?.cgd_category_name?' • '+String(x.cgd_category_name):''):'')+(x?.cgd_item_code?'\n  รหัสรายการมาตรฐาน '+String(x.cgd_item_code):'')+(x?.hospital_item_code?' • รหัส รพ. '+String(x.hospital_item_code):''),size:'sm',wrap:true,color:'#444444'})),
   {type:'text',text:'รวมรายการย่อย '+moneyThai(itemTotal),size:'xs',color:'#444444',wrap:true},
   {type:'text',text:Math.abs(diff)<0.01?'✅ ตรวจสอบแล้ว: รายการย่อยรวมเท่ากับยอดจ่ายจริง':'⚠️ รายการย่อยต่างจากยอดจ่ายจริง '+moneyThai(Math.abs(diff)),size:'xs',weight:'bold',color:Math.abs(diff)<0.01?'#2F6B4F':'#9A6700',wrap:true}
  ]:[]),
  ...(e?.notes?[appointmentFormRow('📝','หมายเหตุ',String(e.notes))]:[]),
  {type:'separator',margin:'md'},
  {type:'text',text:'📎 หลักฐานการชำระ '+String(docs.length)+' รายการ • รูปไม่บังคับ',size:'xs',color:'#667085',wrap:true}
 ];
 const footer:any[]=[
  {type:'button',style:'primary',action:{type:'postback',label:'🧾 รายละเอียดค่ารักษา',data:'รายละเอียดค่ารักษา '+code}},
  ...(docs.length?[{type:'button',style:'secondary',action:{type:'postback',label:phmsNormalizeActionLabel('📎 ดูหลักฐาน ('+String(docs.length)+')'),data:'หลักฐานค่าใช้จ่าย '+code+' 0'}}]:[]),
  ...(canUpdate?[{type:'button',style:'secondary',action:{type:'postback',label:'✏️ แก้ยอด / รายละเอียด',data:'แก้ค่าใช้จ่ายนัด '+code}},
                 {type:'button',style:'secondary',action:{type:'postback',label:'💳 ช่องทาง / ผู้จ่าย',data:'เปลี่ยนการชำระเงิน '+code}},
                 {type:'button',style:docs.length?'secondary':'primary',action:{type:'postback',label:docs.length?'➕ แนบหลักฐานเพิ่ม':'➕ แนบหลักฐาน',data:'แนบหลักฐานค่าใช้จ่าย '+code}}]:[]),
  ...(postVisitNext?[{type:'button',style:'secondary',action:{type:'postback',label:'➕ สร้างนัดถัดไป',data:'เพิ่มนัดติดตาม '+code}},
                     {type:'button',style:'secondary',action:{type:'postback',label:'🔗 เชื่อมนัดที่มีอยู่',data:'เชื่อมนัด '+code+' 0'}},
                     {type:'button',style:'secondary',action:{type:'postback',label:'💊 เพิ่ม/เปลี่ยนยา',data:'เพิ่มยาจากนัด '+code}},
                     {type:'button',style:'secondary',action:{type:'postback',label:'🧪 ผลตรวจ / สุขภาพ',data:'เพิ่มสุขภาพจากนัด '+code}},
                     {type:'button',style:'secondary',action:{type:'postback',label:'ไม่มีนัดต่อ',data:'ไม่มีนัดติดตาม '+code}}]:[]),
  {type:'button',style:'secondary',action:{type:'postback',label:'📎 เอกสารทั้งหมด',data:'เอกสารนัด '+code}},
  {type:'button',action:{type:'postback',label:'↩️ รายละเอียดนัด',data:'ดูนัด '+code}}
 ];
 const flex:any={type:'flex',altText:'💰 ค่าใช้จ่ายหลังนัด '+moneyThai(e?.paid_amount),contents:{type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:'#FFF7E8',paddingAll:'18px',contents:[
   {type:'text',text:'💰 ค่าใช้จ่ายหลังนัด',weight:'bold',size:'xl',color:'#805B18'},
   {type:'text',text:appointmentFinanceContextText(out)||phmsHospitalShortLabel(out?.hospital_name||'โรงพยาบาล'),size:'xs',color:'#667085',margin:'sm',wrap:true}
  ]},
  body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'16px',contents:body},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:footer.slice(0,8)}
 }};
 await replyMessages(rt,t,[flex])
}

function appointmentPaymentEvidenceLabel(kind:any){
 const x=String(kind||'');
 if(x==='receipt')return '🧾 ใบเสร็จ';
 if(x==='payment_slip')return '💸 สลิปชำระเงิน';
 if(x==='payment_qr')return '📱 QR จ่ายเงิน';
 return '📎 หลักฐานอื่น'
}
async function replyAppointmentFinanceEvidenceCards(rt:string,u:string,k:string,id:string,t:string,recordCode:string,page=0,prefix=''){
 const out=one(await rpc(u,k,'phms_line_appointment_documents',{p_line_user_id:id,p_record_code:recordCode}));
 const finance=one(await rpc(u,k,'phms_line_appointment_finance',{p_line_user_id:id,p_record_code:recordCode}));
 const code=String(finance?.record_code||recordCode),canUpdate=out?.can_update===true;
 const all=Array.isArray(out?.items)?out.items:[];
 const docs=all.filter((d:any)=>['receipt','payment_slip','payment_qr','payment_other'].includes(String(d?.link_kind||'')));
 const pageSize=7,totalPages=Math.max(1,Math.ceil(docs.length/pageSize));
 const pg=Math.max(0,Math.min(Number(page)||0,totalPages-1));
 const shown=docs.slice(pg*pageSize,pg*pageSize+pageSize);
 const summaryFooter:any[]=[
  ...(canUpdate?[{type:'button',style:'primary',action:{type:'postback',label:docs.length?'➕ แนบหลักฐานเพิ่ม':'➕ แนบหลักฐาน',data:'แนบหลักฐานค่าใช้จ่าย '+code}}]:[]),
  {type:'button',style:'secondary',action:{type:'postback',label:'💰 กลับค่ารักษา',data:'ค่าใช้จ่ายนัด '+code}},
  {type:'button',action:{type:'postback',label:'↩️ รายละเอียดนัด',data:'ดูนัด '+code}}
 ];
 const cards:any[]=[{type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:'#EEF6FF',paddingAll:'18px',contents:[
   {type:'text',text:'📎 หลักฐานการชำระ',weight:'bold',size:'xl',color:'#365F8D',wrap:true},
   {type:'text',text:appointmentFinanceContextText(finance)||phmsHospitalShortLabel(finance?.hospital_name||'นัดหมาย'),size:'xs',color:'#667085',margin:'sm',wrap:true}
  ]},
  body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'16px',contents:[
   ...(prefix?[{type:'text',text:prefix,size:'sm',weight:'bold',color:'#2F6B4F',wrap:true},{type:'separator',margin:'md'}]:[]),
   {type:'text',text:docs.length?'มีหลักฐาน '+String(docs.length)+' รายการ':'ยังไม่มีหลักฐานการชำระ',size:'md',weight:'bold',wrap:true},
   {type:'text',text:docs.length?'กดเปิดแต่ละรายการเพื่อดูรูปหรือเอกสารต้นฉบับ':'แนบได้ทั้งใบเสร็จ สลิป QR และหลักฐานอื่น',size:'sm',color:'#667085',wrap:true},
   ...(totalPages>1?[{type:'text',text:'หน้า '+String(pg+1)+'/'+String(totalPages),size:'xs',color:'#777777'}]:[])
  ]},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:[
   ...(pg>0?[{type:'button',action:{type:'postback',label:'⬅️ ก่อนหน้า',data:'หลักฐานค่าใช้จ่าย '+code+' '+String(pg-1)}}]:[]),
   ...(pg<totalPages-1?[{type:'button',action:{type:'postback',label:'➡️ ถัดไป',data:'หลักฐานค่าใช้จ่าย '+code+' '+String(pg+1)}}]:[]),
   ...summaryFooter
  ].slice(0,5)}
 }];
 for(const d of shown){
  let url='';
  if(d?.bucket_id&&d?.object_name){
   try{url=await signGalleryObject(u,k,String(d.bucket_id),String(d.object_name),1800)}catch(err){console.error('finance_evidence_sign',String(err))}
  }
  const mime=String(d?.mime_type||'').toLowerCase();
  const isImage=/^image\//.test(mime)||/\.(?:jpg|jpeg|png|webp)$/i.test(String(d?.object_name||''));
  const footer:any[]=[
   ...(url?[{type:'button',style:'primary',action:{type:'uri',label:isImage?'🖼️ เปิดรูป':'📄 เปิดเอกสาร',uri:url}}]:[]),
   {type:'button',action:{type:'postback',label:'💰 กลับค่ารักษา',data:'ค่าใช้จ่ายนัด '+code}}
  ];
  cards.push({type:'bubble',size:'kilo',
   ...(isImage&&url?{hero:{type:'image',url,size:'full',aspectRatio:'4:3',aspectMode:'fit',backgroundColor:'#F7F9FC',action:{type:'uri',label:'เปิดรูป',uri:url}}}:{}),
   header:{type:'box',layout:'vertical',backgroundColor:'#FAFAFA',paddingAll:'16px',contents:[
    {type:'text',text:appointmentPaymentEvidenceLabel(d?.link_kind),size:'xs',color:'#667085',weight:'bold'},
    {type:'text',text:String(d?.title||'หลักฐานการชำระ'),weight:'bold',size:'lg',wrap:true,margin:'sm'}
   ]},
   body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'16px',contents:[
    appointmentFormRow('📆','เพิ่มเมื่อ',appointmentDateOnlyLabel(d?.created_at)),
    ...(d?.created_by_name?[appointmentFormRow('👤','เพิ่มโดย',String(d.created_by_name))]:[]),
    ...(d?.note?[appointmentFormRow('📝','หมายเหตุ',String(d.note))]:[]),
    {type:'text',text:url?'กดปุ่มด้านล่างเพื่อเปิดไฟล์ต้นฉบับ':'⚠️ ยังสร้างลิงก์เปิดไฟล์ไม่ได้',size:'xs',color:url?'#667085':'#9A6700',wrap:true}
   ]},
   footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:footer}
  })
 }
 await replyMessages(rt,t,[{type:'flex',altText:'📎 หลักฐานการชำระ '+String(docs.length)+' รายการ',contents:{type:'carousel',contents:cards.slice(0,10)}}])
}
async function replyAppointmentFinanceDetailCards(rt:string,u:string,k:string,id:string,t:string,recordCode:string,page=0){
 const out=one(await rpc(u,k,'phms_line_appointment_finance',{p_line_user_id:id,p_record_code:recordCode}));
 const e=out?.expense||null,items=Array.isArray(out?.items)?out.items:[],docs=Array.isArray(out?.payment_documents)?out.payment_documents:[];
 const code=String(out?.record_code||recordCode),canUpdate=out?.can_update===true;
 if(!e){
  await replyAppointmentFinanceCard(rt,u,k,id,t,code);
  return
 }
 const pageSize=5,totalPages=Math.max(1,Math.ceil(items.length/pageSize));
 const pg=Math.min(Math.max(0,Math.floor(Number(page)||0)),totalPages-1);
 const visible=items.slice(pg*pageSize,(pg+1)*pageSize);
 const itemTotal=items.reduce((s:number,x:any)=>s+Number(x?.amount||0),0);
 const diff=Number(e?.paid_amount||0)-itemTotal;
 const grouped:any={};
 for(const x of items){
  const key=String(x?.category||'other');
  if(!grouped[key])grouped[key]=[];
  grouped[key].push(x)
 }
 const categories=Object.keys(grouped).sort((a,b)=>
  grouped[b].reduce((s:number,x:any)=>s+Number(x?.amount||0),0)-
  grouped[a].reduce((s:number,x:any)=>s+Number(x?.amount||0),0)
 );
 const cards:any[]=[{type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:'#FFF7E8',paddingAll:'18px',contents:[
   {type:'text',text:'🧾 รายละเอียดค่ารักษา',weight:'bold',size:'xl',color:'#805B18',wrap:true},
   {type:'text',text:appointmentFinanceContextText(out)||phmsHospitalShortLabel(out?.hospital_name||'นัดหมาย'),size:'xs',color:'#667085',margin:'sm',wrap:true}
  ]},
  body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'16px',contents:[
   appointmentFormRow('💵','จ่ายจริง',moneyThai(e?.paid_amount)),
   appointmentFormRow('🧾','รายการย่อย',String(items.length)+' รายการ'),
   ...(items.length?[appointmentFormRow('➕','รวมรายการย่อย',moneyThai(itemTotal))]:[]),
   ...(items.length?[{type:'text',text:Math.abs(diff)<0.01?'✅ รายการย่อยรวมตรงกับยอดจ่ายจริง':'⚠️ รายการย่อยต่างจากยอดจ่ายจริง '+moneyThai(Math.abs(diff)),size:'xs',weight:'bold',color:Math.abs(diff)<0.01?'#2F6B4F':'#9A6700',wrap:true}]:[
    {type:'text',text:'⚠️ นัดนี้มีเฉพาะยอดรวม ยังไม่มีรายการย่อยแยกหมวด',size:'sm',weight:'bold',color:'#9A6700',wrap:true},
    {type:'text',text:'กด “เพิ่ม/แก้รายการย่อย” เพื่อใส่ว่าเป็นค่าตรวจ ค่ายา ค่าแล็บ ฯลฯ แล้วหน้านี้จะแยกหมวดให้อัตโนมัติ',size:'xs',color:'#667085',wrap:true}
   ]),
   appointmentFormRow('🪪','การใช้สิทธิ',e?.coverage_used?'ใช้สิทธิ'+(e?.coverage_type?' • '+String(e.coverage_type):''):'จ่ายเอง'),
   ...(Number(e?.paid_amount||0)>0?[appointmentFormRow('💳','ช่องทาง',appointmentPaymentMethodLabel(e?.payment_method_code||e?.payment_method)),appointmentFormRow('👤','ผู้จ่าย',String(e?.payer||'—'))]:[]),
   {type:'text',text:'📎 หลักฐานการชำระ '+String(docs.length)+' รายการ',size:'xs',color:'#667085',wrap:true,margin:'md'}
  ]},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:[
   ...(docs.length?[{type:'button',style:'secondary',action:{type:'postback',label:phmsNormalizeActionLabel('📎 ดูหลักฐาน ('+String(docs.length)+')'),data:'หลักฐานค่าใช้จ่าย '+code+' 0'}}]:[]),
   ...(canUpdate?[{type:'button',style:'primary',action:{type:'postback',label:'⚙️ จัดการค่ารักษา',data:'แก้ค่าใช้จ่ายนัด '+code}},
                  {type:'button',style:'secondary',action:{type:'postback',label:docs.length?'➕ แนบหลักฐานเพิ่ม':'➕ แนบหลักฐาน',data:'แนบหลักฐานค่าใช้จ่าย '+code}}]:[]),
   {type:'button',style:'secondary',action:{type:'postback',label:'💰 หน้าค่าใช้จ่าย',data:'ค่าใช้จ่ายนัด '+code}},
   {type:'button',action:{type:'postback',label:'↩️ รายละเอียดนัด',data:'ดูนัด '+code}}
  ].slice(0,5)}
 }];
 cards[0].body.contents.push({type:'text',text:'📋 รายการย่อยทั้งหมด '+items.length+' รายการ • หน้า '+(pg+1)+'/'+totalPages,size:'sm',weight:'bold',color:'#654381',wrap:true});
 for(const [localIndex,item] of visible.entries()){
  const itemIndex=pg*pageSize+localIndex;
  cards.push({type:'bubble',size:'kilo',
   header:{type:'box',layout:'vertical',backgroundColor:'#F5EEFB',paddingAll:'16px',contents:[{type:'text',text:'💰 '+String(item.label||appointmentExpenseCategoryLabel(item.category)),size:'lg',weight:'bold',color:'#654381',wrap:true},{type:'text',text:'รายการ '+(itemIndex+1)+'/'+items.length,size:'sm',color:'#475569'}]},
   body:{type:'box',layout:'vertical',paddingAll:'16px',contents:[appointmentFormRow('💵','จำนวนเงิน',moneyThai(item.amount)),appointmentFormRow('📂','หมวด',appointmentExpenseCategoryLabel(item.category))]},
   footer:{type:'box',layout:'vertical',paddingAll:'12px',contents:[{type:'button',style:'primary',color:'#6C4D87',action:{type:'postback',label:'🔎 ดูรายละเอียด',data:'รายละเอียดรายการค่ารักษา '+code+' '+itemIndex}}]}
  });
 }
 if(totalPages>1){
  cards[0].footer.contents.splice(0,0,...[
   ...(pg>0?[{type:'button',style:'secondary',action:{type:'postback',label:'⬅️ ก่อนหน้า',data:'รายละเอียดค่ารักษา '+recordCode+' หน้า '+(pg-1)}}]:[]),
   ...(pg<totalPages-1?[{type:'button',style:'secondary',action:{type:'postback',label:'ถัดไป ➡️',data:'รายละเอียดค่ารักษา '+recordCode+' หน้า '+(pg+1)}}]:[])
  ]);
 }
 await replyMessages(rt,t,[{type:'flex',altText:'🧾 รายละเอียดค่ารักษา '+moneyThai(e?.paid_amount),contents:{type:'carousel',contents:cards.slice(0,10)}}])
}
