async function phmsHospitalFinanceView(rt:string,u:string,k:string,id:string,t:string,idx:number,page=0){
 const v=one(await rpc(u,k,'phms_line_appointment_expense_summary',{p_line_user_id:id,p_limit:100}));
 if(!v||v.can_view_finance===false||v.flow_state==='permission_denied')throw new Error('access denied');
 const hs=Array.isArray(v.by_hospital)?v.by_hospital:[];
 if(!Number.isInteger(idx)||idx<0||idx>=hs.length)throw new Error('invalid hospital');
 const h=hs[idx],nm=String(h.hospital_name||''),who=String(v.person_name||'บุคคล');
 const offset=Math.max(0,Number(page)||0)*5;
 const history=one(await rpc(u,k,'phms_line_hospital_expenses_page',{p_line_user_id:id,p_hospital_name:nm,p_offset:offset,p_page_size:5}))||{};
 const rows=Array.isArray(history.items)?history.items:[];
 const total=Number(history.total_count||0);
 const pageSize=5,pg=Math.max(0,Number(page)||0);
 const body:any[]=[
  appointmentFormRow('💵','จ่ายรวม',moneyThai(h.paid_total||0)),
  appointmentFormRow('🩺','จำนวนครั้ง',String(h.visit_count||0)+' ครั้ง'),
  appointmentFormRow('📊','เฉลี่ยต่อครั้ง',moneyThai(h.paid_average||0)),
  {type:'separator'},
  {type:'text',text:'ประวัติทั้งหมด '+total+' รายการ • หน้า '+(pg+1),size:'md',weight:'bold',color:'#654381'}
 ];
 const detailButtons:any[]=[];
 for(const x of rows){
 body.push({type:'text',text:'• '+moneyThai(x.paid_amount||0)+(x.coverage_type?' • '+String(x.coverage_type):''),size:'sm',wrap:true});
 const record=String(x.record_code||x.appointment_code||x.code||'').replace(/^#/,'');
 if(/^[a-f0-9-]{8,36}$/i.test(record))detailButtons.push({type:'button',style:'secondary',action:{type:'postback',label:'🔎 ดูรายละเอียด',data:'รายละเอียดค่ารักษา '+record}});
 }
 if(!rows.length)body.push({type:'text',text:'ไม่มีรายการย่อยในข้อมูลย้อนหลังที่ดึงมาได้',size:'sm',wrap:true});
 const c={type:'bubble',size:'kilo',header:{type:'box',layout:'vertical',backgroundColor:'#F5EEFB',paddingAll:'16px',contents:[
 {type:'text',text:'💰 '+phmsHospitalShortLabel(nm||'โรงพยาบาล'),size:'lg',color:'#654381',weight:'bold',wrap:true},
 {type:'text',text:'ข้อมูลของ '+who,size:'sm',wrap:true}
 ]},body:{type:'box',layout:'vertical',paddingAll:'16px',spacing:'sm',contents:body},footer:{type:'box',layout:'vertical',paddingAll:'12px',contents:[
 ...detailButtons.slice(0,5),
 ...(pg>0?[{type:'button',style:'secondary',action:{type:'postback',label:'⬅️ ก่อนหน้า',data:'ค่าใช้จ่ายโรงพยาบาล '+idx+' '+(pg-1)}}]:[]),
 ...((pg+1)*pageSize<total?[{type:'button',style:'secondary',action:{type:'postback',label:'➡️ ถัดไป',data:'ค่าใช้จ่ายโรงพยาบาล '+idx+' '+(pg+1)}}]:[]),
 {type:'button',style:'primary',color:'#6C4D87',action:{type:'postback',label:'↩️ ค่าใช้จ่ายทั้งหมด',data:'สรุปค่าใช้จ่ายนัด'}},
 {type:'button',style:'secondary',action:{type:'postback',label:'↩️ กลับภาพรวมบุคคล',data:'กลับภาพรวมบุคคล'}}
 ]}};
 await replyMessages(rt,t,[{type:'flex',altText:'💰 ค่าใช้จ่ายของ '+who+' • '+phmsHospitalShortLabel(nm),contents:c}])
}
