function appointmentRescheduleStatusLabel(v:any){
 const s=String(v||'');
 return s==='pending'?'⏳ รอรับงาน':s==='in_progress'?'🔄 กำลังดำเนินการ':s==='completed'?'✅ เลื่อนแล้ว':s==='cancelled'?'↩️ ยกเลิก':'—'
}
function parseAppointmentRescheduleTemplate(raw:string){
 const lines=String(raw||'').replace(/\r/g,'').split('\n');
 let date='',time='',note='';
 for(const line of lines){
  const m=line.match(/^([^:：]+)[:：]\s*(.*)$/);
  if(!m)continue;
  const key=String(m[1]||'').trim(),val=String(m[2]||'').trim();
  if(['วันใหม่','วันที่ใหม่','วันนัดใหม่','วันที่นัดใหม่'].includes(key))date=val;
  else if(['เวลาใหม่','เวลานัดใหม่'].includes(key))time=val;
  else if(['หมายเหตุ','รายละเอียด'].includes(key))note=val;
 }
 if(!date||!time){
  const m=String(raw||'').match(/(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4}|\d{4}-\d{1,2}-\d{1,2})\s+(?:เวลา\s*)?(\d{1,2}:\d{2})/);
  if(m){date=date||m[1];time=time||m[2]}
 }
 let y=0,mn=0,d=0;
 let dm=date.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})$/);
 if(dm){d=Number(dm[1]);mn=Number(dm[2]);y=Number(dm[3])}
 else{
  const ym=date.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if(ym){y=Number(ym[1]);mn=Number(ym[2]);d=Number(ym[3])}
 }
 if(y>2400)y-=543;
 else if(y>0&&y<100)y+=y>=70?1900:2000;
 const tm=time.match(/^(\d{1,2}):(\d{2})$/);
 if(!y||!mn||!d||!tm)return null;
 const hh=Number(tm[1]),mm=Number(tm[2]);
 const chk=new Date(Date.UTC(y,mn-1,d));
 if(chk.getUTCFullYear()!==y||chk.getUTCMonth()!==mn-1||chk.getUTCDate()!==d||hh<0||hh>23||mm<0||mm>59)return null;
 const pad=(n:number)=>String(n).padStart(2,'0');
 const iso=String(y)+'-'+pad(mn)+'-'+pad(d)+'T'+pad(hh)+':'+pad(mm)+':00+07:00';
 if(Number.isNaN(Date.parse(iso)))return null;
 return {iso,note,date:pad(d)+'/'+pad(mn)+'/'+String(y+543),time:pad(hh)+':'+pad(mm)}
}
async function replyAppointmentRescheduleCard(rt:string,u:string,k:string,id:string,t:string,recordCode:string,prefix=''){
 const out=one(await rpc(u,k,'phms_line_appointment_reschedule_get',{p_line_user_id:id,p_record_code:recordCode}));
 const a=out?.appointment||{},r=out?.request||null,code=String(out?.record_code||recordCode);
 const body:any[]=[
  ...(prefix?[{type:'text',text:prefix,size:'sm',weight:'bold',color:'#285943',wrap:true},{type:'separator',margin:'md'}]:[]),
  appointmentFormRow('📌','นัด',String(a?.title||'นัดหมาย')),
  appointmentFormRow('📆','วันเวลาเดิม/ปัจจุบัน',appointmentCalendarLabel(a?.appointment_at)),
  ...(a?.hospital_name?[appointmentFormRow('🏥','โรงพยาบาล',phmsHospitalShortLabel(a.hospital_name))]:[])
 ];
 const footer:any[]=[];
 if(r){
  body.push(
   {type:'separator',margin:'md'},
   appointmentFormRow('🔄','สถานะงาน',appointmentRescheduleStatusLabel(r?.status)),
   ...(String(r?.entry_mode||'task')==='history'
     ?[
       appointmentFormRow('👤','ผู้เลื่อนจริง',String(r?.performer_name||r?.assignee_name||'—')),
       appointmentFormRow('✍️','ผู้บันทึก',String(r?.recorder_name||r?.requester_name||'—'))
      ]
     :[
       appointmentFormRow('👤','ผู้รับผิดชอบ',String(r?.assignee_name||'—')),
       ...(r?.requester_name?[appointmentFormRow('📨','ผู้มอบหมาย',String(r.requester_name))]:[])
      ]),
   ...(r?.reason?[appointmentFormRow('📝','เหตุผล/รายละเอียด',String(r.reason))]:[]),
   ...(r?.new_appointment_at?[appointmentFormRow('✅','วันเวลาใหม่',appointmentCalendarLabel(r.new_appointment_at))]:[])
  );
  if(r?.status==='pending'&&r?.is_assignee===true){
   footer.push({type:'button',style:'primary',action:{type:'postback',label:'✅ รับงาน',data:'รับงานเลื่อนนัด '+String(r.code||'')}});
  }
  if(['pending','in_progress'].includes(String(r?.status||''))&&(r?.is_assignee===true||out?.can_manage===true)){
   footer.push({type:'button',style:'primary',action:{type:'postback',label:r?.is_assignee===true?'📆 บันทึกว่าเลื่อนแล้ว':'📆 บันทึกผลแทน',data:'บันทึกว่าเลื่อนแล้ว '+String(r.code||'')}});
   footer.push({type:'button',style:'secondary',action:{type:'postback',label:'❌ ยกเลิกงาน',data:'ยกเลิกงานเลื่อนนัด '+String(r.code||'')}});
  }
  if(['completed','cancelled'].includes(String(r?.status||''))&&out?.can_manage===true){
   footer.push({type:'button',style:'primary',action:{type:'postback',label:'🔄 เลื่อนอีกครั้ง',data:'เริ่มเลื่อนนัดเอง '+code}});
   footer.push({type:'button',style:'secondary',action:{type:'postback',label:'👤 มอบหมายคนอื่น',data:'มอบหมายคนเลื่อนนัด '+code+' 0'}});
  }
 }else if(out?.can_manage===true){
  body.push(
   {type:'separator',margin:'md'},
   {type:'text',text:'เลือกว่าจะดำเนินการเอง หรือมอบหมายสมาชิกคนอื่นให้ช่วยติดต่อเลื่อนนัด',size:'sm',wrap:true,color:'#555555'}
  );
  footer.push({type:'button',style:'primary',action:{type:'postback',label:'🙋 ฉันจะเลื่อนเอง',data:'เริ่มเลื่อนนัดเอง '+code}});
  footer.push({type:'button',style:'secondary',action:{type:'postback',label:'👤 มอบหมายคนอื่น',data:'มอบหมายคนเลื่อนนัด '+code+' 0'}});
  footer.push({type:'button',style:'secondary',action:{type:'postback',label:'📝 บันทึกว่าเลื่อนแล้ว',data:'บันทึกประวัติเลื่อนนัด '+code+' 0'}});
 }
 if(out?.can_manage===true)footer.push({type:'button',action:{type:'postback',label:'📅 กลับรายละเอียดนัด',data:'ดูนัด '+code}});
 else footer.push({type:'button',action:{type:'postback',label:'🏡 หน้าเริ่มต้น',data:'กลับหน้าเริ่มต้น'}});
 await replyMessages(rt,t,[{type:'flex',altText:'🔄 งานเลื่อนนัด',contents:{type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:'#FFF7E8',paddingAll:'18px',contents:[
   {type:'text',text:'🔄 เลื่อนนัด',weight:'bold',size:'xl',color:'#805B18'},
   {type:'text',text:r?appointmentRescheduleStatusLabel(r?.status):'ยังไม่มีงานเลื่อนนัด',size:'sm',color:'#8A6B2F',margin:'sm',wrap:true}
  ]},
  body:{type:'box',layout:'vertical',spacing:'md',paddingAll:'16px',contents:body},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:footer.slice(0,5)}
 }}])
}
async function routeAppointmentReschedule(cmd:string,rt:string,u:string,k:string,id:string,t:string){
 let m=cmd.match(/^เลื่อนนัด\s+#?([0-9a-fA-F-]{8,36})$/);
 if(m){try{await replyAppointmentRescheduleCard(rt,u,k,id,t,m[1]);return true}catch(err){console.error('reschedule_open',String(err));await reply(rt,'⚠️ ยังเปิดงานเลื่อนนัดไม่ได้',t);return true}}

 m=cmd.match(/^เริ่มเลื่อนนัดเอง\s+#?([0-9a-fA-F-]{8,36})$/);
 if(m){
  try{
   const rr=one(await rpc(u,k,'phms_line_appointment_reschedule_create',{p_line_user_id:id,p_record_code:m[1],p_mode:'self',p_assignee_code:null,p_reason:null,p_requested_appointment_at:null}));
   await state(u,k,id,'appointment_reschedule_input',{record_code:String(rr?.record_code||m[1]),request_code:String(rr?.request_code||'')});
   await reply(rt,'🙋 เริ่มงานเลื่อนนัดแล้ว\n\nเมื่อโทร/ติดต่อและได้วันใหม่ ให้กรอกแล้วส่งกลับมา:\n\nวันใหม่: 20/10/2569\nเวลาใหม่: 10:30\nหมายเหตุ: ติดต่อ รพ. แล้ว',t,[pb('❌ ยกเลิก','ยกเลิกงานเลื่อนนัด '+String(rr?.request_code||''))]);
  }catch(err){
   const msg=String(err);
   if(msg.includes('already_active'))await replyAppointmentRescheduleCard(rt,u,k,id,t,m[1],'ℹ️ นัดนี้มีงานเลื่อนนัดที่ยังไม่ปิดอยู่แล้ว');
   else await reply(rt,'⚠️ ยังเริ่มงานเลื่อนนัดไม่ได้',t,[pb('📅 กลับนัด','ดูนัด '+m[1])])
  }
  return true
 }

 m=cmd.match(/^มอบหมายคนเลื่อนนัด\s+#?([0-9a-fA-F-]{8,36})(?:\s+(\d+))?$/);
 if(m){
  try{
   const out=one(await rpc(u,k,'phms_list_line_appointment_assignee_options',{p_line_user_id:id,p_record_code:m[1]}));
   const rows=(Array.isArray(out?.items)?out.items:[]).filter((x:any)=>x?.line_ready===true&&x?.user_id);
   const pageSize=8,pg=Math.max(0,Number(m[2]||0)),page=rows.slice(pg,pg+pageSize),code=String(out?.record_code||m[1]);
   if(!page.length){await reply(rt,'👤 ยังไม่มีสมาชิกบัญชีที่เชื่อม LINE พร้อมรับงานเลื่อนนัด',t,[pb('↩️ กลับ','เลื่อนนัด '+code)]);return true}
   const q:any[]=page.map((x:any)=>pb(phmsNormalizeActionLabel('👤 '+String(x?.display_name||'สมาชิก')),'เลือกคนเลื่อนนัด '+code+' '+String(x?.selection_code||'')));
   if(pg>0)q.push(pb('⬅️ ก่อนหน้า','มอบหมายคนเลื่อนนัด '+code+' '+String(Math.max(0,pg-pageSize))));
   if(pg+page.length<rows.length)q.push(pb('➡️ ถัดไป','มอบหมายคนเลื่อนนัด '+code+' '+String(pg+pageSize)));
   q.push(pb('❌ ยกเลิก','เลื่อนนัด '+code));
   await reply(rt,'👤 มอบหมายให้ใครช่วยเลื่อนนัด?\n\nอิ่มอุ่นจะส่งแจ้งเตือนไปหาคนนั้นทันที และให้สิทธิ์เฉพาะงานเลื่อนนัดนี้ ไม่ได้สิทธิ์แก้นัดอื่น',t,q.slice(0,13));
  }catch(err){console.error('reschedule_picker',String(err));await reply(rt,'⚠️ ยังเปิดรายชื่อผู้รับงานไม่ได้',t)}
  return true
 }

 m=cmd.match(/^เลือกคนเลื่อนนัด\s+#?([0-9a-fA-F-]{8,36})\s+([a-f0-9]{6,36})$/i);
 if(m){
  try{
   const rr=one(await rpc(u,k,'phms_line_appointment_reschedule_create',{p_line_user_id:id,p_record_code:m[1],p_mode:'delegate',p_assignee_code:m[2],p_reason:null,p_requested_appointment_at:null}));
   await replyAppointmentRescheduleCard(rt,u,k,id,t,String(rr?.record_code||m[1]),'✅ มอบหมายให้ '+String(rr?.assignee_name||'สมาชิก')+' แล้ว • ส่งแจ้งเตือนไปแล้ว');
  }catch(err){
   const msg=String(err);
   const why=msg.includes('line_required')?'สมาชิกคนนี้ยังไม่ได้เชื่อม LINE จึงรับแจ้งเตือนงานไม่ได้':msg.includes('already_active')?'นัดนี้มีงานเลื่อนนัดที่ยังไม่ปิดอยู่แล้ว':'ยังมอบหมายงานเลื่อนนัดไม่ได้';
   await reply(rt,'⚠️ '+why,t,[pb('↩️ กลับ','เลื่อนนัด '+m[1])])
  }
  return true
 }

 m=cmd.match(/^บันทึกประวัติเลื่อนนัด\s+#?([0-9a-fA-F-]{8,36})(?:\s+(\d+))?$/);
 if(m){
  try{
   const out=one(await rpc(u,k,'phms_list_line_appointment_assignee_options',{p_line_user_id:id,p_record_code:m[1]}));
   const rows=(Array.isArray(out?.items)?out.items:[]).filter((x:any)=>x?.user_id);
   const pageSize=8,pg=Math.max(0,Number(m[2]||0)),page=rows.slice(pg,pg+pageSize),code=String(out?.record_code||m[1]);
   if(!page.length){
    await reply(rt,'👤 ยังไม่มีสมาชิกที่มีบัญชีให้เลือกเป็นคนที่เลื่อนจริง',t,[pb('↩️ กลับ','เลื่อนนัด '+code)]);
    return true
   }
   const q:any[]=page.map((x:any)=>pb(
    phmsNormalizeActionLabel('👤 '+String(x?.display_name||'สมาชิก')),
    'เลือกผู้เลื่อนจริง '+code+' '+String(x?.selection_code||'')
   ));
   if(pg>0)q.push(pb('⬅️ ก่อนหน้า','บันทึกประวัติเลื่อนนัด '+code+' '+String(Math.max(0,pg-pageSize))));
   if(pg+page.length<rows.length)q.push(pb('➡️ ถัดไป','บันทึกประวัติเลื่อนนัด '+code+' '+String(pg+pageSize)));
   q.push(pb('❌ ยกเลิก','เลื่อนนัด '+code));
   await reply(rt,'📝 ใครเป็นคนติดต่อ/ดำเนินการเลื่อนนัดจริง?\n\nคุณกำลังเป็น “ผู้บันทึก” ประวัติ ส่วนชื่อที่เลือกด้านล่างคือ “ผู้เลื่อนจริง”',t,q.slice(0,13));
  }catch(err){console.error('reschedule_history_picker',String(err));await reply(rt,'⚠️ ยังเปิดรายชื่อคนที่เลื่อนนัดไม่ได้',t)}
  return true
 }

 m=cmd.match(/^เลือกผู้เลื่อนจริง\s+#?([0-9a-fA-F-]{8,36})\s+([a-f0-9]{6,36})$/i);
 if(m){
  await state(u,k,id,'appointment_reschedule_history_input',{record_code:m[1],performer_code:m[2]});
  await reply(rt,'📝 บันทึกประวัติการเลื่อนนัด\n\nกรอกวัน/เวลาใหม่ตามที่เลื่อนจริง:\n\nวันใหม่: 20/10/2569\nเวลาใหม่: 10:30\nหมายเหตุ: แอนโทรเลื่อนกับโรงพยาบาลแล้ว\n\nอิ่มอุ่นจะเก็บแยกว่า “คนเลื่อนจริง” กับ “คนที่บันทึกข้อมูล” เป็นคนละคน',t,[pb('❌ ยกเลิก','เลื่อนนัด '+m[1])]);
  return true
 }

 m=cmd.match(/^รับงานเลื่อนนัด\s+#?([0-9a-fA-F-]{8,36})$/);
 if(m){
  try{
   const rr=one(await rpc(u,k,'phms_line_appointment_reschedule_accept',{p_line_user_id:id,p_request_code:m[1]}));
   await state(u,k,id,'appointment_reschedule_input',{record_code:String(rr?.record_code||''),request_code:String(rr?.request_code||m[1])});
   await reply(rt,'✅ รับงานเลื่อนนัดแล้ว\n\nเมื่อได้วันนัดใหม่ ให้กรอก:\n\nวันใหม่: 20/10/2569\nเวลาใหม่: 10:30\nหมายเหตุ: ติดต่อ รพ. แล้ว',t,[pb('🔄 ดูงาน','เลื่อนนัด '+String(rr?.record_code||''))]);
  }catch(err){console.error('reschedule_accept',String(err));await reply(rt,'⚠️ รับงานนี้ไม่ได้ อาจไม่ใช่งานที่มอบหมายให้บัญชีคุณ หรือถูกปิดไปแล้ว',t)}
  return true
 }

 m=cmd.match(/^บันทึกว่าเลื่อนแล้ว\s+#?([0-9a-fA-F-]{8,36})$/);
 if(m){
  try{
   const rr=one(await rpc(u,k,'phms_line_appointment_reschedule_accept',{p_line_user_id:id,p_request_code:m[1]}));
   await state(u,k,id,'appointment_reschedule_input',{record_code:String(rr?.record_code||''),request_code:String(rr?.request_code||m[1])});
   await reply(rt,'📆 บันทึกวันนัดใหม่\n\nกรอกแล้วส่งกลับมา:\n\nวันใหม่: 20/10/2569\nเวลาใหม่: 10:30\nหมายเหตุ: ติดต่อ รพ. แล้ว\n\nอิ่มอุ่นจะเปลี่ยนวันนัดจริงเมื่อบันทึกสำเร็จเท่านั้น',t,[pb('🔄 ดูงาน','เลื่อนนัด '+String(rr?.record_code||''))]);
  }catch(err){console.error('reschedule_complete_open',String(err));await reply(rt,'⚠️ เปิดแบบบันทึกวันใหม่ไม่ได้',t)}
  return true
 }

 m=cmd.match(/^ยกเลิกงานเลื่อนนัด\s+#?([0-9a-fA-F-]{8,36})$/);
 if(m){
  try{
   const rr=one(await rpc(u,k,'phms_line_appointment_reschedule_cancel',{p_line_user_id:id,p_request_code:m[1],p_reason:'ยกเลิกจาก LINE'}));
   await clear(u,k,id);
   await replyAppointmentRescheduleCard(rt,u,k,id,t,String(rr?.record_code||''),'↩️ ยกเลิกงานเลื่อนนัดแล้ว');
  }catch(err){console.error('reschedule_cancel',String(err));await reply(rt,'⚠️ ยกเลิกงานนี้ไม่ได้',t)}
  return true
 }

 let st:any=null;try{st=await getState(u,k,id)}catch{}
 if(String(st?.state_key||'')==='appointment_reschedule_history_input'){
  if(/^(?:เลื่อนนัด|ดูนัด|นัดหมาย|กลับ)/.test(cmd))return false;
  const data=st?.state_data||{},parsed=parseAppointmentRescheduleTemplate(cmd);
  if(!parsed){
   await reply(rt,'⚠️ อ่านวัน/เวลาใหม่ไม่ได้\n\nกรอกตามนี้:\nวันใหม่: 20/10/2569\nเวลาใหม่: 10:30\nหมายเหตุ: -',t,[pb('❌ ยกเลิก','เลื่อนนัด '+String(data?.record_code||''))]);
   return true
  }
  try{
   const rr=one(await rpc(u,k,'phms_line_appointment_reschedule_log',{
    p_line_user_id:id,
    p_record_code:String(data?.record_code||''),
    p_performer_code:String(data?.performer_code||''),
    p_new_appointment_at:parsed.iso,
    p_note:parsed.note||null
   }));
   await clear(u,k,id);
   await replyAppointmentRescheduleCard(
    rt,u,k,id,t,String(rr?.record_code||data?.record_code||''),
    '✅ บันทึกประวัติแล้ว • ผู้เลื่อนจริง: '+String(rr?.performer_name||'สมาชิก')+' • ผู้บันทึก: คุณ'
   );
  }catch(err){
   console.error('reschedule_history_log',String(err));
   await reply(rt,'⚠️ ยังบันทึกประวัติการเลื่อนนัดไม่ได้',t,[pb('↩️ กลับ','เลื่อนนัด '+String(data?.record_code||''))]);
  }
  return true
 }

 if(String(st?.state_key||'')==='appointment_reschedule_input'){
  if(/^(?:เลื่อนนัด|ดูนัด|นัดหมาย|กลับ|ยกเลิกงานเลื่อนนัด)/.test(cmd))return false;
  const data=st?.state_data||{},parsed=parseAppointmentRescheduleTemplate(cmd);
  if(!parsed){
   await reply(rt,'⚠️ อ่านวัน/เวลาใหม่ไม่ได้\n\nกรอกตามนี้ได้เลย:\nวันใหม่: 20/10/2569\nเวลาใหม่: 10:30\nหมายเหตุ: -',t,[pb('❌ ยกเลิก','ยกเลิกงานเลื่อนนัด '+String(data?.request_code||''))]);
   return true
  }
  try{
   const rr=one(await rpc(u,k,'phms_line_appointment_reschedule_complete',{p_line_user_id:id,p_request_code:String(data?.request_code||''),p_new_appointment_at:parsed.iso,p_note:parsed.note||null}));
   await clear(u,k,id);
   await replyAppointmentRescheduleCard(rt,u,k,id,t,String(rr?.record_code||data?.record_code||''),'✅ เลื่อนนัดเรียบร้อยแล้ว • ส่งแจ้งเตือนกลับผู้มอบหมายและผู้เกี่ยวข้องแล้ว');
  }catch(err){
   const msg=String(err);
   const why=msg.includes('must_be_future')?'วันเวลาใหม่ต้องเป็นเวลาในอนาคต':msg.includes('changed_since')?'นัดนี้ถูกคนอื่นแก้วันเวลาไปแล้ว เปิดงานใหม่เพื่อตรวจสอบก่อน':'ยังบันทึกการเลื่อนนัดไม่ได้';
   await reply(rt,'⚠️ '+why,t,[pb('🔄 ดูงาน','เลื่อนนัด '+String(data?.record_code||''))]);
  }
  return true
 }
 return false
}



function appointmentPrevisitTrendLabel(v:any){
 const x=String(v||'');
 return ({new:'อาการใหม่',stable:'คงเดิม',better:'ดีขึ้น',worse:'แย่ลง',fluctuating:'เป็น ๆ หาย ๆ'} as any)[x]||''
}
function parseAppointmentPrevisitSymptomText(text:string):{symptom_text:string,onset_text:string,severity:number|null|undefined,trend:string|undefined,associated_symptoms:string,actions_taken:string,note:string,severity_dimension?:string,functional_impact?:number|null}{
 const raw=String(text||'').trim(),x=parsePhmsTemplate(raw);
 const pick=(...keys:string[])=>{for(const k of keys){const v=String(x?.[k]??'').trim();if(v&&v!=='-'&&v!=='—')return v}return ''};
 let symptom=pick('อาการ','อาการผิดปกติ','อาการหลัก');
 if(!symptom&&!raw.includes('\n')&&!raw.includes(':'))symptom=raw;
 let severity:number|undefined;
 const sm=(pick('ระดับอาการ','ระดับ','ความรุนแรง')||raw).match(/\b(10|[0-9])\s*\/\s*10\b/);
 if(sm)severity=Number(sm[1]);
 let tr=pick('แนวโน้ม','อาการเปลี่ยนแปลง').toLowerCase();
 if(!tr){if(/แย่ลง|มากขึ้น|หนักขึ้น/.test(raw))tr='worse';else if(/ดีขึ้น|ลดลง|เบาลง/.test(raw))tr='better';else if(/เป็น.?ๆ.*หาย.?ๆ|ขึ้น.?ๆ.*ลง.?ๆ/.test(raw))tr='fluctuating';else if(/คงเดิม|เท่าเดิม/.test(raw))tr='stable'}
 const trend=/แย่|worse/.test(tr)?'worse':/ดี|better/.test(tr)?'better':/เป็น|fluct|ขึ้น.*ลง/.test(tr)?'fluctuating':/คง|stable|เท่าเดิม/.test(tr)?'stable':/ใหม่|new/.test(tr)?'new':undefined;
 return {symptom_text:symptom,onset_text:pick('เริ่มเมื่อ','เริ่มมีอาการ','เริ่ม'),severity,trend,
  associated_symptoms:pick('อาการร่วม'),actions_taken:pick('สิ่งที่ทำไปแล้ว','ทำอะไรไปแล้ว','การดูแลที่ทำแล้ว'),note:pick('หมายเหตุ')}
}
function phmsPrevisitDiseaseGroup(w:any):string{
 const z=[w?.item?.title,w?.item?.care_topic,w?.item?.department,w?.item?.diagnosis_summary].filter(Boolean).join(' ').toLowerCase();
 if(/ต้อหิน|ต้อกระจก|จักษุ|ดวงตา|ตาแดง|ตาพร่ามัว|ปวดตา|ตรวจตา|glaucoma|ophthalm/.test(z))return 'eye';
 if(/ปัสสาวะ|ไต|ระบบทางเดินปัสสาวะ|urolog/.test(z))return 'urinary';
 if(/หัวใจ|ความดัน|cardio|heart/.test(z))return 'cardiovascular';
 if(/เบาหวาน|น้ำตาล|diabet/.test(z))return 'diabetes';
 if(/กระดูก|ข้อ|เข่า|สะโพก|กล้ามเนื้อ|ortho/.test(z))return 'musculoskeletal';
 return 'general'
}
async function phmsPrevisitQuestions(u:string,k:string,group:string){
 const r=await fetch(u+'/rest/v1/previsit_template_questions?select=question_th,safety_screen&enabled=eq.true&disease_group=eq.'+encodeURIComponent(group)+'&order=sort_order.asc&limit=6',{headers:{apikey:k,Authorization:'Bearer '+k}});
 if(!r.ok)throw Error('template_fetch_failed');
 return await r.json()
}
function phmsPrevisitReviewText(p:any,group:string){
 return '💙 ตรวจข้อมูลก่อนบันทึก\\n\\nอาการ: '+String(p.symptom_text||'ไม่ได้ระบุ')+
 '\\nเริ่มเมื่อ: '+String(p.onset_text||'ยังไม่ได้ระบุ')+
 '\\nระดับอาการ: '+(p.severity==null?'ยังไม่ได้ประเมิน':String(p.severity)+'/10')+
 '\\nแนวโน้ม: '+String(p.trend==='worse'?'แย่ลง':p.trend==='better'?'ดีขึ้น':p.trend==='stable'?'คงเดิม':p.trend==='fluctuating'?'เป็น ๆ หาย ๆ':'ยังไม่ได้ระบุ')+
 '\\nอาการร่วม: '+String(p.associated_symptoms||'ยังไม่ได้ระบุ')+
 '\\n\\nตรวจว่าข้อมูลตรงกับที่เล่าแล้วจึงกดบันทึก หากผิดให้แก้ไขก่อน'
}
async function replyAppointmentPrevisitSymptomPrompt(rt:string,u:string,k:string,id:string,t:string,recordCode:string,afterAction=''){
 const access=one(await rpc(u,k,'phms_line_appointment_previsit_symptoms',{p_line_user_id:id,p_record_code:recordCode,p_limit:1}))||{};
 if(access.can_add!==true){await reply(rt,'🔒 ยังไม่มีสิทธิ์เพิ่มอาการของบุคคลนี้ ให้ผู้มีสิทธิ์จัดการเปิดสิทธิ์ให้ก่อนนะ',t,[pb('📅 ดูนัด','ดูนัด '+recordCode)]);return}
 const w=one(await rpc(u,k,'phms_line_appointment_workspace',{p_line_user_id:id,p_record_code:recordCode}));
 const code=String(w?.record_code||recordCode);
 const group=phmsPrevisitDiseaseGroup(w);
 const questions=await phmsPrevisitQuestions(u,k,group);
 const extra=questions.length?'\\n\\nคำถามช่วยจำสำหรับนัดนี้:\\n'+questions.map((x:any,i:number)=>String(i+1)+'. '+x.question_th).join('\\n'):'';

 await state(u,k,id,'appointment_previsit_symptom_add',{record_code:code,after_action:afterAction});
 await reply(rt,'🩺 บันทึกอาการก่อนนัด\n\nเล่าอาการเป็นประโยคธรรมดาได้เลย เช่น “ยายปวดตาขวามา 2 วัน ปวด 5/10 มากขึ้นตอนเย็น”\n\nระดับปวดเทียบง่าย ๆ:\n0 = ไม่ปวด\n1–3 = ปวดน้อย ยังทำกิจวัตรได้\n4–6 = ปวดปานกลาง ต้องพักหรือลดกิจกรรม\n7–9 = ปวดมาก ทำกิจวัตรลำบาก\n10 = ปวดมากที่สุดเท่าที่นึกภาพได้\n\nจะใช้รูปแบบนี้ก็ได้:\nอาการ:\nเริ่มเมื่อ:\nระดับอาการ: /10\nแนวโน้ม:\nหมายเหตุ:\n\nผลกระทบต่อกิจวัตร: 0 = ปกติ, 1 = รบกวนเล็กน้อย, 2 = ทำบางอย่างได้น้อยลง, 3 = ทำกิจวัตรลำบากมาก, 4 = ทำกิจวัตรตามปกติไม่ได้\\nพิมพ์เช่น ผลกระทบต่อกิจวัตร: 2\\n\\n⚠️ อาการฉุกเฉินไม่ควรรอนัดแพทย์'+extra,t,[
  ...(afterAction==='early_visit'?[pb('➡️ ไว้บันทึกทีหลัง','ข้ามอาการไปก่อนนัด '+code)]:[]),
  pb('❌ ยกเลิก','ยกเลิกอาการก่อนนัด '+code)
 ])
}
