 const info=one(await rpc(u,k,'phms_line_appointment_source_info',{p_line_user_id:id,p_record_code:earlyCode}))||{};
 if(info?.source_kind!=='early_visit'||!info?.source_code)throw new Error('not_early_visit');
 const old=one(await rpc(u,k,'phms_line_appointment_workspace',{
  p_line_user_id:id,p_record_code:String(info.source_code)
 }))||{};
 const nowHospital=String(w?.item?.hospital_name||'').trim();
 const oldHospital=String(old?.item?.hospital_name||'').trim();
 const same=!!nowHospital&&nowHospital===oldHospital;
