function appointmentLocalIsoParts(v:any){
 const d=new Date(String(v||''));if(Number.isNaN(d.getTime()))return {date:'',time:''};
 try{
  const parts=new Intl.DateTimeFormat('en-CA',{
   timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit',
   hour:'2-digit',minute:'2-digit',hourCycle:'h23'
  }).formatToParts(d);
  const p:any={};for(const x of parts)p[x.type]=x.value;
  return {date:String(p.year||'')+'-'+String(p.month||'')+'-'+String(p.day||''),time:String(p.hour||'')+':'+String(p.minute||'')}
 }catch{return {date:'',time:''}}
}
