/* PHMS_WOUND_VISIT_SERIES_UI_V1
 A proposed series is never persisted until the explicit green confirm action.
 Both client and SQL validate authorization, anchor date, max count and duplicates.
*/
function phmsWoundSeriesEligible(item:any){
 const typ=String(item?.appointment_type||'');
 const title=String(item?.title||'');
 // Only a wound-care or surgical visit may offer repeat wound dressing;
 // generic procedures must not be treated as wound care.
 return /(?:ล้างแผล|ทำแผล|เย็บแผล|ผ่าตัด|ดูแลแผล)/.test(title)&&
  !['cancelled','no_show','rescheduled'].includes(String(item?.status||'scheduled'))
}
function phmsWoundSeriesDates(appointmentAt:any,interval:number,count:number){
 if(!Number.isInteger(interval)||interval<1||interval>30||!Number.isInteger(count)||count<1||count>10)throw Error('wound_schedule_invalid');
 const start=new Date(String(appointmentAt||'')).getTime();
 if(!Number.isFinite(start))throw Error('wound_source_date_missing');
 const rows:any[]=[];
 for(let i=1;i<=count;i++){
  const date=new Date(start+i*interval*86400000);
  if(date.getTime()<=Date.now())throw Error('wound_schedule_not_future');
  rows.push({at:date.toISOString(),label:appointmentDateOnlyLabel(date.toISOString())+' • '+appointmentTimeOnlyLabel(date.toISOString())})
 }
 return rows
}
async function phmsWoundSeriesSource(u:string,k:string,id:string,code:string){
 try{await syncAppointmentOwnerContext(u,k,id,code)}catch{}
 const w=one(await rpc(u,k,'phms_line_appointment_workspace',{p_line_user_id:id,p_record_code:code}))||{};
 const caps=one(await rpc(u,k,'phms_line_record_capabilities',{p_line_user_id:id,p_resource:'appointment',p_record_code:code}))||{};
 const allowed=one(await rpc(u,k,'phms_line_wound_series_can_create',{p_line_user_id:id,p_record_code:code}))||{};
 if(!w?.item||caps?.can_update!==true||allowed?.can_create!==true||!phmsWoundSeriesEligible(w.item))throw Error('wound_plan_permission_or_source');
 return w
}

async function replyAppointmentMoreMenu(rt:string,u:string,k:string,id:string,t:string,recordCode:string){
 const w=one(await rpc(u,k,'phms_line_appointment_workspace',{p_line_user_id:id,p_record_code:recordCode}));
 const caps=one(await rpc(u,k,'phms_line_record_capabilities',{p_line_user_id:id,p_resource:'appointment',p_record_code:recordCode}));
 const ac=one(await rpc(u,k,'phms_line_appointment_action_capabilities',{p_line_user_id:id,p_record_code:recordCode}));
 const code=String(w?.record_code||recordCode),status=String(w?.item?.status||'scheduled');
 const canUpdate=caps?.can_update===true,canSensitive=caps?.can_view_sensitive===true;
 let canCreateHere=false;
 if(canUpdate&&phmsWoundSeriesEligible(w?.item)){
  try{
   const chk=one(await rpc(u,k,'phms_line_wound_series_can_create',{p_line_user_id:id,p_record_code:code}))||{};
   canCreateHere=chk.can_create===true;
  }catch(err){console.error('wound_series_optional_gate',String(err))}
 }
 if(!canUpdate){await reply(rt,'🔒 ไม่มีสิทธิ์จัดการนัดนี้',t,[pb('↩️ รายละเอียดนัด','ดูนัด '+code)]);return}
 const q:any[]=[
  pb('👥 คนรับผิดชอบ / คนขับ','ผู้รับผิดชอบนัด '+code),
  pb('👥 LINE กลุ่ม','วิธีแจ้งในกลุ่ม '+code),
  ...(canSensitive?[pb('📎 เอกสารของนัด','เอกสารนัด '+code)]:[]),
  pb('🔗 เชื่อมนัด','เชื่อมนัด '+code+' 0'),
  ...(canCreateHere?[pb('🩹 ล้างแผลต่อเนื่อง','แผนล้างแผล '+code)]:[]),
  ...(ac?.can_post_visit===true&&canSensitive?[pb('💰 ค่าใช้จ่ายหลังนัด','ค่าใช้จ่ายนัด '+code)]:[]),
  ...(ac?.can_manage_status===true&&['scheduled','confirmed','arrived'].includes(status)?[
   pb('🚫 ไม่ได้ไปตามนัด','ไม่ได้ไปตามนัด '+code),
   pb('❌ ยกเลิกนัด','ยกเลิกนัด '+code)
  ]:[]),
  pb('🗑️ ย้ายเข้าถังขยะ','ย้ายรายการเข้าถังขยะ appointment '+code),
  pb('↩️ กลับเมนูแก้ไข','แก้ไขนัดนี้ '+code)
 ];
 await reply(rt,'⋯ เพิ่มเติม\n\n'+String(w?.item?.title||'นัดหมาย'),t,q.slice(0,13))
}

