async function appointmentEditPicker(rt:string,u:string,k:string,id:string,t:string,mode='edit'){
 const ov=one(await rpc(u,k,'phms_line_appointment_overview',{p_line_user_id:id,p_upcoming_limit:10,p_history_limit:1}));
 const who=String(ov?.person_name||await name(u,k,id));
 let items=[...(Array.isArray(ov?.upcoming)?ov.upcoming:[]),...(Array.isArray(ov?.overdue)?ov.overdue:[])]
  .filter((x:any)=>['scheduled','confirmed','arrived'].includes(String(x?.status||'scheduled')))
  .sort((a:any,b:any)=>appointmentSortTimestamp(a?.appointment_at)-appointmentSortTimestamp(b?.appointment_at));
 const hadCandidates=items.length>0;
 if(mode==='reschedule'){
  const allowed=await Promise.all(items.map(async (x:any)=>{
   const code=String(x?.code||'');if(!code)return false;
   try{const caps=one(await rpc(u,k,'phms_line_record_capabilities',{p_line_user_id:id,p_resource:'appointment',p_record_code:code}))||{};return caps.can_update===true}
   catch{return false}
  }));
  items=items.filter((_:any,i:number)=>allowed[i])
 }
 if(!items.length){
   const access=await appointmentEffectiveAccess(u,k,id);
   await reply(rt,mode==='reschedule'?(hadCandidates?'🔒 มีนัดให้ดู แต่ยังไม่มีสิทธิ์เลื่อนนัด':'📆 ยังไม่มีนัดที่เลื่อนได้ตอนนี้'):'📅 ยังไม่มีนัดที่แก้ไขได้ตอนนี้',t,[...(access?.create===true?[pb('➕ เพิ่มนัด','เพิ่มนัด')]:[]),pb('↩️ กลับนัดหมาย','นัดหมายบุคคลปัจจุบัน')]);
   return
 }
 const cards=items.slice(0,10).map((x:any,i:number)=>{
   const code=String(x?.code||''),cd=appointmentCountdownLabel(x?.appointment_at);
   return {type:'bubble',size:'kilo',
    header:{type:'box',layout:'vertical',backgroundColor:'#FFF7E8',paddingAll:'18px',contents:[
      {type:'text',text:(mode==='reschedule'?'📆 นัด #':'✏️ นัด #')+String(i+1)+(cd?' ('+cd+')':''),size:'xs',color:'#8A6B2F',weight:'bold',wrap:true},
      {type:'text',text:String(x?.title||'นัดหมาย'),size:'lg',weight:'bold',wrap:true,margin:'sm'}
    ]},
    body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'18px',contents:[
      appointmentFormRow('🏷️','ประเภท',appointmentTypeLabel(x?.appointment_type)),
      appointmentFormRow('📆','วันนัด',appointmentDateOnlyLabel(x?.appointment_at)),
      appointmentFormRow('🕐','เวลา',appointmentTimeOnlyLabel(x?.appointment_at)),
      appointmentFormRow('🏥','โรงพยาบาล',phmsHospitalShortLabel(x?.hospital_name||'—')),
      ...(x?.care_topic?[appointmentFormRow('🧭','เรื่องรักษา',x.care_topic)]:[]),
      ...(x?.doctor_name?[appointmentFormRow(appointmentDoctorEmoji(x.doctor_name),'หมอ',appointmentDoctorShortLabel(x.doctor_name))]:[]),
      appointmentFormRow('✅','สถานะ',appointmentStatusLabel(x?.status))
    ]},
    footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'16px',contents:[
      {type:'button',style:'primary',action:{type:'postback',label:mode==='reschedule'?'📆 เลื่อนนัดนี้':'✏️ จัดการนัดนี้',data:(mode==='reschedule'?'เลื่อนนัด ':'แก้ไขนัดนี้ ')+code}}
    ]}
   }
 });
 const flex:any={type:'flex',altText:mode==='reschedule'?'📆 เลือกนัดที่ต้องการเลื่อน':'✏️ เลือกนัดของ '+who+' ที่ต้องการแก้',contents:{type:'carousel',contents:cards}};
 flex.quickReply={items:[pb('↩️ กลับนัดหมาย','นัดหมายบุคคลปัจจุบัน')]};
 await replyMessages(rt,t,[flex])
}
