async function replyAppointmentTaskSelectedEvidence(
 rt:string,u:string,k:string,id:string,t:string,taskCode:string
){
 const task=one(await rpc(u,k,'phms_line_appointment_get_task',{p_line_user_id:id,p_task_code:taskCode}));
 const appointmentCode=String(task?.appointment_code||'');
 const ev=one(await rpc(u,k,'phms_line_appointment_task_evidence_list',{
  p_line_user_id:id,p_record_code:appointmentCode
 }));
 const items=(Array.isArray(ev?.items)?ev.items:[]).filter((x:any)=>String(x?.task_code||'')===String(task?.task_code||taskCode));
 const cards:any[]=[{type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:'#EEF6FF',paddingAll:'16px',contents:[
   {type:'text',text:'🖼️ หลักฐานที่เลือกแล้ว',weight:'bold',size:'xl',color:'#365F8D',wrap:true},
   {type:'text',text:String(task?.title||'รายการเตรียมก่อนนัด'),size:'sm',weight:'bold',wrap:true,margin:'sm'}
  ]},
  body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'14px',contents:[
   {type:'text',text:items.length?'มี '+String(items.length)+' รูป/ไฟล์':'ยังไม่มีหลักฐานที่เลือกไว้',size:'md',weight:'bold',wrap:true},
   {type:'text',text:'ไฟล์เหล่านี้ผูกกับ checklist ข้อนี้และอยู่ในเอกสารของนัดด้วย',size:'sm',color:'#667085',wrap:true}
  ]},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'10px',contents:[
   {type:'button',style:'primary',action:{type:'postback',label:'➕ เพิ่มหลักฐาน',data:'หลักฐานงานเตรียม '+String(task?.task_code||taskCode)+' 0'}},
   {type:'button',action:{type:'postback',label:'↩️ กลับ checklist',data:'สิ่งที่ต้องทำก่อนนัด '+appointmentCode}}
  ]}
 }];
 for(const item of items.slice(0,8)){
  let url='';
  try{
   if(item?.bucket_id&&item?.object_name)url=await signGalleryObject(u,k,String(item.bucket_id),String(item.object_name),1800)
  }catch(err){console.error('appointment_task_selected_evidence_sign',String(err))}
  const mime=String(item?.mime_type||'').toLowerCase(),path=String(item?.object_name||'').toLowerCase();
  const image=/^image\//.test(mime)||/\.(?:jpg|jpeg|png|webp)$/.test(path);
  cards.push({type:'bubble',size:'kilo',
   ...(image&&url?{hero:{type:'image',url,size:'full',aspectRatio:'4:3',aspectMode:'fit',backgroundColor:'#F7F9FC',action:{type:'uri',label:'เปิดรูป',uri:url}}}:{}),
   header:{type:'box',layout:'vertical',paddingAll:'14px',contents:[
    {type:'text',text:String(item?.title||'หลักฐาน'),weight:'bold',size:'md',wrap:true},
    {type:'text',text:'✅ ใช้กับ checklist ข้อนี้แล้ว',size:'xs',color:'#2F6B4F',margin:'sm',wrap:true}
   ]},
   body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'14px',contents:[
    ...(item?.origin_title?[appointmentFormRow('🧭','ต้นทาง',String(item.origin_title))]:[]),
    ...(item?.origin_appointment_at?[appointmentFormRow('📆','วันที่ต้นทาง',appointmentDateOnlyLabel(item.origin_appointment_at))]:[]),
    appointmentFormRow('📎','สถานะ','เป็นหลักฐานของรายการเตรียม')
   ]},
   footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'10px',contents:[
    ...(url?[{type:'button',style:'primary',action:{type:'uri',label:image?'🖼️ เปิดรูปเต็ม':'📄 เปิดเอกสาร',uri:url}}]:[]),
    {type:'button',action:{type:'postback',label:'↩️ กลับ checklist',data:'สิ่งที่ต้องทำก่อนนัด '+appointmentCode}}
   ]}
  })
 }
 await replyMessages(rt,t,[{type:'flex',altText:'🖼️ หลักฐาน '+String(task?.title||''),contents:{type:'carousel',contents:cards.slice(0,10)}}])
}

async function replyAppointmentTaskEvidencePicker(
 rt:string,u:string,k:string,id:string,t:string,taskCode:string,offset=0,prefix=''
){
 const pageSize=5;
 const out=one(await rpc(u,k,'phms_line_appointment_task_evidence_candidates',{
  p_line_user_id:id,p_task_code:taskCode,p_limit:pageSize,p_offset:Math.max(0,Number(offset)||0)
 }));
 const items=Array.isArray(out?.items)?out.items:[];
 const selected=Number(out?.selected_count||0);
 const available=Number(out?.available_count||0);
 const off=Number(out?.offset||0);
 const code=String(out?.task_code||taskCode);
 const appointmentCode=String(out?.appointment_code||'');
 const title=String(out?.task_title||'รายการเตรียมก่อนนัด');
 const status=String(out?.task_status||'pending');

 const summary:any={type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:'#EEF6FF',paddingAll:'18px',contents:[
   {type:'text',text:'📎 หลักฐานของรายการเตรียม',weight:'bold',size:'xl',color:'#365F8D',wrap:true},
   {type:'text',text:title,size:'sm',weight:'bold',margin:'sm',wrap:true}
  ]},
  body:{type:'box',layout:'vertical',spacing:'md',paddingAll:'16px',contents:[
   ...(prefix?[{type:'text',text:prefix,size:'sm',weight:'bold',color:'#2F6B4F',wrap:true},{type:'separator',margin:'sm'}]:[]),
   {type:'text',text:'✅ เลือกแล้ว '+String(selected)+' รูป/ไฟล์',size:'md',weight:'bold',wrap:true},
   {type:'text',text:'เลือกเพิ่มได้หลายรูปทีละรูป • รูปที่เลือกแล้วจะหายออกจากรายการนี้ทันที',size:'sm',color:'#555555',wrap:true},
   {type:'text',text:available>0?'ยังเลือกได้อีก '+String(available)+' รูป/ไฟล์':'ไม่มีรูปที่ยังไม่ได้เลือกเหลือในคลัง',size:'xs',color:'#667085',wrap:true}
  ]},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:[
   ...(selected>0?[{type:'button',style:'primary',action:{type:'postback',label:phmsNormalizeActionLabel('🖼️ ดูหลักฐาน ('+String(selected)+')'),data:'ดูหลักฐานงานเตรียม '+code}}]:[]),
   {type:'button',style:selected>0?'secondary':'primary',action:{type:'postback',label:selected>0?'➕ เพิ่มหลักฐาน':'➕ แนบหลักฐาน',data:'ส่งหลักฐานงานเตรียม '+code}},
   ...(status==='pending'?[{type:'button',style:'secondary',action:{type:'postback',label:'☑️ ทำรายการเสร็จ',data:'ทำแล้ว '+code}}]:[]),
   {type:'button',action:{type:'postback',label:'✅ ครบแล้ว / กลับ checklist',data:'สิ่งที่ต้องทำก่อนนัด '+appointmentCode}}
  ]}
 };

 const cards:any[]=[summary];
 for(const item of items){
  try{
   const url=await signGalleryObject(u,k,String(item?.bucket_id||''),String(item?.object_name||''),600);
   cards.push(appointmentTaskEvidenceBubble(item,url,code))
  }catch(err){console.error('appointment_task_evidence_sign',String(err))}
 }
 const flex:any={type:'flex',altText:'📎 หลักฐาน '+title+' • เลือกแล้ว '+String(selected),contents:{type:'carousel',contents:cards.slice(0,10)}};
 const q:any[]=[];
 if(off>0)q.push(pb('⬅️ ก่อนหน้า','หลักฐานงานเตรียม '+code+' '+String(Math.max(0,off-pageSize))));
 if(off+items.length<available)q.push(pb('➡️ ถัดไป','หลักฐานงานเตรียม '+code+' '+String(off+pageSize)));
 if(selected>0)q.push(pb('🖼️ ดูหลักฐาน','ดูหลักฐานงานเตรียม '+code));
 q.push(pb(selected>0?'➕ เพิ่มหลักฐาน':'➕ แนบหลักฐาน','ส่งหลักฐานงานเตรียม '+code));
 if(status==='pending')q.push(pb('☑️ ทำเสร็จ','ทำแล้ว '+code));
 q.push(pb('↩️ checklist','สิ่งที่ต้องทำก่อนนัด '+appointmentCode));
 flex.quickReply={items:q.slice(0,13)};
 await replyMessages(rt,t,[flex])
}

async function galleryPage(rt:string,u:string,k:string,id:string,t:string,category='all',days=30,offset=0){
 const ownerPhoto=await phmsCategoryOwnerPhoto(u,k,id);
 let ctx:any;try{ctx=one(await rpc(u,k,'phms_get_line_context_state',{p_line_user_id:id}))}catch{}
 if(ctx?.active_scope==='family'&&!ctx?.active_family_id){
   const x=await family(u,k,id);await reply(rt,'📁 รูปและเอกสาร\n\nเลือกครอบครัวก่อน แล้วค่อยเลือกคนที่ต้องการดู',t,x.q);return
 }
 if(ctx?.active_scope==='family'&&!ctx?.active_family_person_id){
   try{
     const p:any=await people(u,k,id,'gallery');
     if(p?.auto)return await galleryPage(rt,u,k,id,t,category,days,offset);
     await reply(rt,'📁 รูปและเอกสาร\n\nก่อนเปิดคลัง เลือกคนที่ต้องการดู\n\n'+p.text,t,p.q||[]);
   }catch{await reply(rt,'📁 รูปและเอกสาร\n\nช่วยเลือกครอบครัวและคนที่ต้องการดูก่อน',t,[act('👨‍👩‍👧 ครอบครัว','ครอบครัว')])}
   return
 }
 const pageSize=7;
 let out:any=null,items:any[]=[];
 try{
  out=one(await rpc(u,k,'phms_list_line_medical_gallery_v2',{p_line_user_id:id,p_category:category,p_days:days,p_limit:pageSize,p_offset:Math.max(0,Number(offset)||0)}));
  items=Array.isArray(out?.items)?out.items:[]
 }catch(e){console.error('gallery_list',String(e));await reply(rt,'⚠️ ยังเปิดรูปและเอกสารไม่ได้ ลองอีกครั้งนะ',t,[act('🏡 หน้าเริ่มต้น','กลับหน้าเริ่มต้น')]);return}
 const who=String(out?.person_name||(ctx?.active_scope==='family'?ctx?.family_person_name:await name(u,k,id))||'ผู้ใช้');
 const total=Number(out?.total_count||0),off=Number(out?.offset||0);
 let canSelectFileOwner=false;
 try{canSelectFileOwner=(await listGalleryCreatablePeople(u,k,id)).length>0}catch{}
 let canLinkAppointment=false;
 try{
  const d=one(await rpc(u,k,'phms_get_line_person_dashboard',{p_line_user_id:id}));
  canLinkAppointment=d?.access?.appointments?.update===true||d?.access?.appointments?.create===true
 }catch{}
 const summary:any={type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:'#EEF6FF',paddingAll:'18px',contents:[
   {type:'text',text:'📁 รูปและเอกสาร',weight:'bold',size:'xl',color:'#365F8D'},
   {type:'text',text:'ข้อมูลของ '+who,size:'md',margin:'sm',wrap:true},...phmsCategoryPhotoNode(ownerPhoto)
  ]},
  body:{type:'box',layout:'vertical',spacing:'md',paddingAll:'18px',contents:[
   {type:'text',text:canSelectFileOwner?'ส่งรูปหรือ PDF ตอนนี้ อิ่มอุ่นจะถือว่าไฟล์เป็นของ “'+who+'” ก่อน':'เปิดดูไฟล์ที่มีสิทธิ์ได้ หากต้องการเพิ่มให้ผู้ดูแลช่วยบันทึก',size:'sm',wrap:true},
   {type:'text',text:'ถ้ามีไฟล์ของหลายคน ให้เปลี่ยนคนก่อนส่ง หรือไฟล์ที่ยัง “รอตรวจ” กดเปลี่ยนเจ้าของทีละใบได้',size:'sm',wrap:true,color:'#555555'},
   {type:'separator',margin:'md'},
   ...(items.length===0?[{type:'text',text:total>0?'ไม่พบเอกสารในตัวกรองนี้':'ยังไม่มีข้อมูลเอกสารที่บันทึก\nเมื่อมีบันทึกข้อมูลเอกสารแล้ว จะแสดงรายการที่นี่',size:'md',weight:'bold',wrap:true,color:'#475569'}]:[]),
   {type:'text',text:'ส่งหลายไฟล์ต่อกันได้ • ก่อนส่งให้เลือกเจ้าของก่อน อิ่มอุ่นจะผูกไฟล์ชุดที่ส่งต่อจากนั้นกับคนที่เลือก\nถ้าผูกผิดคนและไฟล์ยังรอตรวจ สามารถเปลี่ยนเจ้าของทีละไฟล์ได้',size:'xs',wrap:true,color:'#667085'},
   {type:'text',text:'ตัวกรองตอนนี้: '+galleryCategoryLabel(category)+' • '+galleryDaysLabel(days)+' • '+String(total)+' ไฟล์',size:'xs',wrap:true,color:'#777777'}
  ]},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'14px',contents:[
   ...(canSelectFileOwner?[{type:'button',style:'primary',action:{type:'postback',label:'👤 เจ้าของไฟล์',data:'เปลี่ยนคนแกลเลอรี 0'}}]:[]),
   {type:'button',style:'secondary',action:{type:'postback',label:'↩️ ภาพรวมบุคคล',data:'กลับภาพรวมบุคคล'}}
  ]}
 };
 const cards:any[]=[summary];
 for(const item of items){
   try{
     const url=await signGalleryObject(u,k,String(item.bucket_id),String(item.object_name),600);
     let apptCtx:any={linked:false};
     try{
       apptCtx=one(await rpc(u,k,'phms_line_gallery_asset_appointment_context',{
         p_line_user_id:id,p_asset_id:String(item.asset_id)
       }))||{linked:false}
     }catch(err){console.error('gallery_asset_appointment_context',String(err))}
     item.appointment_context=apptCtx;
     const linked=apptCtx?.linked===true;
     let manualText:string|null=null;
     const match=String(item.object_name||'').match(/^intake\/([0-9a-fA-F-]{36})\./);
     if(!linked&&item.lifecycle_state==='temporary'&&match)manualText='กรอกเอง '+match[1];
     let canTrash=false,canChangeOwner=false;
     try{
      const cap=one(await rpc(u,k,'phms_line_storage_asset_capabilities',{p_line_user_id:id,p_asset_id:String(item.asset_id)}));
      canTrash=cap?.can_edit===true;
      canChangeOwner=cap?.can_reassign_owner===true
     }catch{}
     cards.push(galleryBubble(item,url,null,manualText,canTrash,canLinkAppointment&&!linked,canChangeOwner))
   }catch(e){console.error('gallery_sign',String(e))}
 }
 // Owner portrait: authorized directory entry only, never a document thumbnail.
 try{
  const directory=one(await rpc(u,k,'phms_list_line_family_person_directory_v2',{p_line_user_id:id}));
  const persons=Array.isArray(directory?.people)?directory.people:[];
  const activePerson=String(ctx?.active_family_person_id||'');
  const ownerName=who.trim();
  const pick=persons.find((x:any)=>x?.can_view!==false&&activePerson&&String(x?.family_person_id||x?.id||'')===activePerson)
    ||persons.find((x:any)=>x?.can_view!==false&&[x?.display_name,x?.person_name,x?.name,x?.household_name].some((v:any)=>String(v||'').trim()===ownerName));
  if(pick?.photo_object_name){
   const photoUrl=await signedPersonPhotoUrl(u,k,String(pick.photo_object_name));
   if(photoUrl){
    summary.header.contents.push({type:'image',url:photoUrl,size:'56px',aspectRatio:'1:1',aspectMode:'cover',flex:0});
   }
  }
 }catch(err){console.error('gallery_owner_portrait',String(err))}
 // Empty gallery is a single summary card; no redundant secondary empty card.
 const flex:any={type:'flex',altText:'รูปและเอกสารของ '+who+' • '+galleryCategoryLabel(category)+' • '+galleryDaysLabel(days),contents:{type:'carousel',contents:cards.slice(0,10)}};
 const q:any[]=[...galleryQ(category,days).slice(0,5)];
 if(off>0)q.push(act('⬅️ ก่อนหน้า','แกลเลอรีหน้า '+galleryCategoryLabel(category)+' '+String(days||0)+' '+String(Math.max(0,off-pageSize))));
 if(off+items.length<total)q.push(act('➡️ ถัดไป','แกลเลอรีหน้า '+galleryCategoryLabel(category)+' '+String(days||0)+' '+String(off+pageSize)));
 q.push(
  act('🔄 เปลี่ยนคน','เปลี่ยนคนแกลเลอรี 0'),
  act('💊 ไปหน้ายา','ยา'),
  act('📅 ไปหน้านัด','นัดหมาย'),
  act('🩺 ไปหน้าสุขภาพ','สุขภาพ'),
  act('🏡 หน้าเริ่มต้น','กลับหน้าเริ่มต้น')
 );
 flex.quickReply={items:q.slice(0,13)};
 await replyMessages(rt,t,[flex])
}

const MEDIA_MAX_BYTES=10*1024*1024;
function cleanFilename(v:any){const s=String(v??'').replace(/[\\u0000-\\u001f\\u007f]/g,'').trim();return s?s.slice(0,255):null}
function hex(b:Uint8Array){return Array.from(b).map(x=>x.toString(16).padStart(2,'0')).join('')}
async function sha256(b:Uint8Array){return hex(new Uint8Array(await crypto.subtle.digest('SHA-256',new Uint8Array(b).buffer)))}
function mediaType(b:Uint8Array){
 if(b.length>=3&&b[0]===0xff&&b[1]===0xd8&&b[2]===0xff)return {mime:'image/jpeg',ext:'jpg'};
 if(b.length>=8&&b[0]===0x89&&b[1]===0x50&&b[2]===0x4e&&b[3]===0x47&&b[4]===0x0d&&b[5]===0x0a&&b[6]===0x1a&&b[7]===0x0a)return {mime:'image/png',ext:'png'};
 if(b.length>=12&&String.fromCharCode(...b.slice(0,4))==='RIFF'&&String.fromCharCode(...b.slice(8,12))==='WEBP')return {mime:'image/webp',ext:'webp'};
 if(b.length>=5&&String.fromCharCode(...b.slice(0,5))==='%PDF-')return {mime:'application/pdf',ext:'pdf'};
 return null
}
async function uploadPersonPhoto(u:string,k:string,path:string,bytes:Uint8Array,mime:string){
 const url=u+'/storage/v1/object/phms-person-photos/'+path.split('/').map(encodeURIComponent).join('/');
 const r=await fetch(url,{method:'POST',headers:{apikey:k,Authorization:'Bearer '+k,'content-type':mime,'x-upsert':'false'},body:new Uint8Array(bytes).buffer});
 if(!r.ok)throw new Error('person_photo_upload_failed:'+r.status+':'+await r.text());
 return true
}
async function uploadTemp(u:string,k:string,path:string,bytes:Uint8Array,mime:string,bucket='phms-intake-temp'){
 const url=u+'/storage/v1/object/'+bucket+'/'+path.split('/').map(encodeURIComponent).join('/');
 const r=await fetch(url,{method:'POST',headers:{apikey:k,Authorization:'Bearer '+k,'content-type':mime,'x-upsert':'false'},body:new Uint8Array(bytes).buffer});
 if(!r.ok&&r.status!==400)throw new Error('storage_upload_failed:'+r.status+':'+await r.text());
 return {ok:r.ok,status:r.status}
}
async function removeTempObject(u:string,k:string,path:string){
 const r=await fetch(u+'/storage/v1/object/phms-intake-temp',{
  method:'DELETE',
  headers:{apikey:k,Authorization:'Bearer '+k,'content-type':'application/json'},
  body:JSON.stringify({prefixes:[path]})
 });
 if(!r.ok)throw new Error('storage_remove_failed:'+r.status+':'+await r.text());
 return true
}
async function downloadTemp(u:string,k:string,path:string){
 const url=u+'/storage/v1/object/authenticated/phms-intake-temp/'+path.split('/').map(encodeURIComponent).join('/');
 const r=await fetch(url,{headers:{apikey:k,Authorization:'Bearer '+k,'cache-control':'no-store'}});
 if(!r.ok)throw new Error('storage_download_failed:'+r.status+':'+await r.text());
 return new Uint8Array(await r.arrayBuffer())
}
function documentLabel(v:string){
 const m:any={
  medication_label:'ฉลากยา',
  medication_list:'รายการยา',
  prescription:'ใบสั่งยา',
  dispense_summary:'สรุปการจ่ายยา',
  receipt:'ใบเสร็จ',
  appointment:'ใบนัด',
  medical_document:'เอกสารสุขภาพ',
  free_text:'ข้อความทั่วไป',
  unknown:'ยังระบุไม่ได้',
  other:'เอกสารอื่น'
 };
 return m[v]||'ยังระบุไม่ได้'
}

async function intakeReviewLink(u:string,k:string,sourceId:string,lineUserId:string){
 const r=await fetch(u+'/functions/v1/line-intake-review',{method:'POST',headers:{Authorization:'Bearer '+k,'content-type':'application/json'},body:JSON.stringify({action:'create_link',source_id:sourceId,line_user_id:lineUserId})});
 const txt=await r.text();let d:any=null;try{d=txt?JSON.parse(txt):null}catch{}
 if(!r.ok||!d?.ok||!d?.url)throw new Error('intake_review_link_failed:'+r.status+':'+txt.slice(0,300));
 if(d?.frontend_url)d.url=d.frontend_url;
 return d
}
function intakeReviewMessage(r:any){
 const sourceCode=String(r?.source_code||'');
 const personMismatch=Number(r?.person_mismatch_count||0)>0;
 const conflicts=Number(r?.blocking_conflict_count||0);
 const duplicates=Number(r?.duplicate_candidate_count||0)>0;
 if(conflicts>0){
   if(personMismatch){
     return {
       text:'⚠️ พบข้อมูลบุคคลไม่ตรงกัน\n\nไฟล์/รายการนี้ขัดกับบุคคลที่เลือกอยู่ ระบบจึงไม่ให้ยืนยันจนกว่าจะเลือกคนให้ถูกต้อง\n\nรหัสรับเข้า: #'+sourceCode,
       q:[act('👤 ข้อมูลของฉัน','ใช้ข้อมูลของฉัน'),act('👥 คนในครอบครัว','คนในครอบครัว'),pb('❌ ยกเลิก','ยกเลิกรับเข้า '+sourceCode)],
       needsPersonResolution:true
     }
   }
   return {
     text:'♻️ พบข้อมูลซ้ำหรือชนกับรายการเดิม\n\nระบบหยุดการยืนยันไว้เพื่อไม่ให้สร้างข้อมูลซ้ำ'+
       (duplicates?'\nพบ candidate/record ที่มี fingerprint ตรงกัน':'')+
       '\n\nรหัสรับเข้า: #'+sourceCode,
     q:[act('📁 รูปและเอกสาร','รูปและเอกสาร'),pb('❌ ยกเลิก','ยกเลิกรับเข้า '+sourceCode)],
     needsPersonResolution:false
   }
 }
 const sample=String(r?.raw_text||'').replace(/\r/g,'').trim().slice(0,650);
 const text='🔎 ตรวจข้อมูลก่อนยืนยัน'+
  '\n\n👤 ข้อมูลของ: '+String(r?.person_name||'ยังไม่ได้เลือก')+
  '\n📄 ประเภท: '+documentLabel(String(r?.document_type||'unknown'))+
  '\n🔎 รายการที่พบ: '+Number(r?.candidate_count||0)+
  (sample?'\n\n📝 ข้อความที่อ่านได้\n'+sample+(String(r?.raw_text||'').length>650?'…':''):'\n\n📝 ไม่พบข้อความที่อ่านได้ชัดเจน')+
  '\n\n⚠️ ลองตรวจสอบก่อนยืนยัน'+
  '\nการยืนยันขั้นนี้ยังไม่บันทึกเป็นข้อมูลสุขภาพจริง'+
  '\n\nรหัสรับเข้า: #'+sourceCode;
 return {text,q:[act('✅ ยืนยัน','ยืนยันรับเข้า '+sourceCode),pb('❌ ยกเลิก','ยกเลิกรับเข้า '+sourceCode),act('📁 รูปและเอกสาร','รูปและเอกสาร')],needsPersonResolution:false}
}
async function getSelfPerson(u:string,k:string,id:string,createIfMissing=false){
 const identity=await iden(u,k,id);if(!identity?.user_id)throw new Error('line_account_not_linked');
 try{const self=one(await rpc(u,k,'phms_get_line_self_profile',{p_line_user_id:id}));if(self)return {identity,person:self}}catch(err){console.error('self_profile_rpc_precheck',String(err))}
 const setup=one(await rpc(u,k,'phms_get_line_setup_state',{p_line_user_id:id}));let personId=String(setup?.self_person_id||'');
 if(!personId){try{const q=await fetch(u+'/rest/v1/persons?linked_user_id=eq.'+encodeURIComponent(String(identity.user_id))+'&status=eq.active&select=id&limit=1',{headers:H(k)});const rows=q.ok?await q.json():[];personId=String(rows?.[0]?.id||'')}catch{}}
 if(!personId&&createIfMissing){
  const body={linked_user_id:String(identity.user_id),display_name:null,nickname:null,status:'active'};
  const ins=await fetch(u+'/rest/v1/persons',{method:'POST',headers:{...H(k),Prefer:'return=representation'},body:JSON.stringify(body)});
  if(ins.ok){const rows=await ins.json().catch(()=>[]);personId=String(rows?.[0]?.id||'')}
  else{const txt=await ins.text();console.error('self_person_create',ins.status,txt.slice(0,200));const q=await fetch(u+'/rest/v1/persons?linked_user_id=eq.'+encodeURIComponent(String(identity.user_id))+'&status=eq.active&select=id&limit=1',{headers:H(k)});const rows=q.ok?await q.json():[];personId=String(rows?.[0]?.id||'')}
 }
 if(personId){try{await rpc(u,k,'phms_set_line_personal_context',{p_line_user_id:id})}catch(err){console.error('self_person_set_context',String(err))}}
 if(!personId)return {identity,person:null};
 try{const p=one(await rpc(u,k,'phms_get_line_self_profile',{p_line_user_id:id}));if(p)return {identity,person:p}}catch(err){console.error('self_profile_rpc',String(err))}
 const q=await fetch(u+'/rest/v1/persons?id=eq.'+encodeURIComponent(personId)+'&select=id,linked_user_id,nickname,first_name,last_name,date_of_birth,sex,status&limit=1',{headers:H(k)});
 const rows=q.ok?await q.json():[];return {identity,person:rows?.[0]||null}
}


function selfPersonAge(v:any){
 const s=String(v||'').trim();if(!s)return '';
 let y=0,m=1,d=1;
 let x=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
 if(x){y=Number(x[1]);m=Number(x[2]);d=Number(x[3])}
 else{x=s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})$/);if(x){d=Number(x[1]);m=Number(x[2]);y=Number(x[3])}}
 if(!y)return '';
 if(y>2400)y-=543;
 const now=new Date(Date.now()+7*3600000);let age=now.getUTCFullYear()-y;
 const cm=now.getUTCMonth()+1,cd=now.getUTCDate();if(cm<m||(cm===m&&cd<d))age--;
 return age>=0&&age<130?String(age)+' ปี':''
}
