function phmsSexThaiIcon(v:any){
 const value=String(v??'').trim().toLowerCase();
 if(['female','f','หญิง'].includes(value))return '♀️ หญิง';
 if(['male','m','ชาย'].includes(value))return '♂️ ชาย';
 return '⚪ ไม่ระบุ';
}
function personProfileSexLabel(v:any){
 const s=String(v||'').toLowerCase();
 if(['female','f','หญิง'].includes(s))return 'หญิง';
 if(['male','m','ชาย'].includes(s))return 'ชาย';
 if(['other','อื่น','อื่นๆ'].includes(s))return 'อื่นๆ';
 if(['unknown','ไม่ระบุ',''].includes(s))return 'ยังไม่ระบุ';
 return String(v||'ยังไม่ระบุ')
}
const PERSON_BIRTH_MONTHS:any={
 'มค':1,'มกราคม':1,
 'กพ':2,'กุมภาพันธ์':2,
 'มีค':3,'มีนาคม':3,
 'เมย':4,'เมษายน':4,
 'พค':5,'พฤษภาคม':5,
 'มิย':6,'มิถุนายน':6,
 'กค':7,'กรกฎาคม':7,
 'สค':8,'สิงหาคม':8,
 'กย':9,'กันยายน':9,
 'ตค':10,'ตุลาคม':10,
 'พย':11,'พฤศจิกายน':11,
 'ธค':12,'ธันวาคม':12
};
const PERSON_BIRTH_MONTH_LABELS=['','ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
function personBirthYearToCE(y:number,calendarHint=''){
 const hint=String(calendarHint||'').toLowerCase().replace(/[.\s]/g,'');
 if(hint==='พศ'||hint==='be'||hint==='buddhist')return y-543;
 if(hint==='คศ'||hint==='ce'||hint==='ad')return y;
 if(y>=2400)return y-543;   // คนไทยพิมพ์ 2517 -> พ.ศ.
 return y;                  // 1974 -> ค.ศ.
}
function normalizePersonProfileDate(v:string){
 const raw=String(v||'').trim().replace(/^วัน(?:อาทิตย์|จันทร์|อังคาร|พุธ|พฤหัสบดี|ศุกร์|เสาร์)\s*/u,'').replace(/\b(?:พ\.?ศ\.?|ค\.?ศ\.?)\s*(?=\d{2,4}$)/u,'');
 if(!raw)return '';
 const valid=(y:number,m:number,d:number)=>{const x=new Date(Date.UTC(y,m-1,d));return x.getUTCFullYear()===y&&x.getUTCMonth()===m-1&&x.getUTCDate()===d};
 let y=0,mo=0,d=0,hint='';
 let m=raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
 if(m){y=Number(m[1]);mo=Number(m[2]);d=Number(m[3])}
 if(!m){
  m=raw.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})$/);
  if(m){d=Number(m[1]);mo=Number(m[2]);y=Number(m[3])}
 }
 if(!m){
  const cleaned=raw.replace(/,/g,' ').replace(/\s+/g,' ').trim();
  m=cleaned.match(/^(\d{1,2})\s+([^\d\s]+)\s+(?:(พ\.?\s*ศ\.?|ค\.?\s*ศ\.?)\s*)?(\d{2,4})$/i);
  if(m){
   d=Number(m[1]);
   const monthKey=String(m[2]||'').replace(/[.\s]/g,'');
   mo=Number(PERSON_BIRTH_MONTHS[monthKey]||0);
   hint=String(m[3]||'');
   y=Number(m[4]);
  }
 }
 if(!y||!mo||!d)throw new Error('person_profile_invalid_date');
 if(y<100){y=2500+y;}
 y=personBirthYearToCE(y,hint);
 const currentY=new Date().getUTCFullYear();
 if(y<1850||y>currentY||!valid(y,mo,d))throw new Error('person_profile_invalid_date');
 return String(y).padStart(4,'0')+'-'+String(mo).padStart(2,'0')+'-'+String(d).padStart(2,'0')
}
function formatPersonProfileDate(v:any){
 const raw=String(v||'').trim();
 if(!raw)return '—';
 const m=raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
 if(!m)return raw;
 const y=Number(m[1]),mo=Number(m[2]),d=Number(m[3]);
 if(!PERSON_BIRTH_MONTH_LABELS[mo])return raw;
 const wd=['วันอาทิตย์','วันจันทร์','วันอังคาร','วันพุธ','วันพฤหัสบดี','วันศุกร์','วันเสาร์'][new Date(Date.UTC(y,mo-1,d)).getUTCDay()];
 return wd+' '+d+' '+PERSON_BIRTH_MONTH_LABELS[mo]+' พ.ศ. '+(y+543)
}
function shortBirthThai(v:any){
 const raw=String(v||'').trim(),m=raw.match(/^(\d{4})-(\d{2})-(\d{2})$/);
 if(!m)return raw;
 const months=['','ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
 return Number(m[3])+' '+months[Number(m[2])]+' '+String(Number(m[1])+543)
}
function normalizePersonProfileSex(v:string){
 const s=String(v||'').trim().toLowerCase().replace(/^[^ก-๙a-z]+/u,'').trim();
 if(['หญิง','female','f'].includes(s))return 'female';
 if(['ชาย','male','m'].includes(s))return 'male';
 if(['อื่น','อื่นๆ','other'].includes(s))return 'other';
 if(['ไม่ระบุ','unknown','ล้าง',''].includes(s))return 'unknown';
 throw new Error('person_profile_invalid_sex')
}
function parsePersonProfileTemplate(text:string){
 const map:any={
  'ชื่อที่ฉันใช้เรียกตัวเอง':'display_name','ชื่อที่แสดงของฉัน':'display_name','ชื่อที่แสดงสำหรับฉัน':'display_name','ชื่อที่ใช้เรียก':'display_name','ชื่อเรียก':'display_name',
  'ชื่อในบ้าน':'nickname','ชื่อเล่น':'nickname',
  'ชื่อจริง':'first_name','ชื่อ':'first_name',
  'นามสกุล':'last_name',
  'วันเกิด':'date_of_birth','วันที่เกิด':'date_of_birth',
  'เพศ':'sex',
  'ความสัมพันธ์กับฉัน':'relationship','ความสัมพันธ์':'relationship'
 };
 const patch:any={};
 for(const line of String(text||'').replace(/\r/g,'').split('\n')){
  const m=line.match(/^\s*([^:：=]+?)\s*[:：=]\s*(.*?)\s*$/);
  if(!m)continue;
  const label=String(m[1]||'').trim(),field=map[label];
  if(!field)continue;
  let value=String(m[2]||'').trim();
  if(value==='-'||value==='—'||value==='ไม่แก้')continue;
  if(value==='ล้าง')value='';
  if(field==='date_of_birth'&&value)value=normalizePersonProfileDate(value);
  if(field==='sex')value=normalizePersonProfileSex(value);
  patch[field]=value
 }
 if(!Object.keys(patch).length)throw new Error('person_profile_template_empty');
 return patch
}
