async function replyActivePersonBulkMembersPicker(rt:string,u:string,k:string,id:string,t:string,page=0){
 const ov=one(await rpc(u,k,'phms_get_line_active_person_access_overview',{p_line_user_id:id}));
 const personCode=String(ov?.person_code||'');
 const personName=String(ov?.person_name||'บุคคล');
 if(ov?.actor_can_manage_permissions!==true){await replyPersonCaregiverManager(rt,u,k,id,t);return}
 const members=(Array.isArray(ov?.members)?ov.members:[]).filter((m:any)=>{
  const roles=Array.isArray(m?.roles)?m.roles.map(String):[];
  if(!m?.member_code||m?.is_person_self===true)return false;
   return true
 });
 const st=await getState(u,k,id);
 const selected=new Set<string>(
  st?.state_key==='active_person_bulk_members'&&String(st?.state_data?.person_code||'')===personCode
   ?(Array.isArray(st?.state_data?.selected)?st.state_data.selected:[])
   :[]
 );
 const pageSize=7,total=Math.max(1,Math.ceil(members.length/pageSize)),pg=Math.max(0,Math.min(Number(page)||0,total-1));
 const items:any[]=[];
 for(const m of members.slice(pg*pageSize,pg*pageSize+pageSize)){
  const mc=String(m.member_code),on=selected.has(mc);
  items.push(pb((on?'☑️ ':'⬜ ')+String(m.display_name||'สมาชิก').slice(0,16),'สลับผู้รับสิทธิ์ '+personCode+' '+mc+' '+pg))
 }
 if(pg>0)items.push(pb('⬅️ ก่อนหน้า','เลือกหลายผู้รับสิทธิ์ '+personCode+' '+(pg-1)));
 if(pg<total-1)items.push(pb('➡️ ถัดไป','เลือกหลายผู้รับสิทธิ์ '+personCode+' '+(pg+1)));
 if(selected.size)items.push(pb('✅ ตั้งสิทธิ์ '+selected.size+' คน','ตั้งสิทธิ์หลายผู้รับ '+personCode));
 items.push(pb('❌ ยกเลิก','จัดการคนที่ดูหรือช่วยดูแล'));
 await reply(rt,'☑️ ให้สิทธิ์หลายคนพร้อมกัน\n\nข้อมูลของ: '+personName+'\nเลือกสมาชิกที่ต้องการ แล้วกำหนดสิทธิ์ชุดเดียวกัน\n\nเลือกแล้ว '+selected.size+' คน'+(total>1?' • หน้า '+(pg+1)+'/'+total:''),t,items.slice(0,13))
}
