async function signedPersonPhotoUrl(u:string,k:string,objectName:any,expiresIn=86400){
 const path=String(objectName||'').trim();if(!path)return null;
 try{
  const url=u+'/storage/v1/object/sign/phms-person-photos/'+path.split('/').map(encodeURIComponent).join('/');
  const r=await fetch(url,{method:'POST',headers:{apikey:k,Authorization:'Bearer '+k,'content-type':'application/json'},body:JSON.stringify({expiresIn})});
  if(!r.ok){console.error('person_photo_sign_failed',r.status,await r.text());return null}
  const d=await r.json();
  const s=String(d?.signedURL||d?.signedUrl||'');
  if(!s)return null;
  const original=s.startsWith('http')?s:(s.startsWith('/storage/v1/')?u+s:(s.startsWith('/object/')?u+'/storage/v1'+s:u+'/storage/v1/'+s.substring(s.indexOf('/')===0?1:0)));
  const rounded=u+'/functions/v1/phms-person-rounded-photo?source='+encodeURIComponent(original);
  try {
   const probe=await fetch(rounded,{method:'GET',signal:AbortSignal.timeout(4500)});
   const format=String(probe.headers.get('content-type')||'').toLowerCase();
   if(probe.ok&&format.includes('image/png')){await probe.body?.cancel();return rounded;}
   await probe.body?.cancel();
   console.error('person_round_fallback',probe.status,format);
  }catch(err){console.error('person_round_probe_failed',String(err))}
  return original;
  if(s.startsWith('http'))return s;
  if(s.startsWith('/storage/v1/'))return u+s;
  if(s.startsWith('/object/'))return u+'/storage/v1'+s;
  return u+'/storage/v1/'+s.replace(/^\/+/, '');
 }catch(err){console.error('person_photo_sign_error',String(err));return null}
}
