function appointmentSummaryText(x:any){
 const items=Array.isArray(x?.items)?x.items:[];
 return items.length?items.map((a:any)=>'• '+String(a.title||'นัดหมาย')+(a.appointment_at?'\n  '+crudDate(a.appointment_at):'')).join('\n'):'ยังไม่มีนัดหมายที่กำลังมา';
}
function healthSummaryText(x:any){
 const items=Array.isArray(x?.items)?x.items:[];
 return items.length?items.map((h:any)=>{
  const val=h.systolic&&h.diastolic?String(h.systolic)+'/'+String(h.diastolic):String(h.value_numeric??h.value_text??'—');
  return '• '+phmsHealthMeasurementCardTitle(h)+' '+val+(h.unit?' '+String(h.unit):'')+(h.measured_at?'\n  '+crudDate(h.measured_at):'')
 }).join('\n'):'ยังไม่มีข้อมูลสุขภาพ';
}
/* PHMS_MEDICATION_SUMMARY_CENTRAL_POLICY_V23
   Shared summary presentation for all persons and families.
   Do not apply to clinical detail, dispensing, or medication administration cards.
   Preserve navigation, access control, five-category theme, and clinical text. */
function phmsMedicationSummaryBodyV23(meds:any){
 // PHMS_MEDICATION_DASHBOARD_V25: fixed-height summary shared by all people and households.
 // Counts are registry totals, never implicitly 'active'; never derive clinical warnings from truncated items.
 const all=Array.isArray(meds?.items)?meds.items:[];
 const n=Number(meds?.count);
 const count=Number.isInteger(n)&&n>=0?n:all.length;
 const theme=PHMS_CATEGORY_THEME.medications.color;
 const last=meds?.updated_at||meds?.last_updated_at||(all.map((x:any)=>x?.updated_at||x?.created_at).filter(Boolean).sort().at(-1));
 const date=phmsPersonCardShortThaiDate(last);
 const verified=meds?.status_summary_verified===true&&meds?.status_summary&&typeof meds.status_summary==='object';
 const summary=verified?meds.status_summary:{};
 const active=verified&&Number.isInteger(summary.active_count)&&summary.active_count>=0?summary.active_count:null;
 const pending=verified&&Number.isInteger(summary.pending_count)&&summary.pending_count>=0?summary.pending_count:null;
 const low=verified&&Number.isInteger(summary.low_stock_count)&&summary.low_stock_count>=0?summary.low_stock_count:null;
 const changed=verified&&Number.isInteger(summary.changed_order_count)&&summary.changed_order_count>=0?summary.changed_order_count:null;
 const line=(text:string,size='sm',color='#475569')=>({type:'text',text,size,color,wrap:true,maxLines:2});
 /* PHMS_MEDICATION_STATUS_COLOR_GRID_V1: semantic colors apply to statistics, never to inferred clinical values. */
 const tile=(value:string,label:string,bg:string,fg:string)=>({type:'box',layout:'vertical',flex:1,backgroundColor:bg,cornerRadius:'9px',paddingAll:'9px',spacing:'xs',contents:[
  {type:'text',text:value,size:'lg',weight:'bold',align:'center',color:fg,wrap:false,maxLines:1},
  {type:'text',text:label,size:'xs',align:'center',color:fg,wrap:true,maxLines:2}
 ]});
 const signal=(value:number|null)=>value===null?'—':String(value);
 const rows:any[]=[
  {type:'text',text:'ภาพรวมยา',size:'md',weight:'bold',color:theme},
  line(date?'🕒 อัปเดตล่าสุด '+date:'🕒 ยังไม่มีวันที่อัปเดต','xs','#667085'),
  {type:'separator',margin:'xs'},
  {type:'box',layout:'horizontal',spacing:'sm',contents:[
   tile(String(count),'ยาทั้งหมด','#EFF2F6','#334155'),tile(signal(active),'กำลังใช้','#E5F4EA','#17653C')
  ]},
  {type:'box',layout:'horizontal',spacing:'sm',contents:[
   tile(signal(pending),'ต้องติดตาม','#FFF0D8','#8A5200'),tile(signal(low),'ใกล้หมด','#FCE8E8','#A52B35')
  ]},
  {type:'separator',margin:'sm',color:'#D9C9CE'},
  {type:'box',layout:'vertical',backgroundColor:PHMS_CATEGORY_THEME.medications.background,cornerRadius:'9px',paddingAll:'10px',spacing:'xs',contents:[
   {type:'text',text:'📋 สถานะยา',size:'sm',weight:'bold',color:theme},
   line(verified&&pending!==null&&low!==null&&changed!==null
   ?(pending===0&&low===0&&changed===0?'ไม่พบเรื่องต้องติดตาม':'มีเรื่องต้องติดตาม '+pending+' รายการ')
   :'ยังไม่มีข้อมูลสถานะครบ','sm',
   verified&&pending!==null&&low!==null&&changed!==null
    ?(pending>0||low>0||changed>0?'#9A5A16':'#28654B'):'#64748B')
  ]}
 ];
 return {type:'box',layout:'vertical',spacing:'sm',paddingAll:'8px',paddingTop:'10px',paddingBottom:'0px',justifyContent:'center',contents:rows};
}

/* AIM_PERSON_SUMMARY_LIST_V1: show up to 3 rows already authorized by dashboard RPC; no edits to saved clinical content. */
function phmsPersonCardShortThaiDate(v:any){
 if(!v)return '';
 const raw=String(v);
 const d=new Date(raw);
 if(Number.isNaN(d.getTime()))return '';
 const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Bangkok',day:'numeric',month:'numeric',year:'numeric'}).formatToParts(d);
 const get=(k:string)=>Number(parts.find(p=>p.type===k)?.value||0);
 const months=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
 return get('day')+' '+months[get('month')-1]+' '+String(get('year')+543).slice(-2);
}
/* PHMS_HOSPITAL_PRESENTATION_V1: display only; canonical record names are unchanged. */
function phmsHospitalShortLabel(value:any){
 const v=String(value??'').trim();
 if(!v)return '';
 const n=v.toLowerCase().replace(/[^0-9a-zก-๙]/gu,'');
 if(n==='lkb'||n.includes('นคราภิบาล')||
   ['ลาดกระบัง','รพลาดกระบัง','โรงพยาบาลลาดกระบัง'].includes(n))return 'รพ.นคราภิบาล/ลาดกระบัง (LKB)';
 if(v.startsWith('โรงพยาบาล'))return 'รพ.'+v.slice('โรงพยาบาล'.length).trimStart();
 if(v.startsWith('รพ '))return 'รพ.'+v.slice('รพ '.length).trimStart();
 return v.startsWith('รพ.')?v:'รพ.'+v;
}
/* PHMS_HEALTH_ADAPTIVE_SINGLE_CARD_V1: compact preview only; complete records unchanged. */
function aimPersonSummaryRows(kind:'medications'|'appointments'|'health_data',data:any){
 const all=Array.isArray(data?.items)?data.items:[];
 // PHMS_HEALTH_SINGLE_CARD_V2: one latest health preview plus remaining-count link; keep full records in detail.
 const xs=all.slice(0,kind==='appointments'||kind==='health_data'?1:2);
 const empty=kind==='medications'?'ยังไม่มีข้อมูลยา\nเมื่อมีข้อมูล จะแสดงรายการที่นี่':kind==='appointments'?'ยังไม่มีข้อมูลนัดหมาย\nเมื่อมีข้อมูล จะแสดงรายการที่นี่':'ยังไม่มีข้อมูลสุขภาพ\nเมื่อมีข้อมูล จะแสดงรายการที่นี่';
 if(!xs.length)return [{type:'text',text:empty,size:'md',color:'#475569',wrap:true}];
 const short=(v:any,max=90)=>{const t=String(v??'').replace(/\\s+/g,' ').trim();return t.length>max?t.slice(0,max-1).trimEnd()+'…':t};
 // LINE Flex cannot measure leftover carousel height at runtime. Give concise notes
 // additional lines while bounding unusually long text to preserve footer visibility.
 const notesLength=xs.reduce((total:number,x:any)=>total+
  (kind==='health_data'?String(healthTemplateValue(x)||'').length:
   kind==='appointments'?String(x?.title||'').length+String(x?.hospital_display_name||x?.hospital_name||'').length+String(x?.doctor_name||'').length:
   kind==='medications'?String(x?.name||x?.generic_name||'').length+String(x?.dose_text||'').length+String(x?.instructions||'').length:0),0);
 const adaptiveLines=kind==='health_data'?(xs.length>1?2:3):(notesLength<=190?5:notesLength<=300?3:2);
 const rows:any[]=[];
 const theme=kind==='medications'?PHMS_CATEGORY_THEME.medications.color:kind==='appointments'?'#85571D':'#27694B';
 const heading=kind==='medications'?'สรุปรายการยา':kind==='appointments'?'นัดถัดไป':'สุขภาพล่าสุด';
 rows.push({type:'text',text:heading,size:'md',weight:'bold',color:theme});
 {
  const latest=all.map((x:any)=>x?.updated_at||x?.created_at).filter(Boolean).map((v:any)=>new Date(v).getTime()).filter((n:number)=>Number.isFinite(n));
  const last=data?.updated_at||data?.last_updated_at||(latest.length?new Date(Math.max(...latest)).toISOString():null);
  const date=phmsPersonCardShortThaiDate(last);
  rows.push({type:'text',text:date?'🕒 อัปเดตล่าสุด '+date:'ยังไม่มีข้อมูลวันที่อัปเดต',size:'xs',color:'#667085',margin:'xs'});
  rows.push({type:'separator',margin:'sm'});
 }
 for(let i=0;i<xs.length;i++){
  const x=xs[i],blocks:any[]=[]; const recordCode=String(x?.code||''); const chevron=/^(?:[a-f0-9]{8}-[a-f0-9]{3}|[a-f0-9]{12})$/i.test(recordCode)?' ›':'';
  if(kind==='medications'){
   // PHMS_MEDICATION_SUMMARY_V23: display registered facts only; never infer schedule, stock or adherence.
   const name=String(x?.name||x?.generic_name||'ยา').trim();
   blocks.push({type:'text',text:'💊 '+name+chevron,size:'md',weight:'bold',color:'#344054',wrap:true,maxLines:2});
   const dose=String(x?.dose_text||'').trim();
   if(dose)blocks.push({type:'text',text:'ขนาดยา: '+dose,size:'sm',color:'#475569',wrap:true,maxLines:3});
   const instruction=String(x?.instructions||'').trim();
   const clean=name&&instruction.toLocaleLowerCase().startsWith(name.toLocaleLowerCase()+' ')?instruction.slice(name.length).trimStart():instruction;
   if(clean)blocks.push({type:'text',text:'วิธีใช้: '+clean,size:'sm',color:'#667085',wrap:true,maxLines:6});
  }else if(kind==='appointments'){
   // Person detail cards include a recorded doctor; cap each line to preserve compact card height.
   const doctor=String(x?.doctor_name??'').replace(/\s+/g,' ').trim();
   const showDoctor=!!doctor&&!/^(?:-|—|ไม่ระบุ|ไม่ทราบ|ไม่มี|n\/a)$/i.test(doctor);
   const compactTwo=showDoctor&&xs.length>1;
   blocks.push({type:'box',layout:'horizontal',spacing:'none',alignItems:'start',contents:[{type:'text',text:'📌',size:'md',flex:0,wrap:false,margin:'none'},{type:'text',text:String(x?.title||'นัดหมาย')+chevron,size:'md',weight:'bold',color:'#344054',wrap:true,maxLines:2,flex:1,margin:'none'}]});
   if(x?.appointment_at){const d=new Date(x.appointment_at);const weekday=new Intl.DateTimeFormat('th-TH',{timeZone:'Asia/Bangkok',weekday:'long'}).format(d);const timeParts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(d);const h=Number(timeParts.find((v:any)=>v.type==='hour')?.value||0),m=Number(timeParts.find((v:any)=>v.type==='minute')?.value||0);blocks.push({type:'text',text:'📅 '+weekday+' '+phmsPersonCardShortThaiDate(x.appointment_at),size:'sm',color:'#475569',wrap:false,maxLines:1});const fmt=(v:Date)=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(v);const days=Math.round((Date.parse(fmt(d)+'T00:00:00Z')-Date.parse(fmt(new Date())+'T00:00:00Z'))/86400000);if(Number.isFinite(days)&&days>=0){const label=days===0?'วันนี้':days===1?'พรุ่งนี้':'อีก '+days+' วัน';blocks.push({type:'box',layout:'horizontal',spacing:'none',contents:[{type:'box',layout:'vertical',flex:0,backgroundColor:'#FFF1D7',cornerRadius:'8px',paddingAll:'5px',contents:[{type:'text',text:'⏳ '+label,size:'sm',color:'#85571D',wrap:false}]}]});}blocks.push({type:'text',text:'🕒 '+pad2(h)+':'+pad2(m)+' ('+appointmentNaturalTimeLabel(h,m)+')',size:'sm',color:'#475569',wrap:false,maxLines:1});}
   const hospital=phmsHospitalShortLabel(x?.hospital_display_name||x?.hospital_name);
   if(hospital)blocks.push({type:'text',text:'🏥 '+hospital,size:'sm',color:'#475569',wrap:true,maxLines:1});
   if(showDoctor)blocks.push({type:'text',text:appointmentDoctorEmoji(doctor)+' '+appointmentDoctorShortLabel(doctor),size:'sm',color:'#475569',wrap:true,maxLines:1});
  }else{
   blocks.push({type:'text',text:'🩺 '+phmsHealthMeasurementCardTitle(x)+chevron,size:'md',weight:'bold',color:'#344054',wrap:true,maxLines:2});
   const value=healthTemplateValue(x),unit=x?.unit?' '+String(x.unit):'';
   if(value)blocks.push({type:'text',text:String(value)+unit,size:'sm',color:'#475569',wrap:true,maxLines:adaptiveLines});
   if(x?.measured_at)blocks.push({type:'text',text:'🕒 '+phmsPersonCardShortThaiDate(x.measured_at)+' '+(new Date(x.measured_at).toLocaleTimeString('th-TH',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit',hour12:false})),size:'sm',color:'#64748B',wrap:true,maxLines:1});
  }
  if(i)rows.push({type:'separator',margin:kind==='health_data'?'sm':'md'});
  const detailPrefix=kind==='medications'?'ดูยา ':kind==='appointments'?'ดูนัด ':'ดูสุขภาพ ';
  rows.push({type:'box',layout:'vertical',spacing:kind==='appointments'?'5px':kind==='health_data'?'xs':'sm',paddingAll:kind==='appointments'?'0px':kind==='health_data'?'4px':'8px',margin:kind==='appointments'?'8px':undefined,cornerRadius:'8px',contents:blocks,...(/^(?:[a-f0-9]{8}-[a-f0-9]{3}|[a-f0-9]{12})$/i.test(recordCode)?{action:{type:'postback',label:'ดูรายละเอียด',data:detailPrefix+recordCode}}:{})});
 }
 const count=Number(data?.count??all.length);
 /* PHMS_HEALTH_SINGLE_CARD_V3: count remains in header; do not add a health remaining-notice block or split into an otherwise empty extra card. Full records and footer actions remain available. */
 // Person overview: total is in the header; no extra-count notice.
 return rows
}
/* Person overview: notice backgrounds must exactly match category card headers. */
const PHMS_PERSON_CATEGORY_HEADER_BG:Record<string,string>={
 medications:PHMS_CATEGORY_THEME.medications.background,
 appointments:'#FFF5E5',
 health:'#EFF8F1',
 documents:'#EEF5FF',
 expenses:'#F5EFFB'
};
/* PHMS_FIVE_CATEGORY_REMAINING_NOTICE_V4: one shared layout and theme-based colors for all five category summaries. */
const phmsPersonRemainingNotice=(n:number,category:string='documents')=>{
 if(category==='appointments')return {type:'text',text:'📋 ดูอีก '+n+' รายการ',size:'sm',weight:'regular',color:'#85571D',align:'start',wrap:false,maxLines:1,margin:'8px'};
 const key=category==='health_data'?'health':category;
 const palette=(PHMS_CATEGORY_THEME as Record<string,{color:string,background:string}>)[key]||PHMS_CATEGORY_THEME.documents;
 return {type:'box',layout:'vertical',spacing:'4px',margin:'4px',contents:[
  {type:'separator',color:'#D5DDE5',margin:'4px'},
  {type:'box',layout:'vertical',backgroundColor:palette.background,cornerRadius:'10px',paddingAll:'8px',margin:'4px',contents:[
   {type:'text',text:'📋 ดูอีก '+n+' รายการ',size:'sm',weight:'bold',color:palette.color,wrap:false,maxLines:1},
   {type:'text',text:'กดปุ่มด้านล่างเพื่อดูทั้งหมด',size:'xs',color:palette.color,wrap:true,maxLines:1,margin:'xs'}
  ]}
 ]};
};
const phmsPersonExtraRows=(kind:'documents'|'expenses',data:any,displayName='')=>{
 if(kind==='expenses'){
 const rows=(Array.isArray(data?.items)?data.items:[]).filter((x:any)=>x?.amount!=null&&Number.isFinite(Number(x.amount))&&Number(x.amount)>0);
 const verified=data?.view===true&&data?.amounts_verified===true;
 const money=(n:any)=>Number(n).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})+' ฿';
 const shortDate=(v:any)=>{const m=String(v||'').match(/^(\d{4})-(\d{2})-(\d{2})/);if(!m)return 'ไม่ระบุวัน';const mm=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];return Number(m[3])+' '+mm[Number(m[2])-1]+' '+String(Number(m[1])+543).slice(-2)};
 if(!data)return [{type:'text',text:'ยังดึงข้อมูลค่าใช้จ่ายไม่ได้ ลองอีกครั้งนะ',size:'md',color:'#475569',wrap:true}];
 const count=Number(data?.count??rows.length);
 if(count===0)return [{type:'text',text:'ยังไม่มีข้อมูลค่าใช้จ่าย\nเมื่อมีข้อมูล จะแสดงรายการที่นี่',size:'md',color:'#475569',wrap:true}];
 const delta=verified&&data?.previous_month_count>0&&data.month_paid!=null&&data.previous_month_paid!=null?Number(data.month_paid)-Number(data.previous_month_paid):null;
 const compactDelta=(v:number)=>{const abs=Math.abs(v);const amt=abs.toLocaleString('th-TH',{minimumFractionDigits:Number.isInteger(abs)?0:2,maximumFractionDigits:2});return v>0?'▲ +'+amt+' ฿':v<0?'▼ -'+amt+' ฿':'＝ 0 ฿'};
 const previousYear=verified&&data?.previous_year_paid!=null&&Number.isFinite(Number(data.previous_year_paid))?Number(data.previous_year_paid):null;
 const yearlyDelta=previousYear!==null&&data.year_paid!=null?Number(data.year_paid)-previousYear:null;
 const compare=(v:number|null,label:string)=>v===null?[]:[{type:'text',text:compactDelta(v)+' '+(label==='จากเดือนก่อน'?'เทียบเดือนก่อน':'เทียบปีก่อน'),size:'xs',weight:'regular',color:v>0?'#B42318':v<0?'#16803D':'#667085',wrap:true,maxLines:2}];
 const out:any[]=[
 {type:'text',text:'สรุปค่าใช้จ่าย',weight:'bold',size:'md',color:'#66458A'},
 {type:'text',text:(()=>{const dt=phmsPersonCardShortThaiDate(data?.updated_at||rows[0]?.updated_at||rows[0]?.created_at);return dt?'🕒 อัปเดตล่าสุด '+dt:'🕒 ยังไม่มีวันที่อัปเดต'})(),size:'xs',color:'#667085',margin:'xs',wrap:false,maxLines:1},
 {type:'separator',margin:'sm'},
 {type:'box',layout:'horizontal',spacing:'8px',margin:'4px',contents:[
  {type:'box',layout:'vertical',flex:1,backgroundColor:'#F5EFFB',cornerRadius:'10px',paddingAll:'8px',spacing:'4px',action:{type:'postback',label:'💰 ปีนี้',data:'ดูค่าใช้จ่ายรายปี'},contents:[
   {type:'box',layout:'horizontal',alignItems:'center',spacing:'2px',contents:[{type:'text',text:'💰 ปีนี้',size:'sm',weight:'regular',color:'#66458A',wrap:false,flex:1},{type:'text',text:'›',size:'md',color:'#66458A',align:'end',flex:0}]},
   {type:'text',text:verified&&data.year_paid!=null?money(data.year_paid):'ยังไม่มียอดสรุป',size:'lg',weight:'bold',color:'#66458A',wrap:false,action:{type:'postback',label:'💰 ดูรายปี',data:'ดูค่าใช้จ่ายรายปี'}},
  ]},
  {type:'box',layout:'vertical',flex:1,backgroundColor:'#F5EFFB',cornerRadius:'10px',paddingAll:'8px',spacing:'4px',action:{type:'postback',label:'📅 เดือนนี้',data:'ดูค่าใช้จ่ายรายเดือน'},contents:[
   {type:'box',layout:'horizontal',alignItems:'center',spacing:'2px',contents:[{type:'text',text:'📅 เดือนนี้',size:'sm',weight:'regular',color:'#66458A',wrap:false,flex:1},{type:'text',text:'›',size:'md',color:'#66458A',align:'end',flex:0}]},
   {type:'text',text:verified&&data.month_paid!=null?money(data.month_paid):'ยังไม่มียอดสรุป',size:'lg',weight:'bold',color:'#66458A',wrap:false,action:{type:'postback',label:'📅 ดูรายเดือน',data:'ดูค่าใช้จ่ายรายเดือน'}},
  ]}
 ]},
 ...(delta===null?[]:[{type:'text',text:delta>0?'▲ เพิ่มขึ้น '+money(delta)+' จากเดือนก่อน':delta<0?'▼ ลดลง '+money(Math.abs(delta))+' จากเดือนก่อน':'• เท่ากับเดือนก่อน',size:'sm',weight:'regular',color:delta>0?'#B42318':delta<0?'#16803D':'#667085',wrap:false,maxLines:1,margin:'6px'}])
 ];
 out.push({type:'separator',margin:'6px'});
 const nowMonth=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit'}).format(new Date());
 const prevMonth=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit'}).format(new Date(Date.UTC(Number(nowMonth.slice(0,4)),Number(nowMonth.slice(5,7))-2,1)));
 const latestTwo=rows;
 const monthOf=(x:any)=>String(x?.date||'').slice(0,7);
 const currentRows=latestTwo.filter((x:any)=>monthOf(x)===nowMonth);
 const previousRows=latestTwo.filter((x:any)=>monthOf(x)===prevMonth);
 const olderRows=latestTwo.filter((x:any)=>monthOf(x)!==nowMonth&&monthOf(x)!==prevMonth);
 if(currentRows.length)out.push({type:'text',text:'รายการล่าสุดเดือนนี้',weight:'bold',size:'md',color:'#66458A',margin:'6px'});
 const displayRows=(currentRows.length?currentRows:previousRows.length?previousRows:olderRows).slice(0,1);
 let section='';
 for(const [rowIndex,x] of displayRows.entries()){
  // Keep latest expense entries visually separated by whitespace only.
  const group=monthOf(x)===nowMonth?'current':monthOf(x)===prevMonth?'previous':'older';
  if(group!==section){
   if(group==='previous')out.push({type:'text',text:'รายการล่าสุดเดือนที่แล้ว',weight:'bold',size:'md',color:'#66458A',margin:'6px'});
   else if(group==='older')out.push({type:'text',text:'รายการล่าสุดก่อนหน้านี้',weight:'bold',size:'md',color:'#66458A',margin:'6px'});
   section=group;
  }
  const name=String(x.appointment_title||x.title||'ค่าใช้จ่ายที่บันทึกไว้');
  const expenseAppointmentId=String(x?.appointment_id||'');
  const expenseDetailCommand=/^[0-9a-fA-F-]{36}$/.test(expenseAppointmentId)?'รายละเอียดค่ารักษา '+expenseAppointmentId:'สรุปค่าใช้จ่ายนัด';
  out.push({type:'box',layout:'vertical',spacing:'4px',margin:'4px',action:{type:'postback',label:'💰 ดูรายละเอียดค่ารักษา',data:expenseDetailCommand},contents:[
   {type:'box',layout:'horizontal',spacing:'sm',alignItems:'start',contents:[
    {type:'text',text:'🩺 ค่ารักษาพยาบาล',size:'sm',weight:'regular',wrap:false,flex:7},
    {type:'text',text:x.amount==null?'ยังไม่ระบุยอด':money(x.amount),size:'sm',weight:'regular',align:'end',wrap:false,flex:4,action:{type:'postback',label:'💰 ดูค่ารักษา',data:expenseDetailCommand}}
   ]},
   {type:'text',text:name,size:'sm',weight:'regular',wrap:true,maxLines:2,action:{type:'postback',label:'🩺 ดูค่ารักษา',data:expenseDetailCommand}},
   // Date remains accessible in expense details.
  ]})
 }
 // Total count includes records without payment; do not label them as additional paid entries.
 if(!displayRows.length)out.push({type:'text',text:'ยังไม่มีรายการที่มีค่าใช้จ่าย',size:'sm',color:'#667085',wrap:true});
 /* PHMS_EXPENSE_REMAINING_NOTICE_V1: show records not in the one-row preview; count includes unpaid records. */
 const remainingExpenses=Math.max(0,count-displayRows.length);
 // Person overview: do not duplicate the expense count beneath the preview.
 return out;
 }

 /* PHMS_DOCUMENT_SUMMARY_GLOBAL_V1 — shared card for all persons/families.
    Category counts and precise category navigation are pending backend enhancement.
    Never infer total category counts from the five recent preview records. */
 const total=Math.max(0,Number(data?.count??0)||0);
 const updated=phmsPersonCardShortThaiDate(data?.items?.[0]?.updated_at||data?.updated_at||data?.items?.[0]?.date);
 const person=String(displayName||'สมาชิก').trim().slice(0,70);
 const action=(label:string,command:string)=>({type:'postback',label,data:command,displayText:label});
 const docRows:any[]=[
  {type:'text',text:'เอกสารของ'+person,size:'md',weight:'bold',color:'#2D578B',wrap:false,maxLines:1},
  {type:'text',text:updated?'🕒 อัปเดตล่าสุด '+updated:'🕒 อัปเดตล่าสุด —',size:'xs',color:'#475569',wrap:false,maxLines:1},
  {type:'separator',margin:'xs'}
 ];
 const sections=[
  {label:'📅 เอกสารนัดหมาย',key:'appointments',command:'แกลเลอรี นัดหมาย ทั้งหมด'},
  {label:'🧪 ผลตรวจสุขภาพ',key:'health',command:'แกลเลอรี สุขภาพ ทั้งหมด'},
  {label:'🗂️ เอกสารอื่น ๆ',key:'other',command:'รูปและเอกสาร ทั้งหมด'}
 ];
 for(const section of sections){
  const a=action(section.label,section.command);
  docRows.push({type:'box',layout:'horizontal',alignItems:'center',spacing:'sm',margin:'xs',paddingAll:'10px',cornerRadius:'8px',backgroundColor:'#F7FAFE',action:a,contents:[
   {type:'box',layout:'vertical',flex:1,spacing:'2px',contents:[
    {type:'text',text:section.label,size:'md',weight:'bold',color:'#2D578B',wrap:false,maxLines:1},
    {type:'text',text:(data?.category_counts?.[section.key]==null?'กำลังตรวจจำนวน':String(Math.max(0,Number(data.category_counts[section.key])||0))+' รายการ'),size:'sm',color:'#344862',wrap:false,maxLines:1}
   ]},
   {type:'text',text:'›',size:'lg',color:'#2D578B',align:'end',flex:0}
  ]});
 }
 // Person overview: document total appears in the category header.
 return docRows;
};
/* AIM_PERSON_DASHBOARD_V3: unique name, right-aligned connection status, three actions, color-aware header. */
async function personDashboardMessages(u:string,k:string,id:string,title='👤 ภาพรวมบุคคล'){
 const d=one(await rpc(u,k,'phms_get_line_person_dashboard',{p_line_user_id:id}));
 if(!d)throw new Error('person_dashboard_unavailable');
 let caregiverInfo:any=null;
 try{caregiverInfo=one(await rpc(u,k,'phms_list_line_person_caregivers',{p_line_user_id:id}))}catch{}
 const caregivers=Array.isArray(caregiverInfo?.current)?caregiverInfo.current:[];
 const selfManage=caregiverInfo?.self_manage!==false;
 const selfCaregiver=d?.is_self===true;
 const primaryName=String(caregiverInfo?.primary_name||(caregiverInfo?.primary_status==='active'&&d?.is_self===true?'ตัวเอง':'')||'');
 const photoUrl=await signedPersonPhotoUrl(u,k,d?.photo?.object_name);
 const access=d?.access||{},birth=d?.birth_info||{},sum=d?.summaries||{};
 // PHMS_TEMP_INCOMPLETE_ACTIONS_OWNER_ONLY_V1: UI visibility only, never replaces authorization.
 let isHouseholdOwner=false;
 try{const fm=one(await rpc(u,k,'phms_prepare_line_family_management',{p_line_user_id:id}));isHouseholdOwner=fm?.flow_state==='ready'&&fm?.is_owner===true;}catch(err){console.error('person_owner_visibility_check_failed',String(err))}

 let profileColor='#EAF4FF',overviewButtons={main:'#315A75',second:'#526B86'},canChangeColor=false;
 let caregiverBadgeBackground='#F7F1F5',caregiverBadgeText='#704268';
 try{
  const cp=one(await rpc(u,k,'phms_line_person_card_colors',{p_line_user_id:id}));
  const row=(Array.isArray(cp?.items)?cp.items:[]).find((x:any)=>String(x?.person_code||'')===String(d?.person_code||''));
  const pickedColor=String(row?.card_color||d?.card_color||'');if(pickedColor){profileColor=phmsReadablePersonHeaderColor(pickedColor);overviewButtons=phmsPersonButtonTheme(pickedColor)}
  canChangeColor=row?.can_change===true;
  // Use the primary caregiver's own household color when that identity is unambiguous.
  if(primaryName&&primaryName!=='ตัวเอง'){
   const named=(Array.isArray(cp?.items)?cp.items:[]).filter((z:any)=>String(z?.display_name||z?.person_name||'').trim()===primaryName.trim());
   const caregiverColor=String(named.length===1?named[0]?.card_color||'':caregiverInfo?.primary_card_color||caregiverInfo?.primary_color||'');
   if(/^#[0-9a-fA-F]{6}$/.test(caregiverColor)){
    caregiverBadgeBackground=phmsReadablePersonHeaderColor(caregiverColor);
    caregiverBadgeText=phmsPersonButtonTheme(caregiverColor).main;
   }
  }
 }catch{}
 const isTriyaphopOverview=/ไตรภพ/u.test(String(d?.display_name||''));
 if(isTriyaphopOverview){profileColor=phmsReadablePersonHeaderColor('#D13D55');overviewButtons={main:'#9E2941',second:'#A54861'};}
 // Shared renderer for self and every household member; differences are data and granted rights only.
 const upcomingCount=access?.appointments?.view===true&&sum?.appointments?.count!=null?Number(sum.appointments.count):0;
 // PHMS_PERSON_OVERVIEW_LAYOUT_REFINEMENT_V2_5
 // PHMS_PERSON_OVERVIEW_HORIZONTAL_IDENTITY_V1 — shared for every person and household.
 const shortName=String(d?.first_name||d?.given_name||d?.display_name||'บุคคล').trim();
 const details:any[]=[
  {type:'text',text:'👤 '+shortName,size:'md',color:'#374151',wrap:false,maxLines:1},
  ...(birth?.age!=null?[{type:'text',text:'🎈 อายุ '+String(birth.age)+' ปี',size:'md',color:'#374151',wrap:false,maxLines:1}]:[]),
  ...(birth?.date?[{type:'text',text:'🎂 '+shortBirthThai(birth.date),size:'md',color:'#374151',wrap:false,maxLines:1}]:[]),
 ];
 // PHMS_PERSON_OVERVIEW_CAREGIVER_FULL_WIDTH_V1 — shared for all people and households.
 const caregiverRow=primaryName&&primaryName!=='ตัวเอง'&&primaryName!==String(d?.display_name||'')
  ? {type:'box',layout:'vertical',margin:'xs',paddingTop:'6px',paddingBottom:'6px',paddingStart:'10px',paddingEnd:'10px',cornerRadius:'10px',backgroundColor:caregiverBadgeBackground,contents:[
      {type:'text',text:'💗 ผู้ดูแลหลัก: '+primaryName,size:'md',color:caregiverBadgeText,wrap:true,maxLines:3}
    ]}
  : null;
 const profileBody:any[]=[
  {type:'box',layout:'horizontal',alignItems:'center',spacing:'sm',contents:[
   ...(photoUrl?[{type:'box',layout:'vertical',width:'96px',height:'96px',flex:0,cornerRadius:'12px',contents:[{type:'image',url:photoUrl,size:'96px',aspectRatio:'1:1',aspectMode:'cover',flex:0}]}]:[]),
   {type:'box',layout:'vertical',flex:1,spacing:'xs',contents:details}
  ]},
  ...(caregiverRow?[caregiverRow]:[]),
  ...(Number.isFinite(upcomingCount)&&upcomingCount>0?[{type:'box',layout:'vertical',spacing:'xs',margin:'xs',paddingAll:'8px',cornerRadius:'10px',backgroundColor:profileColor,contents:[
   {type:'text',text:'📌 เรื่องที่ควรติดตาม',size:'md',weight:'bold',color:'#374151',margin:'xs'},
   {type:'text',text:'📅 มีนัดหมายที่กำลังจะมาถึง',size:'md',color:'#475569',wrap:true,maxLines:2}
  ]}]:[]),
  {type:'separator',margin:'xs'}
 ];
 const profileFooter:any[]=[{type:'button',style:'primary',height:'md',color:overviewButtons.main,action:{type:'postback',label:'🔎 ดูรายละเอียด',data:'รายละเอียดบุคคล'}}];
 if(d?.is_self===true&&String(title||'').includes('ของฉัน'))profileFooter.push({type:'button',style:'secondary',height:'md',action:{type:'postback',label:'↩️ หน้าเริ่มต้น',data:'กลับหน้าเริ่มต้น'}});
 else profileFooter.push({type:'button',style:'primary',height:'md',color:overviewButtons.second,action:{type:'postback',label:'↩️ ครอบครัว',data:'คนในครอบครัว'}});
 if(isTriyaphopOverview)profileFooter.forEach((b:any)=>b.phmsTriyaphopTheme=true);
 const profile:any={type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:profileColor,phmsCounterColor:overviewButtons.main,paddingAll:'12px',spacing:'4px',contents:[
   {type:'text',text:'👤 ภาพรวมบุคคล',weight:'bold',size:'xl',color:'#111111',wrap:true},
   {type:'text',text:'ข้อมูลของ '+String(d?.display_name||'บุคคล').trim(),weight:'regular',size:'md',color:'#111111',wrap:true,margin:'xs'},
   
  ]},
  body:{type:'box',layout:'vertical',spacing:'0px',paddingAll:'10px',contents:profileBody},
  footer:{type:'box',layout:'vertical',spacing:'xs',paddingAll:'8px',contents:profileFooter}
 };
 /* PHMS_PERSON_OVERVIEW_SHARED_593_CONTENT_FIT_V1: all people / households.
    Preserve existing 340px layout when it fits; remove the fixed body height only
    when variable member content + header + footer exceed the conservative budget.
    No truncation or member-specific hardcoding. */
 const phmsOverviewBudget=phmsCardEstimatedHeight(profile.header)+phmsCardEstimatedHeight(profile.body)+phmsCardEstimatedHeight(profile.footer)+32;
 if(phmsOverviewBudget>560){
   delete profile.body.height;
   profile.body.paddingAll='8px';
   profile.body.spacing='xs';
 }
 let extraSummary:any=null;
 if(access?.documents?.view||access?.expenses?.view){try{extraSummary=one(await rpc(u,k,'phms_line_person_extra_summaries',{p_line_user_id:id}))}catch(err){console.error('person_summary_counts',String(err))}}
 if(extraSummary?.documents?.view===true){
  const doc=extraSummary.documents.items?.find((item:any)=>item?.is_image===true&&item?.preview_bucket&&item?.preview_path)||extraSummary.documents.items?.[0];
  const bucket=String(doc?.preview_bucket||'');
  const path=String(doc?.preview_path||'');
  if(bucket&&path&&/^[a-z0-9_-]+$/i.test(bucket)){
   if(doc!==extraSummary.documents.items?.[0])extraSummary.documents.items=[doc,...extraSummary.documents.items.filter((item:any)=>item!==doc)];
   try{
    const signed=await fetch(u+'/storage/v1/object/sign/'+encodeURIComponent(bucket)+'/'+path.split('/').map(encodeURIComponent).join('/'),{method:'POST',headers:{apikey:k,Authorization:'Bearer '+k,'content-type':'application/json'},body:JSON.stringify({expiresIn:3600})});
    if(!signed.ok)console.error('person_doc_sign_failed',signed.status,await signed.text());
    if(signed.ok){const z=await signed.json();const url=String(z.signedURL||z.signedUrl||'');if(url.startsWith('https://'))doc.preview_url=url;else if(url.startsWith('/storage/v1/'))doc.preview_url=u+url;else if(url.startsWith('/object/'))doc.preview_url=u+'/storage/v1'+url;else if(url)doc.preview_url=u+'/storage/v1/'+url.replace(/^\/+/, '')}
   }catch(err){console.error('person_doc_preview',String(err))}
  }
 }
 if(access?.expenses?.view===true){
  try{
   const tr=one(await rpc(u,k,'phms_line_person_expense_trend',{p_line_user_id:id}));
   if(extraSummary?.expenses?.view===true&&tr?.view===true)extraSummary.expenses={...extraSummary.expenses,year_paid:tr.year_paid,month_paid:tr.month_paid,delta:tr.delta,amounts_verified:tr.verified};
   if(extraSummary?.expenses?.view===true){try{const recent=one(await rpc(u,k,'phms_line_person_expense_recent_labels',{p_line_user_id:id}));if(Array.isArray(recent))extraSummary.expenses.items=recent}catch(err){console.error('expense_recent_labels',String(err))}}
  }catch(err){console.error('person_expense_trend',String(err))}
 }
 const cards:any[]=[profile];
 // Person-scoped permissions: never infer finance from appointment view alone.
 let extraDocs=false,extraExpenses=false;
 try{const g=one(await rpc(u,k,'phms_list_line_medical_gallery_v2',{p_line_user_id:id,p_category:'all',p_days:30,p_limit:1,p_offset:0}));extraDocs=!!g&&g?.flow_state!=='permission_denied'&&g?.can_view!==false}catch{}
 if(access?.appointments?.view){try{const f=one(await rpc(u,k,'phms_line_appointment_expense_summary',{p_line_user_id:id,p_limit:1}));extraExpenses=!!f&&f?.flow_state!=='permission_denied'&&f?.can_view_finance!==false}catch{}}
 const extra=(title:string,bg:string,description:string,label:string,command:string)=>({type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:bg,paddingAll:'16px',contents:[{type:'text',text:title,size:'lg',weight:'bold',color:'#294B6B'}]},
  body:{type:'box',layout:'vertical',paddingAll:'16px',contents:[{type:'text',text:description,size:'sm',color:'#475569',wrap:true}]},
  footer:{type:'box',layout:'vertical',paddingAll:'12px',contents:[{type:'button',height:'md',style:'primary',action:{type:'postback',label,data:command}}]}
 });

 /* Caregiver directory is available in access management; no duplicate name-only carousel. */

 const perm:any={type:'bubble',size:'kilo',header:{type:'box',layout:'vertical',backgroundColor:'#F7F4FF',paddingAll:'14px',contents:[
  {type:'text',text:d?.is_self?'🔐 สิทธิ์ของฉันกับข้อมูลของตัวเอง':'🔐 สิทธิ์ของฉันกับ '+String(d?.display_name||'บุคคล'),weight:'bold',size:'lg',color:'#58427A',wrap:true}
 ]},body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'16px',contents:[
  dashRow('หน้าที่ในครอบครัว',personAccessRoleLabel(d?.viewer_roles)),
  dashRow('ข้อมูลบุคคล',thAccessText(access?.profile)),
  dashRow('ยา',thAccessText(access?.medications)),
  dashRow('นัดหมาย',thAccessText(access?.appointments)),
  dashRow('สุขภาพ',thAccessText(access?.health_data)),
  dashRow('เพิ่มสมาชิก',access?.family?.can_add_members?'ทำได้':'ทำไม่ได้'),
  dashRow('จัดการบทบาท/สิทธิ์',access?.family?.can_manage_roles_permissions?'ทำได้':'ทำไม่ได้'),
  dashRow('จัดการคนที่ช่วยดูแล',access?.family?.can_manage_caregivers?'ทำได้':'ทำไม่ได้')
 ]},footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:[
  {type:'button',style:'primary',action:{type:'postback',label:'👥 คนที่เข้าถึงข้อมูลนี้',data:'จัดการคนที่ดูหรือช่วยดูแล'}},
  ...(access?.profile?.update&&!selfCaregiver?[{type:'button',style:'secondary',action:{type:'postback',label:'📥 ตรวจคำขอแก้ข้อมูล',data:'คำขอแก้ข้อมูล'}}]:[])
 ]}};
 /* Individual access controls remain in their dedicated permissions screen; overview cards stay uniform for every person. */

 if(access?.medications?.view){
  const meds=sum?.medications||{};
  cards.push({type:'bubble',size:'kilo',
   header:{type:'box',layout:'vertical',backgroundColor:PHMS_CATEGORY_THEME.medications.background,paddingAll:'14px',contents:[
    {type:'text',text:'💊 ยา',weight:'bold',size:'lg',color:PHMS_CATEGORY_THEME.medications.color},
    {type:'text',text:'มี '+String(meds.count??0)+' รายการในทะเบียน',size:'xs',color:'#777777',margin:'xs'}
   ]},
   body:phmsMedicationSummaryBodyV23(meds), // PHMS_MEDICATION_SUMMARY_CENTRAL_POLICY_V23
   footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'10px',contents:[
    ...(Number(meds.count??meds.items?.length??0)>0?[{type:'button',color:PHMS_CATEGORY_THEME.medications.color,style:'primary',height:'md',action:{type:'postback',label:'💊 ดูยาทั้งหมด',data:'ยา'}}]:[]),
    ...(access?.medications?.create===true?[{type:'button',style:'primary',color:PHMS_CATEGORY_THEME.medications.color,height:'md',action:{type:'postback',label:'＋ เพิ่มยา',data:'เพิ่มยา'}}]:[])
   ]}
  });
 }
 if(access?.appointments?.view){
  const ap=sum?.appointments||{};
  cards.push({type:'bubble',size:'kilo',
   header:{type:'box',layout:'vertical',backgroundColor:PHMS_PERSON_CATEGORY_HEADER_BG.appointments,paddingAll:'14px',contents:[
    {type:'text',text:'📅 นัดหมาย',weight:'bold',size:'lg',color:'#85571D'},
    {type:'text',text:'มี '+String(ap.count??0)+' นัดที่กำลังจะมาถึง',size:'xs',color:'#777777',margin:'xs'}
   ]},
   body:{type:'box',layout:'vertical',spacing:'xs',paddingAll:'12px',contents:aimPersonSummaryRows('appointments',ap)}, // PHMS_APPOINTMENT_SUMMARY_ADAPTIVE_LAYOUT_V1
   footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'10px',contents:[
    ...(Number(ap.count??ap.items?.length??0)>0?[{type:'button',color:'#AD762A',style:'primary',height:'md',action:{type:'postback',label:'📅 ดูนัดทั้งหมด',data:'รายการนัดของคนนี้ทุกช่วงเวลา 0'}}]:[]),
    ...(access?.appointments?.create===true?[{type:'button',style:'primary',color:'#866337',height:'md',action:{type:'postback',label:'＋ เพิ่มนัด',data:'เพิ่มนัด'}}]:[])
   ]}
  });
 }
 if(access?.health_data?.view){
  const h=sum?.health_data||{};
  cards.push({type:'bubble',size:'kilo',
   header:{type:'box',layout:'vertical',backgroundColor:PHMS_PERSON_CATEGORY_HEADER_BG.health,paddingAll:'14px',contents:[
    {type:'text',text:'🩺 สุขภาพ',weight:'bold',size:'lg',color:'#27694B'},
    {type:'text',text:'มี '+String(h.count??0)+' รายการ',size:'xs',color:'#777777',margin:'xs'}
   ]},
   body:{type:'box',layout:'vertical',spacing:'xs',paddingAll:'12px',contents:aimPersonSummaryRows('health_data',h)},
   footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'10px',contents:[
    ...(Number(h.count??h.items?.length??0)>0?[{type:'button',color:'#33825E',style:'primary',height:'md',action:{type:'postback',label:'🩺 ดูสุขภาพทั้งหมด',data:'สุขภาพทั้งหมดบุคคล'}}]:[]),
    ...(access?.health_data?.create===true?[{type:'button',style:'primary',color:'#4E7963',height:'md',action:{type:'postback',label:'＋ เพิ่มสุขภาพ',data:'เพิ่มสุขภาพ'}}]:[])
   ]}
  });
 }
 if(access?.documents?.view)cards.push({type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:PHMS_PERSON_CATEGORY_HEADER_BG.documents,paddingAll:'14px',contents:[{type:'text',text:'📄 เอกสาร',weight:'bold',size:'lg',color:'#2D578B'},{type:'text',text:extraSummary?.documents?.view===true?'มี '+String(extraSummary.documents.count??extraSummary.documents.items?.length??0)+' รายการ':'กำลังตรวจข้อมูล',size:'xs',color:'#777777',margin:'xs'}]},
  body:{type:'box',layout:'vertical',spacing:'xs',paddingAll:'12px',contents:phmsPersonExtraRows('documents',extraSummary?.documents,shortName)},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'10px',contents:[
   ...(extraSummary?.documents?.view===true&&Number(extraSummary.documents.count??extraSummary.documents.items?.length??0)>0?[{type:'button',color:'#376BA7',height:'md',style:'primary',action:{type:'postback',label:'📄 ดูเอกสารทั้งหมด',data:'รูปและเอกสาร'}}]:[]),
   ...(access?.documents?.create===true?[{type:'button',color:'#55779D',height:'md',style:'primary',action:{type:'postback',label:'＋ เพิ่มเอกสาร',data:'เพิ่มเอกสาร'}}]:[])
  ]}});
 if(access?.expenses?.view)cards.push({type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:PHMS_PERSON_CATEGORY_HEADER_BG.expenses,paddingAll:'14px',contents:[{type:'text',text:'💰 ค่าใช้จ่าย',weight:'bold',size:'lg',color:'#66458A'},{type:'text',text:extraSummary?.expenses?.view===true?'มี '+String(extraSummary.expenses.count??extraSummary.expenses.items?.length??0)+' รายการ':'กำลังตรวจข้อมูล',size:'xs',color:'#777777',margin:'xs'}]},
  body:{type:'box',layout:'vertical',spacing:'12px',paddingAll:'12px',contents:phmsPersonExtraRows('expenses',extraSummary?.expenses)},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'10px',contents:[
   ...(extraSummary?.expenses?.view===true&&Number(extraSummary.expenses.count??extraSummary.expenses.items?.length??0)>0?[{type:'button',color:'#7956A0',height:'md',style:'primary',action:{type:'postback',label:'💰 ดูค่าใช้จ่ายทั้งหมด',data:'สรุปค่าใช้จ่ายนัด'}}]:[]),
   ...(access?.expenses?.create===true?[{type:'button',color:'#6E5B91',height:'md',style:'primary',action:{type:'postback',label:'＋ เพิ่มค่าใช้จ่าย',data:'เพิ่มค่าใช้จ่ายบุคคล'}}]:[])
  ]}});
 /* PHMS_PERSON_OVERVIEW_CATEGORY_ORDER_CENTRAL_V1: shared card order for all households; retain personal overview first. */
 {
  const priority:any={'📅 นัดหมาย':1,'💊 ยา':2,'🩺 สุขภาพ':3,'💰 ค่าใช้จ่าย':4,'📄 เอกสาร':5};
  const cardOrder=(card:any)=>priority[String(card?.header?.contents?.find((x:any)=>x?.type==='text')?.text||'')]??99;
  const first=cards[0];
  const ordered=cards.slice(1).sort((a:any,b:any)=>cardOrder(a)-cardOrder(b));
  cards.splice(0,cards.length,first,...ordered);
 }
 /* PHMS_PERSON_DASHBOARD_CAROUSEL_COUNTER_V1: only category cards, count actual visible cards. */
 {
  const total=cards.length;
  for(let i=1;i<total;i++){
   const h=cards[i]?.header;
   if(!h||!Array.isArray(h.contents))continue;
   const titleNode=h.contents.find((n:any)=>n?.type==='text'&&/^(?:💊 ยา|📅 นัดหมาย|🩺 สุขภาพ|📄 เอกสาร|💰 ค่าใช้จ่าย)$/u.test(String(n.text||'')));
   if(!titleNode)continue;
   const subtitleIndex=h.contents.findIndex((n:any)=>n?.type==='text'&&n!==titleNode);
   if(subtitleIndex<0)continue;
   const subtitle=h.contents[subtitleIndex];
   h.contents[subtitleIndex]={type:'box',layout:'horizontal',alignItems:'center',spacing:'sm',margin:subtitle.margin||'xs',contents:[
    {...subtitle,margin:undefined,flex:1,wrap:false,maxLines:1},
    {type:'text',text:String(i+1)+'/'+String(total),weight:/^(?:ยายปุริตา|ยายปุ|ปุริตา)$/u.test(String(d?.display_name||'').trim())?'regular':'bold',size:'sm',color:/^(?:ยายปุริตา|ยายปุ|ปุริตา)$/u.test(String(d?.display_name||'').trim())?(PHMS_FIVE_CATEGORY_SECONDARY_FONT[String(titleNode.text)]||titleNode.color||'#30343B'):(titleNode.color||'#30343B'),align:'end',flex:0,wrap:false}
   ]};
  }
 }
 /* PHMS_FIVE_CATEGORY_BUTTON_PALETTE_V7: approved 5-category palette, locked for every person's overview. Keep headers and backgrounds unchanged. */
 /* PHMS_FIVE_CATEGORY_LOCK_20261021: apply approved Purita palette to every person overview. */
 {
  const palette:any={
   '💊 ยา':{heading:'#651126',sub:PHMS_FIVE_CATEGORY_SECONDARY_FONT['💊 ยา'],bg:PHMS_FIVE_CATEGORY_SECONDARY_BACKGROUND.medications,inner:'#F5DDE3',primary:'#713444',secondary:'#AC6477'},
   '📅 นัดหมาย':{heading:'#482900',sub:'#896511',bg:PHMS_FIVE_CATEGORY_SECONDARY_BACKGROUND.appointments,inner:'#F1E4CC',primary:'#574126',secondary:'#8F7655'},
   '🩺 สุขภาพ':{heading:'#06452E',sub:PHMS_FIVE_CATEGORY_SECONDARY_FONT['🩺 สุขภาพ'],bg:PHMS_FIVE_CATEGORY_SECONDARY_BACKGROUND.health,inner:'#DDECE0',primary:'#254B3C',secondary:'#548670'},
   '📄 เอกสาร':{heading:'#102F63',sub:'#4D679D',bg:PHMS_FIVE_CATEGORY_SECONDARY_BACKGROUND.documents,inner:'#DCE7F5',primary:'#284660',secondary:'#567EA3'},
   '💰 ค่าใช้จ่าย':{heading:'#35154E',sub:'#855A98',bg:PHMS_FIVE_CATEGORY_SECONDARY_BACKGROUND.expenses,inner:'#EBE0F1',primary:'#50385E',secondary:'#896D9B'}
  };
  for(const card of cards){
   const h=card?.header;
   const heading=Array.isArray(h?.contents)?h.contents.find((x:any)=>x?.type==='text'&&Object.prototype.hasOwnProperty.call(palette,String(x.text||''))):null;
   const theme=palette[String(heading?.text||'').trim()];
   if(!theme)continue;
   h.backgroundColor=theme.bg;
   heading.color=theme.heading;
   const visit=(node:any,depth=0):void=>{
    if(!node||typeof node!=='object'||depth>22)return;
    if(Array.isArray(node)){for(const x of node)visit(x,depth+1);return}
    if(node.type==='button'&&node.style==='primary'){
     const label=String(node?.action?.label||'');
     // PHMS_PURITA_OVERVIEW_BUTTON_COLORS_V2: explicit labels only; retain actions/permissions.
     node.color=/เพิ่ม/u.test(label)?theme.secondary:theme.primary;
    }
    if(node.type==='text'){
     const txt=String(node.text||'');
     if(['รายการยาล่าสุด','นัดถัดไป','สุขภาพล่าสุด','เอกสารล่าสุด','ค่าใช้จ่ายล่าสุด'].includes(txt.trim()))node.color=theme.heading;
     else if(/^(?:💰 รวมปีนี้|📅 เดือนนี้)/u.test(txt))node.color=theme.sub;
     else if(theme.heading==='#35154E'&&/^[▼▲]\s*[+-]?[\d,.]+\s*฿/u.test(txt))node.color=PHMS_EXPENSE_MONTHLY_DELTA_FONT;
     else if(node.weight==='bold'&&/^(?:[฿]?\d+[,.\d]*\s*฿|฿\d+)/u.test(txt))node.color=theme.heading;
    }
    if(node.type==='box'&&typeof node.backgroundColor==='string'){
     const current=node.backgroundColor.toUpperCase();
     const direct=Array.isArray(node.contents)?node.contents:[];
     const isRemaining=direct.some((x:any)=>x?.type==='text'&&String(x.text||'').includes('ยังมีอีก')&&String(x.text||'').includes('รายการ'));
     const isExpenseTotals=String(heading?.text||'')==='💰 ค่าใช้จ่าย'&&direct.some((x:any)=>x?.type==='text'&&/รวมปีนี้/u.test(String(x.text||'')));
     const legacy=['#F5EFFB','#F4EAF8','#F5F0FA','#FBE5E9','#F8EDD9','#E3F0E6','#E5EDFA','#EEF5FF','#EAF0FA','#FFF0F1','#FFF8EA','#EFF8F1','#FFF5E5','#E5F3EB'];
     /* PHMS_PURITA_INNER_SECONDARY_BG_V4: shaded summary/remaining panels must use the same central secondary background token as the category header. */
     if(isRemaining||isExpenseTotals||legacy.includes(current)||current===String(theme.inner).toUpperCase())node.backgroundColor=theme.bg;
    }
    for(const [key,v] of Object.entries(node))if(key!=='action'&&v&&typeof v==='object')visit(v,depth+1);
   };
   visit(card.body);visit(card.footer);
  }
 }
 /* PHMS_PERSON_SUMMARY_TOP_ALIGNMENT_V1322: equal baseline for heading, update date and rule across all five category overview cards. */
 for(const card of cards){
  const category=String(card?.header?.contents?.find((n:any)=>n?.type==='text'&&/^(?:💊 ยา|📅 นัดหมาย|🩺 สุขภาพ|📄 เอกสาร|💰 ค่าใช้จ่าย)$/u.test(String(n.text||'')))?.text||'');
  if(!category)continue;
  const outer=card?.body?.contents;
  const rows=category==='💊 ยา'&&outer?.[0]?.type==='box'&&Array.isArray(outer[0].contents)?outer[0].contents:outer;
  if(!Array.isArray(rows)||rows.length<3||rows[0]?.type!=='text'||rows[1]?.type!=='text'||rows[2]?.type!=='separator')continue;
  const head=rows[0],date=rows[1],rule=rows[2];
  delete head.margin;delete date.margin;
  head.wrap=false;head.maxLines=1;
  date.wrap=false;date.maxLines=1;
  delete rule.margin;
  const aligned={type:'box',layout:'vertical',spacing:'none',contents:[
   {type:'box',layout:'vertical',height:'26px',justifyContent:'center',contents:[head]},
   {type:'box',layout:'vertical',height:'24px',justifyContent:'center',contents:[date]},
   {type:'box',layout:'vertical',height:'12px',justifyContent:'end',contents:[rule]}
  ]};
  rows.splice(0,3,aligned);
 }
 /* PHMS_PERSON_DASHBOARD_593_COMPACT_GLOBAL_V3:
    Compact the entire carousel (not only the first bubble). LINE equalizes
    the heights of every bubble, so leaving even one tall bubble defeats a
    593px target on the person overview. Preserve every action and data row. */
 for(const c of cards){
  if(c?.header?.type==='box'){
   c.header.height='70px';
   c.header.paddingAll='8px';c.header.paddingStart='14px';c.header.paddingEnd='12px';
   c.header.spacing='4px';
  }
  if(c?.body?.type==='box'){
   delete c.body.height;delete c.body.minHeight;delete c.body.flex;
   c.body.paddingAll='8px';c.body.spacing='4px';
  }
  if(c?.footer?.type==='box'){
   c.footer.paddingAll='6px';c.footer.spacing='4px';
   delete c.footer.height;delete c.footer.minHeight;
   for(const btn of c.footer.contents||[])if(btn?.type==='button'){
    btn.height='sm';btn.margin='0px';
   }
  }
 }
 /* PHMS_PERSON_OVERVIEW_HIDE_REMAINING_V1: hide only preview remainder notices.
    Preserve total count, clinical rows, navigation and all category actions. */
 const omitRemaining=(node:any):boolean=>{
  if(!node||typeof node!=='object')return false;
  const text=String(node.text||'').trim();
  if(node.type==='text'&&/^📋\s*ดูอีก\s*\d+\s*รายการ$/u.test(text))return true;
  if(node.type==='box'&&Array.isArray(node.contents)){
   const leaves=(n:any):string[]=>n?.type==='text'?[String(n.text||'').trim()]:Array.isArray(n?.contents)?n.contents.flatMap(leaves):[];
   const labels=leaves(node);
   if(labels.some(x=>/^📋\s*ดูอีก\s*\d+\s*รายการ$/u.test(x))&&labels.every(x=>/^📋\s*ดูอีก\s*\d+\s*รายการ$/u.test(x)||x==='กดปุ่มด้านล่างเพื่อดูทั้งหมด'))return true;
  }
  if(Array.isArray(node.contents)){
   const before=node.contents.length;
   node.contents=node.contents.filter((child:any)=>!omitRemaining(child));
   if(node.type==='box'&&before>0&&!node.contents.length)return true;
  }
  return false;
 };
 for(const card of cards)omitRemaining(card);
 return {dashboard:d,messages:[{type:'flex',altText:'ภาพรวม '+String(d?.display_name||'บุคคล'),contents:{type:'carousel',contents:cards.slice(0,10)}}]};
}
async function replyPersonDashboard(rt:string,u:string,k:string,id:string,t:string,title='👤 ภาพรวมบุคคล'){
 const x=await personDashboardMessages(u,k,id,title);
 // Source-aware routing: only buttons on the person overview carry this origin.
 for(const m of x.messages||[]){const walk=(n:any):void=>{if(!n||typeof n!=='object')return; if(n.action?.type==='postback'&&n.action.data==='เพิ่มนัด')n.action.data='เพิ่มนัด จากภาพรวม'; for(const val of Object.values(n))if(val&&typeof val==='object'){if(Array.isArray(val))val.forEach(walk);else walk(val)}};walk(m)}
 await replyMessages(rt,t,x.messages);return x.dashboard
}


const phmsCareScopeLabels:Record<string,string>={persons:'👤 ข้อมูลส่วนตัว',appointments:'📅 นัดหมาย',health_data:'🩺 สุขภาพ',medications:'💊 ยา',emergency:'🆘 ข้อมูลฉุกเฉิน'};
const phmsCareScopes=['persons','appointments','health_data','medications','emergency'];
function phmsCareLevel(member:any,scope:string){
 const per=(Array.isArray(member?.permissions)?member.permissions:[]).find((x:any)=>x?.resource===scope);
 return per?.create||per?.update||per?.delete?'manage':per?.view?'view':'none';
}
async function phmsCareScopeMenu(rt:string,u:string,k:string,id:string,t:string,memberCode:string,personCode:string){
 const ov=one(await rpc(u,k,'phms_get_line_active_person_access_overview',{p_line_user_id:id}));
 if(ov?.actor_can_manage_permissions!==true){await reply(rt,'ตอนนี้คุณยังเปลี่ยนสิทธิ์ให้คนอื่นไม่ได้',t,[pb('↩️ กลับ','สิทธิ์ของบุคคล '+personCode)]);return}
 const m=(Array.isArray(ov?.members)?ov.members:[]).find((x:any)=>String(x?.member_code||'')===memberCode);
 if(!m||m?.is_primary===true||m?.is_person_self===true){await reply(rt,'คนนี้เป็นผู้ดูแลหลักหรือเจ้าของข้อมูล จึงไม่ใช้หน้านี้เปลี่ยนสิทธิ์',t,[pb('↩️ กลับ','สิทธิ์ของบุคคล '+personCode)]);return}
 const make=(title:string,keys:string[],bg:string,includeBack=false)=>({type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:bg,paddingAll:'14px',contents:[
   {type:'text',text:title,weight:'bold',size:'md',wrap:true},
   {type:'text',text:String(m.display_name||'คนในบ้าน')+' → '+String(ov?.person_name||'คนในบ้าน'),size:'xs',color:'#667085',margin:'sm',wrap:true}
  ]},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'10px',contents:[
   ...keys.map(key=>({type:'button',style:'primary',action:{type:'postback',label:phmsCareScopeLabels[key]+' · '+(phmsCareLevel(m,key)==='manage'?'แก้ได้':phmsCareLevel(m,key)==='view'?'ดูได้':'ไม่ให้ดู'),data:'เลือกเรื่องที่ให้ดู '+memberCode+' '+personCode+' '+key}})),
   ...(includeBack?[{type:'button',action:{type:'postback',label:'↩️ กลับแบบง่าย',data:'เปลี่ยนสิทธิ์แบบง่าย '+memberCode+' '+personCode}}]:[])
  ]}
 });
 const c1=make('⚙️ ปรับสิทธิ์ด้านสุขภาพ',['appointments','medications','health_data'],'#EEF6FF');
 const c2=make('⚙️ ข้อมูลอื่น',['persons','emergency'],'#F7F9FC',true);
 await replyMessages(rt,t,[{type:'flex',altText:'⚙️ ปรับสิทธิ์ทีละเรื่อง',contents:{type:'carousel',contents:[c1,c2]}}])
}

async function phmsCarePrimaryRequests(rt:string,u:string,k:string,id:string,t:string){
 const rr=one(await rpc(u,k,'phms_line_medical_primary_requests',{p_line_user_id:id}));
 const items=Array.isArray(rr?.items)?rr.items:[];
 if(!items.length){await reply(rt,'💚 ตอนนี้ยังไม่มีคำขอให้คุณเป็นผู้ดูแลหลัก',t,[pb('🏡 กลับหน้าแรก','กลับหน้าเริ่มต้น')]);return}
 const lines:string[]=[];const buttons:any[]=[];
 for(const r of items.slice(0,5)){
  lines.push('• '+String(r.person_name||'คนในบ้าน')+' — '+(r.incoming?'รอคุณตอบรับ':'รออีกฝ่ายตอบรับ'));
  if(r.incoming){
   buttons.push(pb('✅ รับดูแล '+String(r.person_name||'คนในบ้าน').slice(0,10),'รับหน้าที่ผู้ดูแลหลัก '+String(r.request_code)));
   buttons.push(pb('❌ ไม่รับดูแล '+String(r.person_name||'คนในบ้าน').slice(0,10),'ไม่รับหน้าที่ผู้ดูแลหลัก '+String(r.request_code)));
  }
 }
 buttons.push(pb('↩️ กลับหน้าแรก','กลับหน้าเริ่มต้น'));
 await reply(rt,'💚 คำขอผู้ดูแลหลัก\n\n'+lines.join('\n')+'\n\nกดตอบรับหรือปฏิเสธได้เลย',t,buttons.slice(0,13));
}

function overviewPermissionLevel(p:any){
 if(!p)return 'none';
 if(p?.create||p?.update||p?.delete)return 'manage';
 if(p?.view)return 'view';
 return 'none'
}
function overviewMemberAccessSummary(m:any){
 const perms=Array.isArray(m?.permissions)?m.permissions:[];
 const by=(r:string)=>perms.find((x:any)=>String(x?.resource||'')===r)||{};
 const med=overviewPermissionLevel(by('medications'));
 const appt=overviewPermissionLevel(by('appointments'));
 const health=overviewPermissionLevel(by('health_data'));
 const profile=overviewPermissionLevel(by('persons'));
 const emergency=overviewPermissionLevel(by('emergency'));
 const levels=[profile,appt,health,med,emergency];
 return {
  med,appt,health,profile,emergency,
  manageAll:levels.every(x=>x==='manage'),
  anyManage:levels.some(x=>x==='manage'),
  viewAll:levels.every(x=>x==='view'||x==='manage'),
  anyView:levels.some(x=>x==='view'||x==='manage'),
  notify:perms.some((x:any)=>x?.receive_notifications===true)
 }
}
function overviewLevelThai(v:any){return String(v||'none')==='manage'?'ดูและแก้ไขได้':String(v||'none')==='view'?'ดูได้':'ดูไม่ได้'}

function phmsSimpleAccessLabel(m:any){
 const a=overviewMemberAccessSummary(m);
 if(m?.is_primary===true)return '💚 ผู้ดูแลหลัก';
 if(m?.is_caregiver===true)return '🤝 ผู้ช่วยดูแล';
 if(a.manageAll)return '✏️ ดูและแก้ไข';
 if(a.viewAll&&!a.anyManage)return '👀 ดูอย่างเดียว';
 if(a.anyView||a.anyManage)return '⚙️ ตั้งแยกบางเรื่อง';
 return '🚫 ไม่ได้ดู'
}
