async function replySimplePersonPermissionSummary(rt:string,u:string,k:string,id:string,t:string,prefix=''){
 const ov=one(await rpc(u,k,'phms_get_line_active_person_access_overview',{p_line_user_id:id}))||{};
 const members=(Array.isArray(ov?.members)?ov.members:[]).filter((m:any)=>m?.member_code&&m?.status!=='removed'&&m?.status!=='deleted'&&m?.status!=='inactive');
 const requests=Array.isArray(ov?.pending_requests)?ov.pending_requests:[];
 const personName=String(ov?.person_name||'คนในบ้าน');
 const personCode=String(ov?.person_code||'');
 const canManage=ov?.actor_can_manage_permissions===true;
 const actor=members.find((m:any)=>m?.is_self===true)||null;
 const actorAccess=actor?overviewMemberAccessSummary(actor):null;
 const rows=members.filter((m:any)=>m?.member_code&&m?.is_person_self!==true).map((m:any)=>({...m,_a:overviewMemberAccessSummary(m)}));
 const active=rows.filter((m:any)=>m?.is_primary===true||m?.is_caregiver===true||m?._a?.anyView||m?._a?.anyManage);
 const viewCount=active.filter((m:any)=>m?._a?.viewAll&&!m?._a?.anyManage&&!m?.is_caregiver&&!m?.is_primary).length;
 const editCount=active.filter((m:any)=>m?.is_primary||m?.is_caregiver||m?._a?.manageAll).length;
 const partialCount=active.filter((m:any)=>!m?.is_primary&&!m?.is_caregiver&&!m?._a?.manageAll&&!(m?._a?.viewAll&&!m?._a?.anyManage)).length;
 const summaryFooter:any[]=[];
 if(canManage&&personCode){
  summaryFooter.push({type:'button',style:'primary',action:{type:'postback',label:'➕ เพิ่มคน',data:'เพิ่มคนดูบุคคล '+personCode}});
  summaryFooter.push({type:'button',style:'secondary',action:{type:'postback',label:'💚 ผู้ดูแลหลัก',data:'เลือกผู้ดูแลหลัก '+personCode}})
 }else if(actor&&!actor?.is_person_self&&(actorAccess?.anyView||actorAccess?.anyManage)&&personCode){
  summaryFooter.push({type:'button',style:'secondary',action:{type:'postback',label:'📥 ขอสิทธิ์เพิ่ม',data:'ขอสิทธิ์แบบง่าย '+personCode}})
 }
 summaryFooter.push({type:'button',action:{type:'postback',label:'↩️ เลือกเจ้าของข้อมูล',data:'สิทธิ์ข้อมูล'}});
 const cards:any[]=[{type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:'#F4F1FA',paddingAll:'16px',contents:[
   {type:'text',text:'🔐 สิทธิ์ข้อมูลของ '+personName,weight:'bold',size:'lg',color:'#57456E',wrap:true},
   {type:'text',text:canManage?'เลือกชื่อคน แล้วกด “เปลี่ยนสิทธิ์”':'สรุปว่าใครเข้าถึงข้อมูลนี้ได้',size:'sm',color:'#667085',margin:'sm',wrap:true}
  ]},
  body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'16px',contents:[
   ...(prefix?[{type:'text',text:prefix,size:'sm',weight:'bold',color:'#285943',wrap:true},{type:'separator',margin:'md'}]:[]),
   {type:'text',text:'👥 เข้าถึงข้อมูล '+String(active.length)+' คน',size:'md',weight:'bold',wrap:true},
   {type:'text',text:'👀 ดูอย่างเดียว '+viewCount+'  •  ✏️ ดูและแก้ '+editCount+(partialCount?'  •  ⚙️ บางเรื่อง '+partialCount:''),size:'sm',color:'#555555',wrap:true},
   {type:'text',text:canManage?'แบบง่ายมี 3 ระดับ: ไม่ให้ดู / ดูอย่างเดียว / ดูและแก้ไข':'คุณยังแก้สิทธิ์ของคนอื่นจากหน้านี้ไม่ได้',size:'xs',color:'#777777',wrap:true}
  ]},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:summaryFooter.slice(0,3)}
 }];
 for(const m of active.slice(0,9)){
  cards.push({type:'bubble',size:'micro',
   header:{type:'box',layout:'vertical',backgroundColor:(m?.is_primary||m?.is_caregiver||m?._a?.anyManage)?'#EEF8F3':'#F7F9FC',paddingAll:'14px',contents:[
    {type:'text',text:String(m?.display_name||'สมาชิก'),weight:'bold',size:'md',wrap:true}
   ]},
   body:{type:'box',layout:'vertical',paddingAll:'12px',contents:[
    {type:'text',text:'ตอนนี้: '+phmsSimpleAccessLabel(m),size:'sm',weight:'bold',wrap:true,color:'#555555'}
   ]},
   ...(canManage&&!m?.is_primary?{footer:{type:'box',layout:'vertical',paddingAll:'10px',contents:[
    {type:'button',style:'primary',action:{type:'postback',label:'✏️ เปลี่ยนสิทธิ์',data:'เปลี่ยนสิทธิ์แบบง่าย '+String(m.member_code)+' '+personCode}}
   ]}}:{})
  })
 }
 if(requests.length){
  cards.push({type:'bubble',size:'micro',
   header:{type:'box',layout:'vertical',backgroundColor:'#FFF7E8',paddingAll:'14px',contents:[
    {type:'text',text:'📥 คำขอรอตรวจ '+String(requests.length),weight:'bold',size:'md',wrap:true}
   ]},
   footer:{type:'box',layout:'vertical',paddingAll:'10px',contents:[
    {type:'button',style:'primary',action:{type:'postback',label:'เปิดคำขอ',data:'ตรวจคำขอสิทธิ์'}}
   ]}
  })
 }
 if(!active.length)cards.push({type:'bubble',size:'micro',body:{type:'box',layout:'vertical',paddingAll:'16px',contents:[
  {type:'text',text:'ยังไม่มีคนอื่นที่ได้รับสิทธิ์',size:'md',weight:'bold',wrap:true}
 ]}});
 await replyMessages(rt,t,[{type:'flex',altText:'🔐 สิทธิ์ข้อมูลของ '+personName,contents:{type:'carousel',contents:cards.slice(0,12)}}])
}
async function replySimplePermissionLevelPicker(rt:string,u:string,k:string,id:string,t:string,memberCode:string,personCode:string){
 const ov=one(await rpc(u,k,'phms_get_line_active_person_access_overview',{p_line_user_id:id}))||{};
 if(ov?.actor_can_manage_permissions!==true){await replySimplePersonPermissionSummary(rt,u,k,id,t);return}
 const m=(Array.isArray(ov?.members)?ov.members:[]).find((x:any)=>String(x?.member_code||'')===String(memberCode));
 if(!m){await reply(rt,'⚠️ ไม่พบสมาชิกนี้ เปิดหน้าสิทธิ์ใหม่อีกครั้งนะ',t,[pb('🔐 สิทธิ์ข้อมูล','สิทธิ์ข้อมูล')]);return}
 if(m?.is_person_self===true||m?.is_primary===true){await reply(rt,'ℹ️ คนนี้เป็นเจ้าของข้อมูลหรือผู้ดูแลหลัก จึงไม่ได้เปลี่ยนจากชุดสิทธิ์ทั่วไป',t,[pb('↩️ กลับ','สิทธิ์ของบุคคล '+personCode)]);return}
 const personName=String(ov?.person_name||'คนในบ้าน'),memberName=String(m?.display_name||'สมาชิก');
 const current=phmsSimpleAccessLabel(m);
 const easy:any={type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:'#EEF6FF',paddingAll:'16px',contents:[
   {type:'text',text:'✏️ เปลี่ยนสิทธิ์',weight:'bold',size:'lg',color:'#365F8D'},
   {type:'text',text:memberName+' → '+personName,size:'md',weight:'bold',margin:'sm',wrap:true}
  ]},
  body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'16px',contents:[
   {type:'text',text:'ตอนนี้: '+current,size:'sm',weight:'bold',wrap:true},
   {type:'text',text:'เลือกแบบที่ต้องการได้เลย',size:'sm',color:'#667085',wrap:true}
  ]},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:[
   {type:'button',style:'primary',action:{type:'postback',label:'🚫 ไม่ให้ดู',data:'บันทึกสิทธิ์แบบง่าย '+memberCode+' '+personCode+' none'}},
   {type:'button',style:'primary',action:{type:'postback',label:'👀 ดูอย่างเดียว',data:'บันทึกสิทธิ์แบบง่าย '+memberCode+' '+personCode+' view'}},
   {type:'button',style:'primary',action:{type:'postback',label:'✏️ ดูและแก้ไข',data:'บันทึกสิทธิ์แบบง่าย '+memberCode+' '+personCode+' manage'}}
  ]}
 };
 const more:any={type:'bubble',size:'micro',
  header:{type:'box',layout:'vertical',backgroundColor:'#F7F9FC',paddingAll:'14px',contents:[
   {type:'text',text:'ต้องการแยกเป็นรายเรื่อง?',weight:'bold',size:'md',wrap:true},
   {type:'text',text:'เช่น ให้ดูนัดได้ แต่ไม่ให้ดูยา',size:'xs',color:'#667085',margin:'sm',wrap:true}
  ]},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'10px',contents:[
   {type:'button',style:'secondary',action:{type:'postback',label:'⚙️ ปรับทีละเรื่อง',data:'ตั้งสิทธิ์ดูแล '+memberCode+' '+personCode}},
   {type:'button',action:{type:'postback',label:'↩️ กลับ',data:'สิทธิ์ของบุคคล '+personCode}}
  ]}
 };
 await replyMessages(rt,t,[{type:'flex',altText:'✏️ เปลี่ยนสิทธิ์ '+memberName,contents:{type:'carousel',contents:[easy,more]}}])
}

async function replyPersonCaregiverManager(rt:string,u:string,k:string,id:string,t:string,prefix=''){
 await replySimplePersonPermissionSummary(rt,u,k,id,t,prefix)
}

async function replyAddPersonViewerPicker(rt:string,u:string,k:string,id:string,t:string,personCode:string){
 const ov=one(await rpc(u,k,'phms_get_line_active_person_access_overview',{p_line_user_id:id}));
 if(ov?.actor_can_manage_permissions!==true)throw new Error('permission_management_denied');
 const rows=(Array.isArray(ov?.members)?ov.members:[]).filter((m:any)=>{
  if(m?.is_person_self===true)return false;
  const a=overviewMemberAccessSummary(m);
  return !a.anyView&&!a.anyManage
 });
 const cards:any[]=[{type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:'#EEF8F3',paddingAll:'16px',contents:[
   {type:'text',text:'➕ เพิ่มคนที่ดูได้',weight:'bold',size:'xl',color:'#2F6B4F'},
   {type:'text',text:'ข้อมูลของ '+String(ov?.person_name||'บุคคลนี้'),size:'sm',weight:'bold',margin:'sm',wrap:true}
  ]},
  body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'16px',contents:[
   {type:'text',text:'เลือกสมาชิก 1 คน แล้วอิ่มอุ่นจะให้สิทธิ์ “ดูได้”',size:'sm',weight:'bold',wrap:true},
   {type:'text',text:'ดูได้: 👤 ข้อมูลส่วนตัว • 💊 ยา • 📅 นัดหมาย • 🩺 สุขภาพ • 🆘 ข้อมูลฉุกเฉิน\nแก้ไขข้อมูลไม่ได้',size:'sm',color:'#555555',wrap:true},
   {type:'separator',margin:'md'},
   {type:'text',text:rows.length?'เลื่อนไปด้านข้างแล้วกด “ให้ดูได้” ใต้สมาชิกที่ยังไม่มีสิทธิ์\nถ้าคนที่ต้องการยังไม่อยู่ในครอบครัว ให้กด “ชวนสมาชิกใหม่” ด้านล่าง':'✅ สมาชิกที่อยู่ในครอบครัวตอนนี้มีสิทธิ์อยู่แล้วทั้งหมด\nถ้าต้องการเพิ่มคนใหม่ ให้ชวนเข้าครอบครัวก่อน แล้วกลับมาให้สิทธิ์ดู',size:'sm',color:rows.length?'#667085':'#285943',wrap:true}
  ]},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:[
   {type:'button',style:'secondary',action:{type:'postback',label:'🔗 ชวนสมาชิกใหม่',data:'ชวนเข้าครอบครัว'}},
   {type:'button',action:{type:'postback',label:'↩️ กลับหน้าสรุป',data:'คนที่ดูหรือช่วยดูแล'}}
  ]}
 }];
 for(const m of rows.slice(0,9)){
  cards.push({type:'bubble',size:'micro',
   header:{type:'box',layout:'vertical',paddingAll:'14px',contents:[
    {type:'text',text:String(m?.display_name||'สมาชิก'),weight:'bold',size:'md',wrap:true},
    {type:'text',text:'ยังไม่มีสิทธิ์เข้าถึงข้อมูลของบุคคลนี้',size:'xs',color:'#777777',margin:'sm',wrap:true}
   ]},
   footer:{type:'box',layout:'vertical',paddingAll:'10px',contents:[
    {type:'button',style:'primary',action:{type:'postback',label:'👀 ให้ดูได้',data:'ตั้งคนดูบุคคล '+String(m?.member_code||'')+' '+String(personCode)}}
   ]}
  })
 }
 await replyMessages(rt,t,[{type:'flex',altText:'➕ เพิ่มคนที่ดูข้อมูลของ '+String(ov?.person_name||'บุคคลนี้')+' ได้',contents:{type:'carousel',contents:cards.slice(0,10)}}])
}

/* PHMS_PERSON_EDIT_INPUT_CARD_V1: clear instructions, existing save paths retained. */
async function phmsTextInputCard(rt:string,t:string,title:string,example:string,note:string,cancel='แก้รายละเอียดบุคคล',current?:any){
 const card:any={type:'flex',altText:title,contents:{type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:'#F2EDFB',paddingAll:'16px',contents:[{type:'text',text:title,size:'lg',weight:'bold',color:'#49386B',wrap:true},{type:'text',text:/ชื่อในบ้าน/u.test(title)?'ชื่อที่ใช้เรียกร่วมกันในบ้าน ทุกคนที่มีสิทธิ์เห็นชื่อเดียวกัน':/ชื่อส่วนตัว|ชื่อที่ฉันใช้เรียก/u.test(title)?'ชื่อที่คุณตั้งไว้เรียกคนนี้ เห็นเฉพาะคุณ':/ความสัมพันธ์/u.test(title)?'คนนี้เกี่ยวข้องกับคุณอย่างไร เช่น ยาย หรือแม่':/วันเกิด/u.test(title)?'วัน เดือน ปีเกิดของคนนี้':/นามสกุล/u.test(title)?'นามสกุลตามข้อมูลจริง':/ชื่อจริง/u.test(title)?'ชื่อจริงตามข้อมูลจริง':'แก้เฉพาะข้อมูลหัวข้อนี้ ช่องอื่นไม่เปลี่ยน',size:'sm',color:'#49386B',wrap:true,margin:'sm'}]},
  body:{type:'box',layout:'vertical',paddingAll:'16px',spacing:'md',contents:[
   ...(current!==undefined?[{type:'box',layout:'vertical',backgroundColor:'#F5F7FA',cornerRadius:'10px',paddingAll:'12px',spacing:'xs',contents:[{type:'text',text:'ค่าปัจจุบัน',weight:'bold',size:'sm',color:'#425466'},{type:'text',text:String(current??'').trim()||'ยังไม่ได้ระบุ',size:'lg',weight:'bold',color:'#263238',wrap:true}]}]:[]),
   {type:'text',text:'พิมพ์ข้อมูลใหม่ในช่องแชต แล้วกดส่ง',size:'md',weight:'bold',color:'#263238',wrap:true},
   {type:'text',text:'ตัวอย่าง: '+example,size:'md',color:'#263238',wrap:true},
   {type:'text',text:note,size:'sm',color:'#52606D',wrap:true}
  ]},
  footer:{type:'box',layout:'vertical',paddingAll:'12px',contents:[{type:'button',style:'secondary',height:'md',color:'#8E3E4C',action:{type:'postback',label:'❌ ยกเลิก',data:cancel,displayText:'❌ ยกเลิก'}}]}
 }};
 await replyMessages(rt,t,[card])
}
/* PHMS_GLOBAL_TEXT_EDIT_STANDARD_V2: single reusable card for every typed-input edit. */
async function phmsPersonInputCard(rt:string,t:string,title:string,example:string,note:string,cancel='แก้รายละเอียดบุคคล',current?:any){
 return phmsTextInputCard(rt,t,title,example,note,cancel,current);
}
async function replyPersonPhotoGallery(rt:string,u:string,k:string,id:string,t:string){
 const out=one(await rpc(u,k,'phms_list_line_person_photos',{p_line_user_id:id}));
 const photos=Array.isArray(out?.photos)?out.photos:[];
 const cards:any[]=[];
 for(const p of photos.slice(0,9)){
  const url=await signedPersonPhotoUrl(u,k,p?.object_name); if(!url)continue;
  const footer:any[]=[];
  if(!p?.selected_for_me)footer.push({type:'button',style:'primary',action:{type:'postback',label:'ใช้เป็นรูปที่ฉันอยากเห็น',data:'เลือกรูปบุคคล '+String(p.photo_code)}});
  if(p?.shared)footer.push({type:'button',style:'secondary',action:{type:'postback',label:'🔒 ให้เห็นเฉพาะฉัน',data:'ตั้งรูปบุคคลส่วนตัว '+String(p.photo_code)}});
  else if(out?.can_set_shared)footer.push({type:'button',style:'secondary',action:{type:'postback',label:'🌐 แชร์ให้คนอื่นเห็น',data:'ยืนยันแชร์รูปบุคคล '+String(p.photo_code)}});
  cards.push({type:'bubble',size:'micro',hero:{type:'image',url,size:'full',aspectRatio:'1:1',aspectMode:'cover'},
   body:{type:'box',layout:'vertical',paddingAll:'12px',contents:[
    {type:'text',text:p?.shared?'🌐 รูปที่แชร์ให้คนอื่นเห็น':'🔒 รูปส่วนตัว',weight:'bold',size:'sm',wrap:true},
    {type:'text',text:p?.selected_for_me?'✅ รูปที่ฉันเลือกดูอยู่':(p?.mine?'รูปที่ฉันเพิ่มไว้':'รูปที่เจ้าตัวแชร์ให้ดู'),size:'xs',color:'#777777',margin:'sm',wrap:true}
   ]},
   footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'10px',contents:footer.length?footer:[{type:'button',action:{type:'postback',label:'↩️ ภาพรวม',data:'รายละเอียดบุคคล'}}]}
  });
 }
 const summary:any={type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:'#EEF6FF',paddingAll:'16px',contents:[
   {type:'text',text:'📷 รูปบุคคล',weight:'bold',size:'lg',wrap:true,color:'#365F8D'}
  ]},
  body:{type:'box',layout:'vertical',paddingAll:'16px',spacing:'sm',contents:[
   {type:'text',text:photos.length?'เลือกรูปที่ต้องการดู หรือเพิ่มรูปใหม่ได้เลย':'ยังไม่มีรูปของคนนี้ เพิ่มรูปแรกได้เลย',size:'sm',wrap:true,color:'#334155'},
   {type:'text',text:'รูปที่คุณเลือกจะแสดงให้คุณเห็นเท่านั้น ไม่เปลี่ยนรูปที่คนอื่นเลือกไว้',size:'sm',wrap:true,color:'#64748B'}
  ]},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:[
   {type:'button',style:'primary',action:{type:'postback',label:'➕ เพิ่มรูป',data:'เพิ่มรูปบุคคล'}},
   {type:'button',style:'secondary',action:{type:'postback',label:'↩️ รายละเอียด',data:'รายละเอียดบุคคล'}}
  ]}
 };
 await replyMessages(rt,t,[{type:'flex',altText:'📷 รูปบุคคล',contents:cards.length?{type:'carousel',contents:[summary,...cards].slice(0,10)}:summary}])
}
async function replyNotificationTargetPicker(rt:string,u:string,k:string,id:string,t:string,batchId:string){
 const out=one(await rpc(u,k,'phms_line_notification_target_options',{p_line_user_id:id,p_batch_id:batchId}));
 const users=Array.isArray(out?.users)?out.users:[],groups=Array.isArray(out?.groups)?out.groups:[];
 const cards:any[]=[{type:'bubble',size:'kilo',header:{type:'box',layout:'vertical',backgroundColor:'#EEF6FF',paddingAll:'16px',contents:[
  {type:'text',text:'🔔 เลือกผู้รับแจ้งเตือน',weight:'bold',size:'lg',color:'#365F8D'},
  {type:'text',text:'แตะเพื่อเลือก/ยกเลิกได้ทันที',size:'xs',wrap:true,color:'#667788',margin:'sm'}
 ]},body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'16px',contents:[
  {type:'text',text:'เลือกเฉพาะคนหรือกลุ่มที่ควรได้รับการแจ้งเตือนรายการนี้',size:'sm',wrap:true},
  {type:'text',text:'อิ่มอุ่นจะไม่ส่งให้ทั้งครอบครัวอัตโนมัติ',size:'xs',wrap:true,color:'#777777',margin:'sm'}
 ]},footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:[
  {type:'button',action:{type:'postback',label:'✅ เสร็จแล้ว',data:'จบตั้งผู้รับแจ้งเตือน'}}
 ]}}];
 for(const x of users.slice(0,8)){
  cards.push({type:'bubble',size:'micro',header:{type:'box',layout:'vertical',paddingAll:'14px',contents:[
   {type:'text',text:String(x.display_name||'สมาชิก PHMS'),weight:'bold',size:'md',wrap:true},
   {type:'text',text:x.line_ready?'LINE พร้อมรับแจ้งเตือน':'ยังไม่มี LINE ที่พร้อมรับแจ้งเตือน',size:'xs',wrap:true,color:'#777777',margin:'sm'}
  ]},footer:{type:'box',layout:'vertical',paddingAll:'10px',contents:[
   {type:'button',style:x.selected?'primary':'secondary',action:{type:'postback',label:(x.selected?'☑ ':'☐ ')+phmsFitActionLabelNoEllipsis(String(x.display_name||'สมาชิก'),12),data:'ตั้งผู้รับแจ้งเตือน '+batchId+' user '+String(x.code)+' '+(x.selected?'off':'on')}}
  ]}});
 }
 for(const g of groups.slice(0,3)){
  cards.push({type:'bubble',size:'micro',header:{type:'box',layout:'vertical',paddingAll:'14px',contents:[
   {type:'text',text:String(g.label||'LINE กลุ่ม'),weight:'bold',size:'md',wrap:true},
   {type:'text',text:'กลุ่มที่บอทเคยถูกตั้งเป็น target ในครอบครัวนี้',size:'xs',wrap:true,color:'#777777',margin:'sm'}
  ]},footer:{type:'box',layout:'vertical',paddingAll:'10px',contents:[
   {type:'button',style:g.selected?'primary':'secondary',action:{type:'postback',label:(g.selected?'☑ ':'☐ ')+'ส่งเข้ากลุ่ม',data:'ตั้งผู้รับแจ้งเตือน '+batchId+' group '+String(g.code)+' '+(g.selected?'off':'on')}}
  ]}});
 }
 await replyMessages(rt,t,[{type:'flex',altText:'🔔 เลือกผู้รับแจ้งเตือน',contents:{type:'carousel',contents:cards.slice(0,12)}}])
}
function personFieldThai(v:any){return ({display_name:'ชื่อที่ฉันใช้เรียก',nickname:'ชื่อในบ้าน',first_name:'ชื่อจริง',last_name:'นามสกุล',date_of_birth:'วันเกิด',sex:'เพศ',relationship:'ความสัมพันธ์'} as any)[String(v||'')]||String(v||'ข้อมูล')}
async function replyPersonChangeRequests(rt:string,u:string,k:string,id:string,t:string){
 const out=one(await rpc(u,k,'phms_list_line_person_change_requests',{p_line_user_id:id}));
 const rows=Array.isArray(out?.requests)?out.requests:[];
 if(!rows.length){await reply(rt,'📥 ยังไม่มีคำขอแก้ข้อมูลที่รอตรวจ',t,[pb('↩️ ภาพรวม','รายละเอียดบุคคล')]);return}
 const cards=rows.slice(0,10).map((x:any)=>({type:'bubble',size:'micro',
  header:{type:'box',layout:'vertical',backgroundColor:'#FFF8E8',paddingAll:'14px',contents:[
   {type:'text',text:'✏️ '+String(x.person_name||'บุคคล'),weight:'bold',size:'md',wrap:true},
   {type:'text',text:personFieldThai(x.field),size:'xs',color:'#777777',margin:'sm'}
  ]},
  body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'14px',contents:[
   dashRow('เดิม',x.old_value||'—'),dashRow('ขอแก้เป็น',x.requested_value||'—'),
   ...(x.reason?[{type:'text',text:'เหตุผล: '+String(x.reason),size:'xs',wrap:true,color:'#666666'}]:[])
  ]},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:x.can_review?[
   {type:'button',style:'primary',action:{type:'postback',label:'✅ อนุมัติ',data:'อนุมัติคำขอแก้ '+String(x.request_code)}},
   {type:'button',style:'secondary',action:{type:'postback',label:'❌ ปฏิเสธ',data:'ปฏิเสธคำขอแก้ '+String(x.request_code)}}
  ]:[{type:'button',action:{type:'postback',label:'↩️ ภาพรวม',data:'รายละเอียดบุคคล'}}]}
 }));
 await replyMessages(rt,t,[{type:'flex',altText:'📥 คำขอแก้ข้อมูลบุคคล',contents:{type:'carousel',contents:cards}}])
}
/* AIM_PERSON_PROFILE_DETAIL_V3: compact information, 3 buttons, color direct from person view. */
function personProfileFlex(p:any,title='👤 รายละเอียดบุคคล'){
 const line=(label:string,value:any)=>({type:'box',layout:'horizontal',spacing:'md',contents:[
  {type:'text',text:label,size:'sm',color:'#64748B',flex:4,wrap:true},
  {type:'text',text:String(value??'—'),size:'sm',color:'#263649',flex:7,wrap:true}
 ]});
 const display=String(p?.display_name||'บุคคล'),shared=String(p?.nickname||'').trim();
 const legal=[p?.first_name,p?.last_name].filter(Boolean).map(String).join(' ').trim();
 const birth=p?.birth_info||{},age=birth?.age;
 const bdate=birth?.date||p?.date_of_birth;
 const personButtons=phmsPersonButtonTheme(p?.card_color);
 const buttons:any[]=[
  ...(p?.can_edit===true?[{type:'button',height:'md',style:'primary',color:personButtons.main,action:{type:'postback',label:'✏️ แก้ไข',data:'แก้รายละเอียดบุคคล'}}]:[]),

  {type:'button',height:'md',style:'secondary',color:personButtons.second,action:{type:'postback',label:'↩️ ภาพรวม'+String(p?.display_name||'บุคคล').trim(),displayText:'↩️ ภาพรวมบุคคล'+String(p?.display_name||'บุคคล').trim(),data:'กลับภาพรวมบุคคล'}}
 ];
 const sexCode=String(p?.sex||'').toLowerCase().trim();
 const sexLabel=phmsSexThaiIcon(p?.sex||p?.sex_label||p?.gender_label);
 const sections:any[]=[
  ...(p?.detail_photo_url?[{type:'box',layout:'vertical',alignItems:'center',contents:[{type:'image',url:p.detail_photo_url,size:'xl',aspectRatio:'1:1',aspectMode:'cover',align:'center'}]}]:[]),
  {type:'text',text:'🪪 ข้อมูลส่วนตัว',size:'md',weight:'bold',color:'#315C85'},
  ...(legal?[line('ชื่อจริง',legal)]:[]),
  ...(sexLabel?[line('เพศ',sexLabel)]:[]),
  ...(bdate?[line('วันเกิด',formatPersonProfileDate(bdate).replace(' พ.ศ. ', ' '))]:[]),
  ...(age!=null?[line('อายุ',String(age)+' ปี')]:[]),
  {type:'separator',margin:'md'},
  {type:'text',text:'🏡 ข้อมูลในบ้าน',size:'md',weight:'bold',color:'#315C85'},
  line('ชื่อส่วนตัว',display),
  line('ชื่อในบ้าน',shared||'ยังไม่ได้ตั้ง'),
  ...(p?.relationship_label&&String(p.relationship_label).trim()!==shared&&String(p.relationship_label).trim()!==display?[line('ความสัมพันธ์',p.relationship_label)]:[]),
  line('ผู้ดูแลหลัก',(()=>{const caregiver=String(p?.primary_caregiver_name||'').trim();return (caregiver&&(caregiver===display||caregiver===shared))||(!caregiver&&p?.self_manage===true)?'ตัวเอง':caregiver||'ยังไม่ได้ระบุ'})()),

  {type:'box',layout:'horizontal',spacing:'md',alignItems:'center',contents:[{type:'text',text:'สีประจำตัว',size:'sm',color:'#64748B',flex:4},{type:'box',layout:'horizontal',flex:7,spacing:'sm',alignItems:'center',contents:[{type:'box',layout:'vertical',width:'22px',height:'22px',cornerRadius:'6px',backgroundColor:String(p?.card_color||'#E7F2FF'),contents:[{type:'text',text:'●',size:'xs',color:String(p?.card_color||'#E7F2FF')}]},{type:'text',text:p?.card_color?String(p.card_color).toUpperCase():'ยังไม่ได้ตั้ง',size:'sm',color:'#263649'}]}]}
 ];
 const split=sections.findIndex((x:any)=>x?.type==='text'&&x.text==='🏡 ข้อมูลในบ้าน');
 const head=(i:number)=>({type:'box',layout:'vertical',backgroundColor:String(p?.header_color||'#E7F2FF'),phmsCounterColor:personButtons.main,paddingAll:'16px',contents:[
 {type:'text',text:title,size:'lg',weight:'bold',color:'#28507B'},
 {type:'text',text:'ข้อมูลของ '+display,size:'sm',color:'#263649',wrap:true}
 ]});
 const bubble=(i:number,items:any[],footer=false):any=>({type:'bubble',size:'kilo',header:head(i),body:{type:'box',layout:'vertical',spacing:'md',paddingAll:'16px',contents:items},
 ...(footer?{footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:buttons}}:{})});
 return {type:'flex',altText:title+' • '+display,contents:{type:'carousel',contents:[bubble(1,sections.slice(0,split)),bubble(2,sections.slice(split),true)]}};
}

async function replyPersonProfileCard(rt:string,u:string,k:string,id:string,t:string,title='👤 รายละเอียดบุคคล'){
  const p=one(await rpc(u,k,'phms_get_line_active_person_profile',{p_line_user_id:id}));
 try{
  const ov=one(await rpc(u,k,'phms_get_line_active_person_access_overview',{p_line_user_id:id}));
  p.can_manage_permissions=ov?.actor_can_manage_permissions===true;
  p.person_code=String(ov?.person_code||'')
 }catch{}
  try{
   const cp=one(await rpc(u,k,'phms_line_person_card_colors',{p_line_user_id:id}));
   const row=(Array.isArray(cp?.items)?cp.items:[]).find((x:any)=>String(x?.person_code||'')===String(p?.person_code||''));
   p.can_change_color=row?.can_change===true;
   if(row?.card_color){p.card_color=row.card_color;p.header_color=phmsReadablePersonHeaderColor(row.card_color)}
  }catch{}
  try{
   const ci=one(await rpc(u,k,'phms_list_line_person_caregivers',{p_line_user_id:id}));
   p.primary_caregiver_name=String(ci?.primary_name||p?.primary_caregiver_name||'');
   p.self_manage=ci?.self_manage===true;
   if(!ci?.primary_name&&ci?.primary_status==='active')console.warn('person_primary_missing_name');
  }catch{}
  try{
   const gallery=one(await rpc(u,k,'phms_list_line_person_photos',{p_line_user_id:id}));
   const photos=Array.isArray(gallery?.photos)?gallery.photos:[];
   const picked=photos.find((x:any)=>x?.selected_for_me===true)||photos.find((x:any)=>x?.shared===true);
   if(picked?.object_name)p.detail_photo_url=await signedPersonPhotoUrl(u,k,picked.object_name);
  }catch(err){console.error('person_detail_photo',String(err))}
  const msg:any=personProfileFlex(p,title);

  if(p?.setup_status==='draft'&&p?.can_manage_setup===true&&p?.person_code){
    const last=msg.contents.type==='carousel'?msg.contents.contents[1]:msg.contents;
    const f=last?.footer?.contents||[];
    last.footer.contents=[
      {type:'text',text:'🧩 บุคคลนี้ยังเป็นฉบับร่าง คนอื่นในบ้านยังไม่เห็น',size:'xs',color:'#8A6B2F',wrap:true},
      {type:'button',style:'primary',action:{type:'postback',label:'✏️ ตั้งค่าต่อ',data:'ตั้งค่าบุคคลร่าง '+String(p.person_code)}},
      {type:'button',style:'secondary',action:{type:'postback',label:'👁️ กำหนดว่าใครเห็น',data:'ตั้งการมองเห็นบุคคล '+String(p.person_code)}},
      {type:'button',style:'primary',action:{type:'postback',label:'✅ ตั้งค่าเสร็จ — แสดงในบ้าน',data:'เผยแพร่บุคคล '+String(p.person_code)}},
      ...f
    ].slice(0,8)
  }
  await replyMessages(rt,t,[msg])
}
/* AIM_PERSON_EDIT_CAROUSEL_V1: direct edit by topic, permission-aware actions, 3 max buttons per card. */
async function replyPersonEditMenu(rt:string,u:string,k:string,id:string,t:string){
 const p=one(await rpc(u,k,'phms_get_line_active_person_profile',{p_line_user_id:id}));
 const canEdit=p?.can_edit===true;
 if(!canEdit){await reply(rt,'🔒 คุณยังไม่มีสิทธิ์แก้ไขข้อมูลส่วนตัวของคนนี้',t,[pb('↩️ รายละเอียดบุคคล','รายละเอียดบุคคล')]);return}
 let canColor=false;
 try{
  const color=one(await rpc(u,k,'phms_line_person_card_colors',{p_line_user_id:id}));
  canColor=(Array.isArray(color?.items)?color.items:[]).some((x:any)=>x?.can_change===true&&String(x?.person_code||'')===String(p?.person_code||''))
 }catch{}
 const make=(head:string,note:string,bg:string,actions:[string,string][])=>({type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:bg,paddingAll:'16px',contents:[
   {type:'text',text:head,size:'lg',weight:'bold',color:'#294B6B',wrap:true},
   {type:'text',text:note,size:'sm',color:'#59687B',wrap:true,margin:'sm'}
  ]},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'12px',contents:actions.slice(0,3).map(([label,data])=>({
   type:'button',style:'primary',height:'md',action:{type:'postback',label,data}
  }))}
 });
 const nameActions:[string,string][]=[['🏷️ ชื่อส่วนตัว','ตั้งชื่อที่ฉันใช้เรียก']];
 if(canEdit)nameActions.push(['🏡 ชื่อในบ้าน','แก้ข้อมูลบุคคล nickname']);
 nameActions.push(['👪 ความสัมพันธ์','ตั้งความสัมพันธ์กับฉัน']);
 const cards:any[]=[make('🏷️ ตั้งค่าชื่อ','เลือกชื่อส่วนตัว หรือชื่อในบ้าน','#EDF5FF',nameActions)];
 if(canEdit){
 cards.push(make('🪪 ข้อมูลส่วนตัว','เลือกแก้ชื่อจริงหรือนามสกุล','#F2EDFB',[
  ['🪪 ชื่อจริง','แก้ข้อมูลบุคคล first_name'],
  ['🪪 นามสกุล','แก้ข้อมูลบุคคล last_name']
 ]));
 cards.push(make('🩺 ข้อมูลสุขภาพพื้นฐาน','เลือกวันเกิดหรือเพศที่บันทึกไว้','#E5F3EB',[
  ['🎂 วันเกิด','แก้ข้อมูลบุคคล date_of_birth'],
  ['🩺 เพศที่บันทึก','แก้ข้อมูลบุคคล sex']
 ]));
 }
 const visual:[string,string][]=[['📷 รูปบุคคล','เพิ่มรูปบุคคล']];
 if(canColor&&/^[a-f0-9]{12}$/i.test(String(p?.person_code||'')))visual.push(['🎨 สีประจำตัว','ตั้งสีบุคคล '+String(p.person_code)]);
 
 cards.push(make('🎨 รูปและสี','ปรับรูปที่เห็นและสีหัวการ์ดของคนนี้','#F7EAF2',visual));
 cards.push(make('🧾 แก้หลายช่อง','แก้หลายช่องพร้อมกันได้ในข้อความเดียว','#FFF7E8',[
  ...(canEdit?[['🧾 แก้ด้วยเทมเพลต','แก้ข้อมูลบุคคล template'] as [string,string]]:[]),
  ['↩️ รายละเอียดบุคคล','รายละเอียดบุคคล']
 ]));
 await replyMessages(rt,t,[{type:'flex',altText:'✏️ แก้ข้อมูลบุคคล • '+String(p?.display_name||'บุคคล').trim(),contents:{type:'carousel',contents:cards}}])
}
