async function pushPersonRelationshipPrompt(to:string,t:string,personName:string){
 const bubble:any={type:'flex',altText:'👤 เพิ่มบุคคลแล้ว — ระบุความสัมพันธ์ได้ภายหลัง',contents:{
  type:'bubble',
  header:{type:'box',layout:'vertical',contents:[
   {type:'text',text:'✅ เพิ่มบุคคลแล้ว',weight:'bold',size:'xl'},
   {type:'text',text:'สร้างบุคคลก่อน แล้วค่อยเติมรายละเอียดได้',size:'sm',color:'#777777',margin:'sm'}
  ]},
  body:{type:'box',layout:'vertical',spacing:'md',contents:[
   {type:'box',layout:'horizontal',spacing:'sm',contents:[
    {type:'text',text:'ชื่อ',size:'sm',color:'#777777',flex:3},
    {type:'text',text:String(personName||'บุคคล'),size:'sm',weight:'bold',flex:7,wrap:true}
   ]},
   {type:'text',text:'ต้องการระบุความสัมพันธ์กับคุณตอนนี้ไหม?\nถ้ายังไม่แน่ใจ สามารถข้ามแล้วมาแก้ทีหลังได้',size:'sm',color:'#555555',wrap:true}
  ]},
  footer:{type:'box',layout:'vertical',spacing:'sm',contents:[
   {type:'button',style:'primary',action:{type:'postback',label:'👪 ระบุความสัมพันธ์',data:'ระบุความสัมพันธ์คนใหม่'}},
   {type:'button',action:{type:'postback',label:'⏭️ ไว้ทีหลัง',data:'ข้ามความสัมพันธ์คนใหม่'}},
   {type:'button',action:{type:'message',label:'👤 ดูบุคคลในครอบครัว',text:'คนในครอบครัว'}}
  ]}
 }};
 const r=await phmsChargeableLineFetch('https://api.line.me/v2/bot/message/push',{method:'POST',headers:{Authorization:'Bearer '+t,'content-type':'application/json'},body:JSON.stringify({to,messages:[phmsDualActionMessage(bubble)]})});
 if(!r.ok)console.error('person_relationship_prompt',r.status,await r.text())
}
async function promptManualForStoredSource(e:any,u:string,k:string,lineUserId:string,token:string,sourceId:string,appointmentIntent:boolean){
 if(appointmentIntent){
   await state(u,k,lineUserId,'appointment_image_classify',{source_id:sourceId});
   await replyOrPush(e.replyToken,lineUserId,
     '✅ เก็บรูป/ไฟล์ไว้แล้ว\n\nรูปนี้เป็นอะไร?',
     token,[pb('📅 รูปใบนัด','จัดประเภทรูปนัด ใบนัด'),pb('📎 เอกสารประกอบนัด','จัดประเภทรูปนัด เอกสารประกอบ'),pb('❌ ยกเลิก','นัดหมาย')]
   );
   return
 }
 const codeRef=await beginManualFallback(u,k,lineUserId,sourceId,'manual_only_image_mode');
 await state(u,k,lineUserId,'intake_manual_category',{source_code:codeRef,source_id:sourceId});
 await replyOrPush(e.replyToken,lineUserId,
   '📎 เก็บรูป/ไฟล์ไว้แล้ว\n\nตอนนี้อิ่มอุ่นยังอ่านข้อมูลจากรูปให้อัตโนมัติไม่ได้\nเลือกว่ารูปนี้เกี่ยวกับอะไร แล้วพิมพ์ข้อมูลสำคัญเองได้เลย\nอิ่มอุ่นจะบันทึกข้อมูลที่กรอกคู่กับรูปต้นฉบับนี้\n\nยังไม่บันทึกเป็นข้อมูลสุขภาพจริงจนกว่าจะกดยืนยัน',
   token,[
     act('📅 นัดหมาย','กรอกเอง นัดหมาย'),
     act('💊 ยา','กรอกเอง ยา'),
     act('🩺 สุขภาพ','กรอกเอง สุขภาพ'),
     act('📄 เอกสาร','กรอกเอง เอกสาร'),
     pb('❌ ยกเลิก','ยกเลิกรับเข้า '+codeRef),
     act('📁 รูปและเอกสาร','รูปและเอกสาร')
   ]
 )
}

async function promptExistingAppointmentFileClassify(e:any,u:string,k:string,lineUserId:string,token:string,sourceId:string,assetId:string,recordCode:string,linkKind:string,appointmentId:string=''){
 const prior=await getState(u,k,lineUserId);
 const same=prior?.state_key==='appointment_existing_file_classify'&&String(prior?.state_data?.record_code||'')===String(recordCode);
 const pending:any[]=same&&Array.isArray(prior?.state_data?.pending_files)?[...prior.state_data.pending_files]:[];
 if(!pending.some((x:any)=>String(x?.asset_id||'')===String(assetId)))pending.push({source_id:sourceId,asset_id:assetId});
 await state(u,k,lineUserId,'appointment_existing_file_classify',{
  source_id:sourceId,asset_id:assetId,record_code:recordCode,link_kind:linkKind,
  appointment_id:appointmentId||String(prior?.state_data?.appointment_id||''),
  pending_files:pending
 });
 const n=pending.length;
 let w:any=null;try{w=one(await rpc(u,k,'phms_line_appointment_workspace',{p_line_user_id:lineUserId,p_record_code:recordCode}))}catch{}
 const x=w?.item||{};
 const who=String(w?.person_name||'ผู้ใช้');
 const draft=[
  '📎 รูป/เอกสารของนัด',
  '',
  '👤 นัดของ: '+who,
  '📌 นัดเพื่อ: '+String(x?.title||'นัดหมาย'),
  '📆 วันนัด: '+appointmentDateOnlyLabel(x?.appointment_at),
  '🕐 เวลา: '+appointmentTimeOnlyLabel(x?.appointment_at),
  ...(x?.hospital_name?['🏥 รพ./คลินิก: '+phmsHospitalShortLabel(x.hospital_name)]:[]),
  '',
  '🖼️ รับรูป/ไฟล์แล้ว '+String(n)+' รายการ',
  '',
  'เลือกประเภทเอกสารจากเนื้อหาหลักของไฟล์:',
  '📅 ใบนัด — ใบนัดหรือรายละเอียดวันพบแพทย์',
  '🧪 ผลตรวจ — Lab, X-ray, CT, MRI, pathology หรือผลตรวจอื่น',
  '💳 ค่าใช้จ่าย / การชำระเงิน — ใบเสร็จ ใบแจ้งหนี้ สรุปค่าใช้จ่าย หรือหลักฐานชำระเงิน',
  '📄 ใบส่งตัว / เอกสารสิทธิ์ — ใบส่งตัว ประกัน สิทธิรักษา หรือเอกสารรับรองสิทธิ์',
  '📝 เอกสารจากแพทย์ / โรงพยาบาล — ใบรับรองแพทย์ ใบสรุปการรักษา ใบสั่งยา หรือเอกสารจากสถานพยาบาล',
  '📎 เอกสารอื่น / เอกสารที่ต้องเตรียม — แบบฟอร์ม สำเนา หนังสือยินยอม หรือเอกสารอื่น',
  '',
  'ถ้าไม่แน่ใจ เลือก “อื่น / ต้องเตรียม” แล้วแก้ภายหลังได้',
  'ส่งรูปเพิ่มต่อได้เลยก่อนเลือกประเภท'
 ].join('\n');
 await replyOrPush(e.replyToken,lineUserId,draft,token,[
   pb('📅 ใบนัด','จัดประเภทไฟล์นัดเดิม ใบนัด'),
   pb('🧪 ผลตรวจ','จัดประเภทไฟล์นัดเดิม ผลตรวจ'),
   pb('💳 ค่าใช้จ่าย/ชำระเงิน','จัดประเภทไฟล์นัดเดิม ค่าใช้จ่าย'),
   pb('📄 ส่งตัว/สิทธิ์','จัดประเภทไฟล์นัดเดิม ส่งตัวสิทธิ์'),
   pb('📝 เอกสารแพทย์/รพ.','จัดประเภทไฟล์นัดเดิม เอกสารแพทย์'),
   pb('📎 อื่น/ต้องเตรียม','จัดประเภทไฟล์นัดเดิม อื่น'),
   pb('❌ ยกเลิก','ดูนัด '+recordCode)
 ])
}
async function promptMedicalRecordRequestAttachmentMetadata(e:any,u:string,k:string,lineUserId:string,token:string,assetId:string,sourceId:string,requestCode:string,itemCode:string){
 let w:any=null,it:any=null;
 try{
  w=one(await rpc(u,k,'phms_line_medical_record_request_workspace',{p_line_user_id:lineUserId,p_request_code:requestCode}));
  const items=Array.isArray(w?.items)?w.items:[];
  it=items.find((x:any)=>String(x?.code||'')===String(itemCode||''))||items.find((x:any)=>x?.status==='requested')||null
 }catch(err){console.error('medical_record_request_workspace_for_upload',String(err))}
 const title=String(it?.title||''),type=String(it?.document_type||'');
 const d1=String(it?.service_period_start||''),d2=String(it?.service_period_end||'');
 await state(u,k,lineUserId,'medical_record_request_attachment_metadata',{
  request_code:requestCode,item_code:String(it?.code||itemCode||''),asset_id:assetId,source_id:sourceId,
  default_title:title,default_document_type:type,default_service_period_start:d1,default_service_period_end:d2
 });
 const text='📄 รับไฟล์แล้ว — ระบุวันที่ให้เอกสารนี้\n\n'+
  'ชื่อเอกสาร: '+title+'\n'+
  'ประเภทเอกสาร: '+type+'\n'+
  'วันที่เอกสาร: \n'+
  'ช่วงรักษาเริ่ม: '+d1+'\n'+
  'ช่วงรักษาสิ้นสุด: '+d2+'\n'+
  'วันที่ได้รับจริง: \n\n'+
  'วันที่เอกสาร = วันที่บนเอกสาร\n'+
  'ช่วงรักษา = วันที่ที่เนื้อหาในเอกสารอ้างถึง\n'+
  'วันที่ได้รับจริง = วันที่เราได้ไฟล์/กระดาษมา\n\n'+
  'กรอกเฉพาะที่รู้ ช่องที่ไม่รู้ใส่ - ได้';
 await replyOrPush(e.replyToken,lineUserId,text,token,[pb('❌ ยกเลิก','ดูคำขอเวชระเบียน '+requestCode)])
}
async function handleLineMedia(e:any,u:string,k:string,lineUserId:string,token:string){
 const m=e?.message??{},type=String(m.type??'');
 const conv=await getState(u,k,lineUserId);
 const appointmentIntent=conv?.state_key==='crud_add_appointment_image'||conv?.state_key==='crud_add_appointment';
 const appointmentFileAttach=['crud_appointment_attach','appointment_existing_file_classify'].includes(String(conv?.state_key||''));
 const financeAttach=['appointment_finance_attach','appointment_finance_file_classify'].includes(String(conv?.state_key||''));
 const previsitSymptomAttach=String(conv?.state_key||'')==='appointment_previsit_symptom_attach';
 const appointmentAttach=appointmentFileAttach||financeAttach||previsitSymptomAttach;
 const appointmentAttachId=appointmentAttach?String(conv?.state_data?.appointment_id||''):'';
 const previsitSymptomCode=previsitSymptomAttach?String(conv?.state_data?.symptom_code||''):'';
 const preparationTaskEvidenceCode=appointmentFileAttach?String(conv?.state_data?.preparation_task_code||'').trim():'';
 const recordRequestAttach=String(conv?.state_key||'')==='medical_record_request_attach';
 const recordRequestCode=recordRequestAttach?String(conv?.state_data?.request_code||'').trim():'';
 const recordRequestItemCode=recordRequestAttach?String(conv?.state_data?.item_code||'').trim():'';
 if(type!=='image'&&type!=='file'){
   await reply(e.replyToken,'📎 ตอนนี้อิ่มอุ่นรับเก็บเฉพาะรูปภาพและไฟล์ PDF ก่อน',token,[act('🏡 หน้าเริ่มต้น','กลับหน้าเริ่มต้น')]);
   return
 }
 const identity=await iden(u,k,lineUserId);
 if(!identity?.user_id){await reply(e.replyToken,'🔐 ก่อนเก็บรูปหรือเอกสาร เชื่อมบัญชีอิ่มอุ่นก่อน',token,[act('🔐 เชื่อมบัญชี','เชื่อมบัญชีอิ่มอุ่น')]);return}
 if(conv?.state_key==='person_photo_upload'){
  if(type!=='image'){await reply(e.replyToken,'📷 ช่วยส่งเป็นรูปภาพ JPEG, PNG หรือ WebP',token,[pb('❌ ยกเลิก','รายละเอียดบุคคล')]);return}
  const cr=await fetch('https://api-data.line.me/v2/bot/message/'+encodeURIComponent(String(m.id))+'/content',{headers:{Authorization:'Bearer '+token}});
  if(!cr.ok)throw new Error('line_person_photo_fetch_failed:'+cr.status);
  const bytes=new Uint8Array(await cr.arrayBuffer());
  if(!bytes.length)throw new Error('empty_file');
  if(bytes.length>MEDIA_MAX_BYTES)throw new Error('file_too_large');
  const detected=mediaType(bytes);
  if(!detected||detected.mime==='application/pdf')throw new Error('unsupported_media_type');
  const checksum=await sha256(bytes);
  const objectName='people/'+crypto.randomUUID()+'.'+detected.ext;
  await uploadTemp(u,k,objectName,bytes,detected.mime,'phms-person-photos');
  await rpc(u,k,'phms_register_line_person_photo',{p_line_user_id:lineUserId,p_object_name:objectName,p_mime_type:detected.mime,p_byte_size:bytes.length,p_checksum_sha256:checksum,p_share_with_family:conv?.state_data?.share_with_family===true});
  await clear(u,k,lineUserId);
  await replyPersonDashboard(e.replyToken,u,k,lineUserId,token,'✅ เพิ่มรูปบุคคลแล้ว');
  return
 }
 if(type==='image'&&m?.contentProvider?.type==='external'){await reply(e.replyToken,'⚠️ ช่วยส่งรูปเข้าห้องแชตโดยตรงอีกครั้ง',token);return}
 const declaredSize=Number(m?.fileSize??0);
 if(declaredSize>MEDIA_MAX_BYTES){await reply(e.replyToken,'⚠️ ไฟล์ใหญ่เกิน 10 MB ช่วยเลือกไฟล์ที่เล็กกว่านี้',token);return}

 const sourceKind=type==='image'?'image':'document';
 const originalName=cleanFilename(m?.fileName);
 const start=one(await rpc(u,k,'phms_start_line_medical_intake',{
   p_line_user_id:lineUserId,p_line_message_id:String(m.id),p_source_kind:sourceKind,
   p_source_metadata:{
     line_message_type:type,original_filename:originalName,declared_file_size:declaredSize||null,
     content_provider:m?.contentProvider?.type??'line',ingestion_stage:'received',
     intent_resource:recordRequestAttach?'health':(appointmentIntent?'appointment':(appointmentAttach?'document':null)),
     intent_mode:recordRequestAttach?'medical_record_request':(appointmentIntent?'manual_from_image':(previsitSymptomAttach?'appointment_previsit_symptom':(financeAttach?'appointment_finance_evidence':(appointmentFileAttach?'appointment_attachment':null)))),
     intent_started_from:recordRequestAttach?'medical_record_request_attach':(appointmentIntent?'crud_add_appointment':(previsitSymptomAttach?'appointment_previsit_symptom_attach':(financeAttach?'appointment_finance_attach':(appointmentFileAttach?'crud_appointment_attach':null)))),
     automatic_extraction:false,manual_entry_required:true,
     appointment_id:appointmentAttach?appointmentAttachId:null,
     appointment_link_kind:previsitSymptomAttach?'other':(financeAttach?'payment_other':(appointmentFileAttach?String(conv?.state_data?.link_kind||'result'):null)),
     medical_record_request_code:recordRequestAttach?recordRequestCode:null,
     medical_record_request_item_code:recordRequestAttach?recordRequestItemCode:null
   }
 }));

 if(start?.storage_asset_id){
   if(recordRequestAttach){
     await promptMedicalRecordRequestAttachmentMetadata(
       e,u,k,lineUserId,token,
       String(start.storage_asset_id),String(start.source_id||''),
       recordRequestCode,recordRequestItemCode
     );
     return
   }
   if(previsitSymptomAttach){
     const linked=one(await rpc(u,k,'phms_line_appointment_link_existing_asset',{
       p_line_user_id:lineUserId,
       p_record_code:String(conv?.state_data?.record_code||''),
       p_storage_asset_id:String(start.storage_asset_id),
       p_link_kind:'other',
       p_usage_relation:'supporting',
       p_note:'อาการก่อนนัด #'+previsitSymptomCode
     }))||{};
     if(linked?.link_id)await rpc(u,k,'phms_line_appointment_previsit_symptom_link_document',{
       p_line_user_id:lineUserId,
       p_symptom_code:previsitSymptomCode,
       p_appointment_document_link_id:String(linked.link_id)
     });
     await replyOrPush(e.replyToken,lineUserId,'✅ เพิ่มรูปอาการก่อนนัดแล้ว\n\nส่งรูปต่อได้ หรือกด “ครบแล้ว”',token,[
       {type:'action',action:{type:'camera',label:'📷 ถ่ายเพิ่ม'}},
       {type:'action',action:{type:'cameraRoll',label:'🖼️ เลือกรูปเพิ่ม'}},
       pb('✅ ครบแล้ว','จบแนบรูปอาการก่อนนัด '+String(conv?.state_data?.record_code||''))
     ]);
     return
   }
   if(preparationTaskEvidenceCode){
     const rr=one(await rpc(u,k,'phms_line_appointment_attach_task_asset',{
       p_line_user_id:lineUserId,
       p_task_code:preparationTaskEvidenceCode,
       p_storage_asset_id:String(start.storage_asset_id),
       p_note:null
     }));
     await state(u,k,lineUserId,'crud_appointment_attach',{
       record_code:String(rr?.appointment_code||conv?.state_data?.record_code||''),
       appointment_id:appointmentAttachId,
       link_kind:'preparation',
       preparation_task_code:preparationTaskEvidenceCode
     });
     await replyOrPush(
       e.replyToken,lineUserId,
       '✅ เพิ่มรูป/เอกสารเป็นหลักฐานแล้ว\n\nส่งรูปต่อได้เลย หรือเลือกจากรูปเดิมเพิ่ม • รูปที่เลือกแล้วจะไม่ขึ้นซ้ำในรายการ',
       token,[
        pb('🖼️ เลือกจากรูปเดิม','หลักฐานงานเตรียม '+preparationTaskEvidenceCode+' 0'),
        pb('☑️ ทำรายการเสร็จ','ทำแล้ว '+preparationTaskEvidenceCode),
        pb('✅ ครบแล้ว','สิ่งที่ต้องทำก่อนนัด '+String(rr?.appointment_code||conv?.state_data?.record_code||''))
       ]
     );
     return
   }
   if(financeAttach){
     await promptAppointmentFinanceFileClassify(e,u,k,lineUserId,token,String(start.source_id||''),String(start.storage_asset_id||''),String(conv?.state_data?.record_code||''),appointmentAttachId);
     return
   }
   if(appointmentFileAttach){
     await promptExistingAppointmentFileClassify(e,u,k,lineUserId,token,String(start.source_id||''),String(start.storage_asset_id||''),String(conv?.state_data?.record_code||''),String(conv?.state_data?.link_kind||'result'),appointmentAttachId);
     return
   }
   await promptManualForStoredSource(e,u,k,lineUserId,token,String(start.source_id),appointmentIntent);
   return
 }

 const cr=await fetch('https://api-data.line.me/v2/bot/message/'+encodeURIComponent(String(m.id))+'/content',{headers:{Authorization:'Bearer '+token}});
 if(!cr.ok)throw new Error('line_content_fetch_failed:'+cr.status+':'+await cr.text());
 const bytes=new Uint8Array(await cr.arrayBuffer());
 if(!bytes.length)throw new Error('empty_file');
 if(bytes.length>MEDIA_MAX_BYTES)throw new Error('file_too_large');
 const detected=mediaType(bytes);
 if(!detected)throw new Error('unsupported_media_type');

 const checksum=await sha256(bytes);
 const objectName='intake/'+String(start.source_id)+'.'+detected.ext;
 await uploadTemp(u,k,objectName,bytes,detected.mime);
 const attached=one(await rpc(u,k,'phms_attach_line_intake_storage',{
   p_source_id:start.source_id,p_bucket_id:'phms-intake-temp',p_object_name:objectName,
   p_mime_type:detected.mime,p_byte_size:bytes.length,p_checksum_sha256:checksum,
   p_original_filename:originalName,
   p_metadata:{
     line_message_type:type,line_content_type_header:cr.headers.get('content-type'),
     ingestion_stage:'stored',automatic_extraction:false,manual_entry_required:true,
     appointment_id:appointmentAttach?appointmentAttachId:null,
     appointment_link_kind:previsitSymptomAttach?'other':(financeAttach?'payment_other':(appointmentFileAttach?String(conv?.state_data?.link_kind||'result'):null)),
     medical_record_request_code:recordRequestAttach?recordRequestCode:null,
     medical_record_request_item_code:recordRequestAttach?recordRequestItemCode:null
   }
 }));

 const effectiveSourceId=String(attached?.source_id??start.source_id);
 if(attached?.discard_uploaded_object){
   try{await removeTempObject(u,k,String(attached.discard_object_name||objectName))}catch(err){console.error('duplicate_temp_cleanup',String(err))}
 }

 if(recordRequestAttach){
   const requestAssetId=String(attached?.storage_asset_id||start?.storage_asset_id||'');
   if(!requestAssetId)throw new Error('medical_record_request_storage_asset_missing');
   await promptMedicalRecordRequestAttachmentMetadata(
     e,u,k,lineUserId,token,
     requestAssetId,effectiveSourceId,
     recordRequestCode,recordRequestItemCode
   );
   return
 }
 if(previsitSymptomAttach){
   const symptomAssetId=String(attached?.storage_asset_id||start?.storage_asset_id||'');
   if(!symptomAssetId)throw new Error('previsit_symptom_storage_asset_missing');
   const linked=one(await rpc(u,k,'phms_line_appointment_link_existing_asset',{
     p_line_user_id:lineUserId,
     p_record_code:String(conv?.state_data?.record_code||''),
     p_storage_asset_id:symptomAssetId,
     p_link_kind:'other',
     p_usage_relation:'supporting',
     p_note:'อาการก่อนนัด #'+previsitSymptomCode
   }))||{};
   if(linked?.link_id)await rpc(u,k,'phms_line_appointment_previsit_symptom_link_document',{
     p_line_user_id:lineUserId,
     p_symptom_code:previsitSymptomCode,
     p_appointment_document_link_id:String(linked.link_id)
   });
   await replyOrPush(e.replyToken,lineUserId,'✅ เพิ่มรูปอาการก่อนนัดแล้ว\n\nส่งรูปต่อได้ หรือกด “ครบแล้ว”',token,[
     {type:'action',action:{type:'camera',label:'📷 ถ่ายเพิ่ม'}},
     {type:'action',action:{type:'cameraRoll',label:'🖼️ เลือกรูปเพิ่ม'}},
     pb('✅ ครบแล้ว','จบแนบรูปอาการก่อนนัด '+String(conv?.state_data?.record_code||''))
   ]);
   return
 }
 if(preparationTaskEvidenceCode){
   const evidenceAssetId=String(attached?.storage_asset_id||start?.storage_asset_id||'');
   if(!evidenceAssetId)throw new Error('task_evidence_storage_asset_missing');
   const rr=one(await rpc(u,k,'phms_line_appointment_attach_task_asset',{
     p_line_user_id:lineUserId,
     p_task_code:preparationTaskEvidenceCode,
     p_storage_asset_id:evidenceAssetId,
     p_note:null
   }));
   await state(u,k,lineUserId,'crud_appointment_attach',{
     record_code:String(rr?.appointment_code||conv?.state_data?.record_code||''),
     appointment_id:appointmentAttachId,
     link_kind:'preparation',
     preparation_task_code:preparationTaskEvidenceCode
   });
   await replyOrPush(
     e.replyToken,lineUserId,
     '✅ เพิ่มรูป/เอกสารเป็นหลักฐานแล้ว\n\nส่งรูปต่อได้เลย หรือเลือกจากรูปเดิมเพิ่ม • รูปที่เลือกแล้วจะไม่ขึ้นซ้ำในรายการ',
     token,[
      pb('🖼️ เลือกจากรูปเดิม','หลักฐานงานเตรียม '+preparationTaskEvidenceCode+' 0'),
      pb('☑️ ทำรายการเสร็จ','ทำแล้ว '+preparationTaskEvidenceCode),
      pb('✅ ครบแล้ว','สิ่งที่ต้องทำก่อนนัด '+String(rr?.appointment_code||conv?.state_data?.record_code||''))
     ]
   );
   return
 }
 if(financeAttach){
   await promptAppointmentFinanceFileClassify(e,u,k,lineUserId,token,effectiveSourceId,String(attached?.storage_asset_id||start?.storage_asset_id||''),String(conv?.state_data?.record_code||''),appointmentAttachId);
   return
 }
 if(appointmentFileAttach){
   await promptExistingAppointmentFileClassify(e,u,k,lineUserId,token,effectiveSourceId,String(attached?.storage_asset_id||start?.storage_asset_id||''),String(conv?.state_data?.record_code||''),String(conv?.state_data?.link_kind||'result'),appointmentAttachId);
   return
 }

 await promptManualForStoredSource(e,u,k,lineUserId,token,effectiveSourceId,appointmentIntent)
}



// PHMS_GROUP_NO_BACK_BUTTON_V1: remove navigation-back actions only in LINE groups.
function phmsRemoveGroupBackButtons(m:any){
 const walk=(n:any):void=>{
  if(!n||typeof n!=='object')return;
  if(Array.isArray(n)){n.forEach(walk);return}
  if(n.type==='box'&&Array.isArray(n.contents)){
   n.contents=n.contents.filter((v:any)=>!(v?.type==='button'&&(/ย้อนกลับ|กลับหน้า|กลับไป|กลับเมนู|หน้าก่อน/.test(String(v?.action?.label||''))||/^↩️ *นัดหมาย$/.test(String(v?.action?.label||'')))));
  }
  if(n.quickReply?.items) n.quickReply.items=n.quickReply.items.filter((v:any)=>!/(?:ย้อนกลับ|กลับหน้า|กลับไป|หน้าก่อน)/.test(String(v?.action?.label||'')));
  for(const key of ['contents','header','body','footer','hero','template','columns','items'])if(n[key])walk(n[key]);
 };
 walk(m);return m;
}
async function phmsGroupReplyMessages(rt:string,t:string,messages:any[]){
 return replyMessages(rt,t,messages.map(phmsRemoveGroupBackButtons));
}
async function phmsPushMessages(to:string,t:string,messages:any[]){
 const r=await phmsChargeableLineFetch('https://api.line.me/v2/bot/message/push',{
  method:'POST',
  headers:{Authorization:'Bearer '+t,'content-type':'application/json'},
  body:JSON.stringify({to,messages:messages.slice(0,5).map(m=>String(to).startsWith('C')?phmsRemoveGroupBackButtons(phmsDualActionMessage(m)):phmsDualActionMessage(m))})
 });
 if(!r.ok)throw new Error('line_push_messages_failed:'+r.status+':'+(await r.text()).slice(0,300));
 if(r.status===202){
  const d=await r.clone().json().catch(()=>null);
  if(d?.suppressed===true)return false
 }
 return true
}


