function phmsGroupReadyCarouselFlex(s:any){
 const people=Array.isArray(s?.people)?s.people:[];
 const families=Array.isArray(s?.families)?s.families:[];
 const multi=families.length>1;
 const enabled=(p:any,r:string)=>p?.[r]===true||(Array.isArray(p?.resources)&&p.resources.includes(r));
 const pName=(p:any)=>{
  const n=String(p?.display_name||p?.nickname||'ไม่ระบุชื่อ');
  return multi?n+' ('+String(p?.family_name||'บ้าน')+')':n
 };
 const bubble=(title:string,subtitle:string,body:any[])=>({
  type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:'#EAF4FF',paddingAll:'18px',contents:[
   {type:'text',text:title,weight:'bold',size:'xl',color:'#2457A7',wrap:true},
   {type:'text',text:subtitle,size:'sm',color:'#667085',margin:'sm',wrap:true}
  ]},
  body:{type:'box',layout:'vertical',paddingAll:'18px',spacing:'md',contents:body}
 });
 const familyText=families.length
  ?families.map((x:any)=>String(x?.family_name||'ครอบครัว')).join(' • ')
  :String(s?.family_name||'ครอบครัว');
 const cards:any[]=[
  bubble('💙 อิ่มอุ่นพร้อมใช้งานแล้ว','ถามได้เลย ไม่ต้องกดเมนู',[
   {type:'text',text:'👥 '+String(s?.channel_name||'LINE กลุ่ม'),size:'sm',weight:'bold',wrap:true},
   ...(familyText?[{type:'text',text:'🏠 '+familyText,size:'sm',color:'#475467',wrap:true}]:[]),
   {type:'box',layout:'vertical',backgroundColor:'#F7FBFF',cornerRadius:'12px',paddingAll:'12px',contents:[
    {type:'text',text:'เรียก “อิ่มอุ่น” ก่อนถามทุกครั้ง',size:'sm',weight:'bold',color:'#2457A7',wrap:true},
    {type:'text',text:'เช่น “อิ่มอุ่น ยายมีนัดวันไหน”',size:'sm',color:'#475467',margin:'sm',wrap:true}
   ]},
   {type:'text',text:'เลื่อนไปด้านข้างเพื่อดูตัวอย่างเพิ่มเติม 👉',size:'xs',color:'#667085',wrap:true}
  ])
 ];
 const examples=[
  ['appointments','📅 เรื่องนัด',(n:string)=>'อิ่มอุ่น '+n+' มีนัดวันไหน'],
  ['medications','💊 เรื่องยา',(n:string)=>'อิ่มอุ่น '+n+' มียาอะไรบ้าง'],
  ['health_data','🩺 เรื่องสุขภาพ',(n:string)=>'อิ่มอุ่น สุขภาพของ '+n+' ล่าสุดเป็นยังไง']
 ] as any[];
 for(const [r,title,make] of examples){
  const xs=people.filter((p:any)=>enabled(p,r)).map(pName).filter(Boolean);
  if(!xs.length)continue;
  cards.push(bubble(String(title),'กลุ่มนี้ถามได้',[
   {type:'text',text:xs.join(' • '),weight:'bold',size:'md',color:'#2457A7',wrap:true},
   {type:'text',text:'ตัวอย่าง\n“'+make(xs[0])+'”',size:'sm',color:'#475467',wrap:true}
  ]))
 }
 cards.push(bubble('🔎 อยากดูรายละเอียด','เปิดต่อในแชตส่วนตัว',[
  {type:'text',text:'เวลามีการ์ดสรุป กด “ดูรายละเอียด” เพื่อเปิดข้อมูลต่อในแชตอิ่มอุ่นส่วนตัว',size:'sm',wrap:true},
  {type:'text',text:'อิ่มอุ่นจะตรวจการเชื่อมบัญชีและสิทธิ์ของคนนั้นก่อนเปิดรายละเอียด',size:'xs',color:'#667085',wrap:true}
 ]));
 return {type:'flex',altText:'💙 อิ่มอุ่นพร้อมใช้งานแล้ว',contents:{type:'carousel',contents:cards.slice(0,12)}}
}

