async function phmsShowFamilyLineGroups(
 rt:string,u:string,k:string,lineUserId:string,t:string,familyCode:string,note=''
){
 try{
  const w=one(await rpc(u,k,'phms_line_family_group_workspace',{
   p_line_user_id:lineUserId,p_family_code:familyCode
  }));
  const groups=Array.isArray(w?.groups)?w.groups:[];
  const rows=groups.slice(0,8).map((g:any)=>{
   const ready=g?.setup_completed===true&&g?.can_query_bot===true;
   const a=Number(g?.appointment_people||0);
   const m=Number(g?.medication_people||0);
   const h=Number(g?.health_people||0);
   return '• 👥 '+String(g?.channel_name||'LINE กลุ่ม')+
    '\n  '+(ready?'✅ ดู/ถามได้ตามสิทธิ์':'⏳ ยังตั้งค่าข้อมูลไม่เสร็จ')+
    ' • 🔔 '+(g?.can_receive_notifications===false?'ปิด':'รับแจ้งเตือนได้')+
    '\n  📅 '+a+' คน • 💊 '+m+' คน • 🩺 '+h+' คน'
  }).join('\n\n');
  const q=groups.slice(0,8).map((g:any)=>pb(
   phmsShortLabel('⚙️ ',g?.channel_name||'LINE กลุ่ม'),
   'ตั้งค่ากลุ่มส่วนตัว '+String(g?.line_group_id||'')
  ));
  q.push(pb('🔗 สิทธิ์เชิญ/ขอเชื่อม','สิทธิ์ขอเชื่อมกลุ่ม '+String(w?.family_code||familyCode)));
  q.push(pb('↩️ กลับครอบครัว','ครอบครัว'));
  await reply(
   rt,
   (note?note+'\n\n':'')+
   '👥 LINE กลุ่มของบ้าน\n\n'+
   '🏠 '+String(w?.family_name||'ครอบครัว')+'\n\n'+
   (rows||'ยังไม่มี LINE กลุ่มที่เชื่อมกับบ้านนี้')+
   '\n\nกลุ่มมีสิทธิ์แค่ 👁️ ดู/ถามรายละเอียดตามที่เปิดไว้ และ 🔔 รับแจ้งเตือน\nเพิ่ม • แก้ไข • ลบข้อมูล ต้องทำในแชตส่วนตัว',
   t,q
  )
 }catch(err){
  console.error('family_line_group_workspace',String(err));
  await reply(rt,'🔒 หน้านี้ให้เจ้าบ้านหรือผู้ช่วยดูแลครอบครัวเป็นคนจัดการ',t,[pb('↩️ ครอบครัว','ครอบครัว')])
 }
}

async function phmsShowGroupRequestPermissions(rt:string,u:string,k:string,lineUserId:string,t:string,familyCode:string,note=''){
 try{
  const w=one(await rpc(u,k,'phms_line_group_request_permission_workspace',{
   p_line_user_id:lineUserId,p_family_code:familyCode
  }));
  const members=Array.isArray(w?.members)?w.members:[];
  const rows=members.slice(0,10).map((x:any)=>
   '• '+String(x?.display_name||'สมาชิก')+' — '+
   (x?.is_manager
    ?'🔑 Owner/Admin • เชื่อมเองได้'
    :x?.can_request
      ?'✅ อนุญาตให้ส่งคำขอเชื่อม'
      :'○ ยังไม่อนุญาต')
  ).join('\n');
  const q=members.filter((x:any)=>x?.is_manager!==true).slice(0,9).map((x:any)=>pb(
   phmsShortLabel(x?.can_request?'✅ ':'○ ',x?.display_name||'สมาชิก'),
   'สลับสิทธิ์ขอกลุ่ม '+String(w?.family_code||familyCode)+' '+String(x?.user_code||'')
  ));
  q.push(pb('↩️ กลับครอบครัว','ครอบครัว'));
  await reply(rt,(note?note+'\n\n':'')+
   '🔗 สิทธิ์เชิญ/ขอเชื่อม LINE กลุ่ม\n\n'+
   '🏠 '+String(w?.family_name||'ครอบครัว')+'\n\n'+
   'หน้านี้คือสิทธิ์ของ “บัญชีสมาชิกครอบครัว” ว่าใครเชิญอิ่มอุ่นเข้ากลุ่มแล้วส่งคำขอเชื่อมบ้านนี้ได้\n'+
   'ไม่ใช่รายชื่อบุคคลที่ LINE กลุ่มดูข้อมูลสุขภาพได้\n\n'+
   (rows||'ยังไม่มีสมาชิกบัญชี')+
   '\n\n🔑 Owner/Admin เชื่อมเองได้เสมอ\n✅ สมาชิกที่อนุญาตส่งคำขอได้ แล้ว Owner/Admin ค่อยอนุมัติในแชตส่วนตัว\n○ ยังไม่อนุญาต\n\nOwner/Admin ไม่จำเป็นต้องอยู่ใน LINE กลุ่มนั้น',
   t,q
  )
 }catch(err){
  console.error('group_request_permission_workspace',String(err));
  await reply(rt,'🔒 หน้านี้ให้เจ้าบ้านหรือผู้ช่วยดูแลครอบครัวเป็นคนตั้งค่า',t,[pb('↩️ ครอบครัว','ครอบครัว')])
 }
}


function phmsGroupRequestStatusFlex(x:any){
 const status=String(x?.status||'');
 const label=status==='pending_review'?'⏳ รอเจ้าบ้าน/ผู้ช่วยดูแลครอบครัวตรวจสอบ':
  status==='approved_setup_pending'?'⚙️ อนุมัติแล้ว • รอตั้งค่ากลุ่ม':
  status==='ready'?'💙 พร้อมใช้งานแล้ว':
  status==='rejected'?'❌ ไม่ได้รับอนุมัติ':'ℹ️ '+status;
 const body:any[]=[
  {type:'text',text:'👥 '+String(x?.group_name||'LINE กลุ่ม'),size:'sm',weight:'bold',wrap:true},
  {type:'text',text:'🏠 '+String(x?.family_name||'ครอบครัว'),size:'sm',color:'#475467',wrap:true},
  {type:'box',layout:'vertical',backgroundColor:'#FFF9ED',cornerRadius:'12px',paddingAll:'12px',margin:'md',contents:[
   {type:'text',text:label,size:'sm',weight:'bold',color:status==='ready'?'#2F6B4F':'#8A5A00',wrap:true},
   ...(status==='pending_review'||status==='approved_setup_pending'
    ?[{type:'text',text:'รอมาแล้ว '+String(Number(x?.waiting_days||0))+' วัน',size:'xs',color:'#667085',margin:'sm',wrap:true}]
    :[])
  ]},
  ...(x?.requested_at?[{type:'text',text:'ส่งคำขอ: '+phmsGroupThaiDateTime(x.requested_at),size:'xs',color:'#667085',wrap:true}]:[]),
  ...(x?.reviewed_at?[{type:'text',text:'ตรวจคำขอ: '+phmsGroupThaiDateTime(x.reviewed_at),size:'xs',color:'#667085',wrap:true}]:[]),
  ...(x?.setup_completed_at?[{type:'text',text:'พร้อมใช้: '+phmsGroupThaiDateTime(x.setup_completed_at),size:'xs',color:'#667085',wrap:true}]:[]),
  ...(status==='rejected'&&x?.review_note?[{type:'text',text:'เหตุผล: '+String(x.review_note),size:'sm',color:'#475467',wrap:true,margin:'md'}]:[])
 ];
 if(x?.last_reminded_at&&!x?.can_remind&&(status==='pending_review'||status==='approved_setup_pending')){
  body.push({type:'text',text:'🔔 ส่งแจ้งเตือนซ้ำแล้ว '+phmsGroupThaiDateTime(x.last_reminded_at),size:'xs',color:'#667085',wrap:true,margin:'md'});
  if(x?.next_reminder_at)body.push({type:'text',text:'เตือนได้อีกครั้ง '+phmsGroupThaiDateTime(x.next_reminder_at),size:'xs',color:'#667085',wrap:true})
 }
 const footer:any[]=[
  {type:'button',style:'secondary',action:{type:'postback',label:'🔄 ตรวจสอบสถานะ',data:'ติดตามคำขอเชื่อมกลุ่ม '+String(x?.request_code||'')}}
 ];
 if(x?.can_remind===true){
  footer.unshift({type:'button',style:'primary',color:'#3E73C8',action:{
   type:'postback',label:'🔔 เตือนเจ้าบ้าน/ผู้ช่วยดูแลครอบครัวอีกครั้ง',data:'เตือนคำขอเชื่อมกลุ่ม '+String(x?.request_code||'')
  }})
 }
 return {type:'flex',altText:'🔎 สถานะคำขอเชื่อม LINE กลุ่ม',contents:{type:'bubble',size:'kilo',
  header:{type:'box',layout:'vertical',backgroundColor:'#EAF4FF',paddingAll:'18px',contents:[
   {type:'text',text:'🔎 สถานะคำขอ',weight:'bold',size:'xl',color:'#2457A7',wrap:true}
  ]},
  body:{type:'box',layout:'vertical',paddingAll:'18px',spacing:'sm',contents:body},
  footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'14px',contents:footer}
 }}
}
async function phmsShowGroupLinkRequestStatus(rt:string,u:string,k:string,lineUserId:string,t:string,requestCode:string,note=''){
 try{
  const rr=one(await rpc(u,k,'phms_line_group_link_request_status',{p_line_user_id:lineUserId,p_request_code:requestCode}));
  const xs=Array.isArray(rr?.requests)?rr.requests:[];
  if(!xs.length){await reply(rt,'ℹ️ ไม่พบคำขอนี้ หรือคำขอนี้ไม่ใช่ของบัญชีนี้',t);return}
  const messages:any[]=[]; if(note)messages.push({type:'text',text:note});
  messages.push(phmsGroupRequestStatusFlex(xs[0]));
  await replyMessages(rt,t,messages)
 }catch(err){
  console.error('group_link_request_status',String(err));
  await reply(rt,'⚠️ ยังตรวจสถานะคำขอนี้ไม่ได้',t)
 }
}

async function phmsRoutePrivateGroupSetup(
 c:string,rt:string,u:string,k:string,lineUserId:string,t:string,st:any
){

 if(String(st?.state_key||'')==='line_group_reject_reason'){
  const code=String(st?.state_data?.request_code||'');
  if(c==='ยกเลิก'){
   await clear(u,k,lineUserId);
   await reply(rt,'ยกเลิกแล้ว',t);
   return true
  }
  const note=c==='ปฏิเสธโดยไม่ใส่เหตุผล'?null:String(c||'').trim();
  if(code&&note!=='' ){
   try{
    await rpc(u,k,'phms_review_line_group_link_request',{
     p_line_user_id:lineUserId,p_request_code:code,p_decision:'reject',p_review_note:note
    });
    await clear(u,k,lineUserId);
    await reply(rt,'❌ ปฏิเสธคำขอแล้ว'+(note?'\nเหตุผล: '+note:''),t)
   }catch(err){
    console.error('group_link_reject_with_reason',String(err));
    await reply(rt,'⚠️ คำขอนี้อาจถูกจัดการไปแล้ว หรือตอนนี้ยังไม่มีสิทธิ์ปฏิเสธ',t)
   }
   return true
  }
 }
 let auto=c.match(/^ตั้งค่ากลุ่มอัตโนมัติ\s+([A-Za-z0-9_-]{8,80})$/);
 if(auto){
  try{
   const o=one(await rpc(u,k,'phms_line_group_setup_options',{
    p_line_user_id:lineUserId,p_line_group_id:auto[1]
   }));
   await replyMessages(rt,t,[phmsGroupPrivateSetupFlex(o,auto[1])])
  }catch(err){
   console.error('private_group_auto_prompt_open',String(err));
   await reply(rt,'⚠️ ยังเปิดการตั้งค่ากลุ่มนี้ไม่ได้ ลองใหม่อีกครั้งจากเมนูครอบครัว',t)
  }
  return true
 }

 let familyGroups=c.match(/^LINE กลุ่มของบ้าน\s+([0-9a-fA-F-]{8,36})$/);
 if(familyGroups){
  await phmsShowFamilyLineGroups(rt,u,k,lineUserId,t,familyGroups[1]);
  return true
 }

 let confirmGroup=c.match(/^ยืนยันเชื่อมกลุ่มเดิม\s+([A-Za-z0-9_-]{8,80})$/);
 if(confirmGroup){
  try{
   await rpc(u,k,'phms_line_group_reconfirm',{
    p_line_user_id:lineUserId,p_line_group_id:confirmGroup[1]
   });
   await phmsShowPrivateGroupSettings(rt,u,k,lineUserId,confirmGroup[1],t,
    '🔐 ยืนยันการเชื่อมกลุ่มเดิมแล้ว ลองตรวจสอบบ้านและสิทธิ์ที่กลุ่มดูได้ จากนั้นกด “ตั้งค่าเสร็จ” เพื่อเปิดใช้งาน');
  }catch(err){
   console.error('line_group_reconfirm_failed',String(err));
   await reply(rt,'🔒 ยังยืนยันกลุ่มเดิมไม่ได้ ต้องเป็นเจ้าบ้าน/ผู้ช่วยดูแลครอบครัว และบอทต้องกลับเข้ากลุ่มแล้ว',t);
  }
  return true;
 }

 let m=c.match(/^ยกเลิกบ้านจากกลุ่ม\s+([A-Za-z0-9_-]{8,80})\s+([0-9a-fA-F-]{8,36})$/);
 if(m){
  try{
   const rr=one(await rpc(u,k,'phms_line_unlink_group_family',{
    p_line_user_id:lineUserId,
    p_line_group_id:m[1],
    p_family_code:m[2]
   }));
   const o=one(await rpc(u,k,'phms_line_group_setup_options',{
    p_line_user_id:lineUserId,p_line_group_id:m[1]
   }));
   await replyMessages(rt,t,[
    {type:'text',text:
     '✅ เอา “'+String(rr?.removed_family_name||'ครอบครัว')+'” ออกจาก LINE กลุ่มแล้ว\n\n'+
     '👥 LINE กลุ่ม: '+String(rr?.group_name||'LINE กลุ่ม')+
     '\nระบบปิดสิทธิ์ดูและแจ้งเตือนของบ้านนี้ในกลุ่มแล้ว'
    },
    phmsGroupPrivateSetupFlex(o,m[1])
   ])
  }catch(err){
   const msg=String(err);
   console.error('private_group_unlink_family',msg);
   await reply(rt,
    msg.includes('permission_denied')||msg.includes('settings_permission')
     ?'🔒 เอาบ้านนี้ออกจากกลุ่มไม่ได้ ต้องเป็นเจ้าบ้านหรือผู้ช่วยดูแลครอบครัวของบ้านนั้น'
     :msg.includes('not_found')
      ?'ℹ️ บ้านนี้ไม่ได้เชื่อมกับกลุ่มแล้ว ลองเปิดรายการใหม่อีกครั้ง'
      :'⚠️ อิ่มอุ่นยังเอาบ้านออกจากกลุ่มไม่สำเร็จ ลองอีกครั้งนะ',
    t
   )
  }
  return true
 }

 m=c.match(/^เชื่อมกลุ่มตรง\s+([A-Za-z0-9_-]{8,80})\s+([0-9a-fA-F-]{8,36})$/);
 if(m){
  try{
   const gs=await phmsLineGroupSummary(t,m[1]);
   const rr=one(await rpc(u,k,'phms_line_link_group_family',{
    p_line_user_id:lineUserId,p_line_group_id:m[1],p_family_code:m[2],
    p_channel_name:gs.groupName||null,p_picture_url:gs.pictureUrl||null
   }));
   await rpc(u,k,'phms_line_group_begin_setup',{p_line_user_id:lineUserId,p_line_group_id:m[1]});
   await phmsShowPrivateGroupSettings(rt,u,k,lineUserId,m[1],t)
  }catch(err){
   console.error('private_group_direct_link',String(err));
   await reply(rt,'⚠️ ยังเชื่อมกลุ่มนี้ไม่ได้ ต้องเป็นเจ้าบ้านหรือผู้ช่วยดูแลครอบครัวของบ้านที่เลือก',t)
  }
  return true
 }

 m=c.match(/^ขอเชื่อมกลุ่ม\s+([A-Za-z0-9_-]{8,80})\s+([0-9a-fA-F-]{8,36})$/);
 if(m){
  try{
   const rr=one(await rpc(u,k,'phms_line_request_group_link',{
    p_line_user_id:lineUserId,p_line_group_id:m[1],p_family_code:m[2]
   }));
   await phmsShowGroupLinkRequestStatus(rt,u,k,lineUserId,t,String(rr?.request_code||''),
    Number(rr?.reviewer_count||0)>0?'💙 ส่งคำขอแล้ว • เจ้าบ้าน/ผู้ช่วยดูแลครอบครัวจะได้รับคำขอในแชตส่วนตัว':'💙 เก็บคำขอไว้แล้ว')
  }catch(err){
   const msg=String(err);
   console.error('private_group_request_link',msg);
   await reply(rt,
    msg.includes('permission_denied')
      ?'🔒 คนดูแลบ้านปิดสิทธิ์การส่งคำขอเชื่อมกลุ่มของบัญชีนี้ไว้'
      :'⚠️ ยังส่งคำขอเชื่อมกลุ่มไม่ได้ ลองเปิดเมนูใหม่อีกครั้ง',
    t
   )
  }
  return true
 }


 m=c.match(/^ติดตามคำขอเชื่อมกลุ่ม\s+([0-9a-fA-F-]{8,36})$/);
 if(m){await phmsShowGroupLinkRequestStatus(rt,u,k,lineUserId,t,m[1]);return true}

 m=c.match(/^เตือนคำขอเชื่อมกลุ่ม\s+([0-9a-fA-F-]{8,36})$/);
 if(m){
  try{
   const rr=one(await rpc(u,k,'phms_line_group_link_request_remind',{
    p_line_user_id:lineUserId,p_request_code:m[1]
   }));
   await phmsShowGroupLinkRequestStatus(rt,u,k,lineUserId,t,m[1],
    Number(rr?.reviewer_count||0)>0?'🔔 ส่งแจ้งเตือนให้เจ้าบ้าน/ผู้ช่วยดูแลครอบครัวแล้ว':'🔔 บันทึกการติดตามแล้ว แต่ตอนนี้ยังส่ง LINE หาเจ้าบ้าน/ผู้ช่วยดูแลครอบครัวไม่ได้')
  }catch(err){
   const msg=String(err);
   console.error('group_link_request_remind',msg);
   await phmsShowGroupLinkRequestStatus(rt,u,k,lineUserId,t,m[1],
    msg.includes('remind_too_soon')?'🔔 ยังไม่ครบ 3 วัน จึงยังส่งเตือนซ้ำไม่ได้':'⚠️ ยังส่งเตือนคำขอนี้ไม่ได้')
  }
  return true
 }

 m=c.match(/^(?:เริ่มปฏิเสธเชื่อมกลุ่ม|ไม่อนุมัติเชื่อมกลุ่ม)\s+([0-9a-fA-F-]{8,36})$/);
 if(m){
  await state(u,k,lineUserId,'line_group_reject_reason',{request_code:m[1]});
  await reply(rt,'❌ ต้องการปฏิเสธคำขอนี้\n\nพิมพ์เหตุผลที่ต้องการบอกผู้ขอได้เลย หรือเลือกปฏิเสธโดยไม่ใส่เหตุผล',t,[
   pb('ไม่ใส่เหตุผล','ปฏิเสธโดยไม่ใส่เหตุผล'),pb('ยกเลิก','ยกเลิก')
  ]);
  return true
 }

 m=c.match(/^ตั้งคนกลุ่มส่วนตัว\s+([A-Za-z0-9_-]{8,80})\s+([0-9a-fA-F-]{8,36})$/);
 if(m){await phmsShowPrivateGroupPersonScope(rt,u,k,lineUserId,m[1],t,m[2]);return true}

 m=c.match(/^เลือกทุกข้อมูลคนกลุ่มส่วนตัว\s+([A-Za-z0-9_-]{8,80})\s+([0-9a-fA-F-]{8,36})$/);
 if(m){
  try{
   for(const resource of ['appointments','medications','health_data']){
    await rpc(u,k,'phms_line_group_toggle_query_scope',{
     p_line_user_id:lineUserId,p_line_group_id:m[1],p_person_code:m[2],p_resource:resource,p_enabled:true
    })
   }
   const fresh=one(await rpc(u,k,'phms_line_group_settings',{p_line_user_id:lineUserId,p_line_group_id:m[1]}));
   await replyMessages(rt,t,[phmsPrivateGroupPersonScopeFlex(fresh,m[1],m[2])])
  }catch(err){
   console.error('private_group_person_scope_select_all',String(err));
   await reply(rt,'🔒 เลือกข้อมูลไม่ได้ ต้องเป็นเจ้าบ้านหรือผู้ช่วยดูแลครอบครัวของบ้านนั้น',t)
  }
  return true
 }

 m=c.match(/^สลับคนขอบเขตกลุ่มส่วนตัว\s+([A-Za-z0-9_-]{8,80})\s+([0-9a-fA-F-]{8,36})\s+(appointments|medications|health_data)$/);
 if(m){
  try{
   const ss=one(await rpc(u,k,'phms_line_group_settings',{p_line_user_id:lineUserId,p_line_group_id:m[1]}));
   const row=(Array.isArray(ss?.people)?ss.people:[]).find((x:any)=>
    String(x?.person_code||'').toLowerCase().startsWith(String(m?.[2]||'').toLowerCase())
   );
   if(!row)throw new Error('scope_person_not_found');
   const enabled=!(row?.[m[3]]===true);
   await rpc(u,k,'phms_line_group_toggle_query_scope',{
    p_line_user_id:lineUserId,p_line_group_id:m[1],p_person_code:m[2],p_resource:m[3],p_enabled:enabled
   });
   const person=String(row?.display_name||row?.nickname||'บุคคล');
   const resource=phmsGroupResourceLabel(m[3]);
   const fresh=one(await rpc(u,k,'phms_line_group_settings',{p_line_user_id:lineUserId,p_line_group_id:m[1]}));
   if(fresh?.setup_completed===true){
    await state(u,k,lineUserId,'line_group_scope_change_notice',{
     line_group_id:m[1],person_name:person,resource:m[3],resource_label:resource,enabled
    });
    await replyMessages(rt,t,[
     {type:'text',text:(enabled?'✅ เพิ่ม ':'➖ เอาออก ')+resource+'ของ '+person+' แล้ว',quickReply:{items:[
      pb('📢 แจ้งในกลุ่ม','แจ้งการเปลี่ยนขอบเขตกลุ่ม '+m[1]),
      pb('🔕 ไม่ต้องแจ้ง','ไม่แจ้งการเปลี่ยนขอบเขตกลุ่ม '+m[1])
     ]}},
     phmsPrivateGroupPersonScopeFlex(fresh,m[1],m[2])
    ])
   }else{
    await replyMessages(rt,t,[phmsPrivateGroupPersonScopeFlex(fresh,m[1],m[2])])
   }
  }catch(err){
   console.error('private_group_person_scope_toggle',String(err));
   await reply(rt,'🔒 เปลี่ยนขอบเขตนี้ไม่ได้ ต้องเป็นเจ้าบ้านหรือผู้ช่วยดูแลครอบครัวของบ้านนั้น',t)
  }
  return true
 }

 m=c.match(/^แจ้งการเปลี่ยนขอบเขตกลุ่ม\s+([A-Za-z0-9_-]{8,80})$/);
 if(m){
  const d=String(st?.state_key||'')==='line_group_scope_change_notice'?st?.state_data:null;
  if(d&&String(d?.line_group_id||'')===m[1]){
   try{
    await phmsPushMessages(m[1],t,[{type:'flex',altText:'🔐 การเข้าถึงของกลุ่มมีการเปลี่ยนแปลง',contents:{type:'bubble',size:'kilo',
     header:{type:'box',layout:'vertical',backgroundColor:'#F4F7FB',paddingAll:'16px',contents:[
      {type:'text',text:'🔐 การเข้าถึงของกลุ่มเปลี่ยนแล้ว',weight:'bold',size:'lg',wrap:true}
     ]},
     body:{type:'box',layout:'vertical',paddingAll:'16px',contents:[
      {type:'text',text:(d?.enabled===true?'เพิ่ม ':'เอาออก ')+String(d?.resource_label||'ข้อมูล')+'ของ '+String(d?.person_name||'สมาชิก'),size:'sm',wrap:true}
     ]}
    }}]);
    await clear(u,k,lineUserId);
    await reply(rt,'📢 แจ้งการเปลี่ยนแปลงในกลุ่มแล้ว',t)
   }catch(err){console.error('group_scope_change_push',String(err));await reply(rt,'⚠️ ยังส่งแจ้งในกลุ่มไม่ได้',t)}
  }else await reply(rt,'ℹ️ ไม่มีการเปลี่ยนแปลงล่าสุดที่รอแจ้ง',t);
  return true
 }
 m=c.match(/^ไม่แจ้งการเปลี่ยนขอบเขตกลุ่ม\s+([A-Za-z0-9_-]{8,80})$/);
 if(m){await clear(u,k,lineUserId);await reply(rt,'🔕 บันทึกแล้ว โดยไม่แจ้งในกลุ่ม',t);return true}

 m=c.match(/^ตั้งค่ากลุ่มส่วนตัว\s+([A-Za-z0-9_-]{8,80})$/);
 if(m){await phmsShowPrivateGroupSettings(rt,u,k,lineUserId,m[1],t);return true}

 m=c.match(/^การทำงานอิ่มอุ่นในกลุ่ม\s+([A-Za-z0-9_-]{8,80})$/);
 if(m){await phmsShowPrivateGroupBehavior(rt,u,k,lineUserId,m[1],t);return true}

 m=c.match(/^สลับถามตอบกลุ่มส่วนตัว\s+([A-Za-z0-9_-]{8,80})$/);
 if(m){
  try{
   const s=one(await rpc(u,k,'phms_line_group_settings',{p_line_user_id:lineUserId,p_line_group_id:m[1]}));
   await rpc(u,k,'phms_line_group_set_query_enabled',{
    p_line_user_id:lineUserId,p_line_group_id:m[1],p_enabled:s?.can_query_bot===false
   });
   await phmsShowPrivateGroupBehavior(rt,u,k,lineUserId,m[1],t,s?.can_query_bot===false?'✅ เปิดการตอบคำถามแล้ว':'🔕 ปิดการตอบคำถามแล้ว')
  }catch(err){
   console.error('private_group_query_toggle',String(err));
   await reply(rt,'🔒 เปลี่ยนค่านี้ไม่ได้ ต้องเป็นเจ้าบ้านหรือผู้ช่วยดูแลครอบครัว',t)
  }
  return true
 }

 m=c.match(/^ตั้งขอบเขตกลุ่มส่วนตัว\s+([A-Za-z0-9_-]{8,80})\s+(appointments|medications|health_data)$/);
 if(m){await phmsShowPrivateGroupScope(rt,u,k,lineUserId,m[1],t,m[2]);return true}

 m=c.match(/^ตั้งทั้งบ้านกลุ่มส่วนตัว\s+([A-Za-z0-9_-]{8,80})\s+(appointments|medications|health_data)\s+([0-9a-fA-F-]{8,36})\s+(on|off)$/);
 if(m){
  try{
   await rpc(u,k,'phms_line_group_set_family_scope',{
    p_line_user_id:lineUserId,
    p_line_group_id:m[1],
    p_family_code:m[3],
    p_resource:m[2],
    p_enabled:m[4]==='on'
   });
   await phmsShowPrivateGroupScope(
    rt,u,k,lineUserId,m[1],t,m[2],
    m[4]==='on'?'✅ เลือกทุกคนในบ้านนี้แล้ว':'○ ล้างรายการของบ้านนี้แล้ว'
   )
  }catch(err){
   console.error('private_group_family_scope',String(err));
   await reply(rt,'🔒 เปลี่ยนขอบเขตทั้งบ้านไม่ได้ ต้องเป็นเจ้าบ้านหรือผู้ช่วยดูแลครอบครัวของบ้านนั้น',t)
  }
  return true
 }

 m=c.match(/^สลับขอบเขตกลุ่มส่วนตัว\s+([A-Za-z0-9_-]{8,80})\s+(appointments|medications|health_data)\s+([0-9a-fA-F-]{8,36})$/);
 if(m){
  try{
   const s=one(await rpc(u,k,'phms_line_group_settings',{p_line_user_id:lineUserId,p_line_group_id:m[1]}));
   const row=(Array.isArray(s?.people)?s.people:[]).find((x:any)=>
    String(x?.person_code||'').toLowerCase().startsWith(String(m?.[3]||'').toLowerCase())
   );
   if(!row)throw new Error('scope_person_not_found');
   await rpc(u,k,'phms_line_group_toggle_query_scope',{
    p_line_user_id:lineUserId,p_line_group_id:m[1],p_person_code:m[3],p_resource:m[2],p_enabled:!(row?.[m[2]]===true)
   });
   await phmsShowPrivateGroupScope(rt,u,k,lineUserId,m[1],t,m[2],'✅ อัปเดตแล้ว')
  }catch(err){
   console.error('private_group_scope_toggle',String(err));
   await reply(rt,'🔒 เปลี่ยนขอบเขตนี้ไม่ได้ ต้องเป็นเจ้าบ้านหรือผู้ช่วยดูแลครอบครัว',t)
  }
  return true
 }


 m=c.match(/^ตั้งค่ากลุ่มเสร็จ\s+([A-Za-z0-9_-]{8,80})$/);
 if(m){
  try{
   const ss=one(await rpc(u,k,'phms_line_group_settings',{p_line_user_id:lineUserId,p_line_group_id:m[1]}));
   if(ss?.setup_completed===true){
    await phmsShowPrivateGroupSettings(rt,u,k,lineUserId,m[1],t,'💙 กลุ่มนี้เปิดใช้งานอยู่แล้ว')
   }else{
    const selected=(Array.isArray(ss?.people)?ss.people:[]).some((p:any)=>
     p?.appointments===true||p?.medications===true||p?.health_data===true
    );
    if(!selected){
     await reply(rt,'💙 เลือกอย่างน้อย 1 เรื่องกับ 1 คนก่อนนะ',t)
    }else{
     await replyMessages(rt,t,[phmsPrivateGroupActivationConfirmFlex(ss,m[1])])
    }
   }
  }catch(err){
   console.error('group_setup_preview',String(err));
   await reply(rt,'⚠️ ยังตรวจการตั้งค่ากลุ่มนี้ไม่ได้ ลองอีกครั้ง',t)
  }
  return true
 }

 m=c.match(/^ยืนยันเปิดใช้งานกลุ่ม\s+([A-Za-z0-9_-]{8,80})$/);
 if(m){
  try{
   const before=one(await rpc(u,k,'phms_line_group_settings',{p_line_user_id:lineUserId,p_line_group_id:m[1]}));
   if(before?.setup_completed===true){
    await phmsShowPrivateGroupSettings(rt,u,k,lineUserId,m[1],t,'💙 กลุ่มนี้เปิดใช้งานอยู่แล้ว');
    return true
   }
   const rr=one(await rpc(u,k,'phms_line_group_complete_setup',{
    p_line_user_id:lineUserId,p_line_group_id:m[1]
   }));
   if(rr?.should_send_ready===true){
    try{
     const ctx=one(await rpc(u,k,'phms_line_group_query_context',{
      p_line_group_id:String(rr?.line_group_id||m[1])
     }));
     await phmsPushMessages(String(rr?.line_group_id||m[1]),t,[phmsGroupReadyCarouselFlex(ctx)]);
     await rpc(u,k,'phms_line_group_mark_ready_sent',{p_line_group_id:String(rr?.line_group_id||m[1])});
    }catch(pushErr){
     console.error('group_ready_push_failed',String(pushErr));
     await reply(rt,'✅ บันทึกการตั้งค่าแล้ว แต่ยังส่งการ์ดพร้อมใช้งานเข้าในกลุ่มไม่สำเร็จ',t);
     return true
    }
   }
   await phmsShowPrivateGroupSettings(rt,u,k,lineUserId,m[1],t,'✅ เปิดใช้งาน LINE กลุ่มเรียบร้อยแล้ว')
  }catch(err){
   const msg=String(err);
   console.error('group_setup_complete',msg);
   await reply(rt,msg.includes('group_setup_requires_scope')
    ?'💙 เลือกอย่างน้อย 1 เรื่องกับ 1 คนก่อนนะ'
    :'⚠️ ยังเปิดใช้งานกลุ่มนี้ไม่ได้ ลองตรวจการตั้งค่าอีกครั้ง',t)
  }
  return true
 }

 m=c.match(/^สิทธิ์ขอเชื่อมกลุ่ม\s+([0-9a-fA-F-]{8,36})$/);
 if(m){await phmsShowGroupRequestPermissions(rt,u,k,lineUserId,t,m[1]);return true}

 m=c.match(/^สลับสิทธิ์ขอกลุ่ม\s+([0-9a-fA-F-]{8,36})\s+([0-9a-fA-F-]{8,36})$/);
 if(m){
  try{
   const w=one(await rpc(u,k,'phms_line_group_request_permission_workspace',{
    p_line_user_id:lineUserId,p_family_code:m[1]
   }));
   const row=(Array.isArray(w?.members)?w.members:[]).find((x:any)=>
    String(x?.user_code||'').toLowerCase().startsWith(String(m?.[2]||'').toLowerCase())
   );
   if(!row||row?.is_manager===true)throw new Error('request_permission_member_invalid');
   await rpc(u,k,'phms_line_group_set_request_permission',{
    p_line_user_id:lineUserId,p_family_code:m[1],p_user_code:m[2],p_enabled:!(row?.can_request===true)
   });
   await phmsShowGroupRequestPermissions(rt,u,k,lineUserId,t,m[1],'✅ อัปเดตสิทธิ์แล้ว')
  }catch(err){
   console.error('group_request_permission_toggle',String(err));
   await reply(rt,'🔒 เปลี่ยนสิทธิ์นี้ไม่ได้ ต้องเป็นเจ้าบ้านหรือผู้ช่วยดูแลครอบครัว',t)
  }
  return true
 }

 m=c.match(/^(อนุมัติเชื่อมกลุ่ม|ไม่อนุมัติเชื่อมกลุ่ม)\s+([0-9a-fA-F-]{8,36})$/);
 if(m){
  try{
   const rr=one(await rpc(u,k,'phms_review_line_group_link_request',{
    p_line_user_id:lineUserId,p_request_code:m[2],
    p_decision:m[1]==='อนุมัติเชื่อมกลุ่ม'?'approve':'reject',
    p_review_note:null
   }));
   if(rr?.decision==='approved'&&rr?.line_group_id){
    await rpc(u,k,'phms_line_group_begin_setup',{p_line_user_id:lineUserId,p_line_group_id:String(rr.line_group_id)});
    await phmsShowPrivateGroupSettings(rt,u,k,lineUserId,String(rr.line_group_id),t,
     '✅ อนุมัติและเชื่อมกลุ่มเรียบร้อย\n\n👥 LINE กลุ่ม: '+String(rr?.group_name||'LINE กลุ่ม')+'\n🏠 ครอบครัว: '+String(rr?.family_name||'ครอบครัว')
    )
   }else{
    await reply(rt,'↩️ ไม่อนุมัติคำขอนี้แล้ว',t)
   }
  }catch(err){
   console.error('group_link_request_review',String(err));
   await reply(rt,'⚠️ คำขอนี้อาจถูกจัดการไปแล้ว หรือตอนนี้ยังไม่มีสิทธิ์อนุมัติ',t)
  }
  return true
 }

 if(c==='เชื่อมกลุ่ม'&&String(st?.state_key||'')==='line_group_private_setup'){
  const gid=String(st?.state_data?.line_group_id||'');
  if(gid){
   try{
    const o=one(await rpc(u,k,'phms_line_group_setup_options',{
     p_line_user_id:lineUserId,p_line_group_id:gid
    }));
    await replyMessages(rt,t,[phmsGroupPrivateSetupFlex(o,gid)])
   }catch(err){
    console.error('private_group_resume',String(err));
    await reply(rt,'⚠️ ยังเปิดขั้นตอนเชื่อมกลุ่มไม่ได้ ลองพิมพ์ “เชื่อมกลุ่ม” จากในกลุ่มอีกครั้ง',t)
   }
   return true
  }
 }
 return false
}


async function phmsReplyJoinCards(rt:string,groupId:string,t:string){
 const messages=[phmsGroupWelcomeFlex()];
 try{
  const r=await fetch('https://api.line.me/v2/bot/message/reply',{
   method:'POST',
   headers:{Authorization:'Bearer '+t,'content-type':'application/json'},
   body:JSON.stringify({replyToken:rt,messages:messages.map(m=>phmsRemoveGroupBackButtons(phmsDualActionMessage(m)))})
  });
  if(r.ok)return true;
  const body=await r.text().catch(()=>'');
  console.error('line_group_join_cards_failed',r.status,body.slice(0,800));
 }catch(err){
  console.error('line_group_join_cards_exception',String(err))
 }
 try{
  await phmsPushMessages(groupId,t,[{
   type:'text',
   text:'💙 สวัสดีทุกคน อิ่มอุ่นมาอยู่ด้วยแล้ว 🌿✨\\nผู้ช่วยตัวเล็ก ๆ ของคนในบ้าน ช่วยจำเรื่องยา เรื่องนัด และเรื่องสุขภาพให้ทุกคนได้ 💙'
  }]);
  return false
 }catch(err){
  console.error('line_group_join_fallback_push_failed',String(err));
  return false
 }
}

async function phmsLineGroupSummary(token:string,groupId:string){
 try{
  const r=await fetch('https://api.line.me/v2/bot/group/'+encodeURIComponent(groupId)+'/summary',{
   headers:{Authorization:'Bearer '+token}
  });
  if(!r.ok)return {groupName:'',pictureUrl:''};
  const d=await r.json();
  return {groupName:String(d?.groupName||''),pictureUrl:String(d?.pictureUrl||'')};
 }catch{return {groupName:'',pictureUrl:''}}
}

async function phmsKnownGroupLinkCandidates(u:string,k:string){
 const memRes=await fetch(
  u+'/rest/v1/family_memberships?status=eq.active&select=user_id&limit=1000',
  {headers:H(k)}
 );
 if(!memRes.ok)throw new Error('group_link_members_lookup_failed:'+memRes.status);
 const memberships=await memRes.json().catch(()=>[]);
 if(!Array.isArray(memberships)||!memberships.length)return [];

 const userIds=[...new Set(
  memberships.map((x:any)=>String(x?.user_id||'').trim()).filter(Boolean)
 )];
 const keys=new Set<string>();
 const out:any[]=[];

 for(const userId of userIds.slice(0,500)){
  const idRes=await fetch(
   u+'/rest/v1/line_identities?user_id=eq.'+encodeURIComponent(userId)+
   '&is_active=eq.true&onboarding_status=eq.ready&select=line_user_id,user_id&order=updated_at.desc&limit=5',
   {headers:H(k)}
  );
  if(!idRes.ok)continue;
  const ids=await idRes.json().catch(()=>[]);
  for(const li of (Array.isArray(ids)?ids:[])){
   const lineUserId=String(li?.line_user_id||'').trim();
   if(!lineUserId||keys.has(lineUserId))continue;
   keys.add(lineUserId);
   out.push({line_user_id:lineUserId,user_id:userId})
  }
 }
 return out
}

async function phmsLineGroupHasMember(token:string,groupId:string,lineUserId:string){
 try{
  const r=await fetch(
   'https://api.line.me/v2/bot/group/'+encodeURIComponent(groupId)+'/member/'+encodeURIComponent(lineUserId),
   {headers:{Authorization:'Bearer '+token}}
  );
  if(r.ok)return true;
  if(r.status!==404){
   const body=await r.text().catch(()=>'');
   console.error('line_group_member_profile_failed',r.status,body.slice(0,500))
  }
  return false
 }catch(err){
  console.error('line_group_member_profile_exception',String(err));
  return false
 }
}

async function phmsNotifyGroupLinkCandidatesOnJoin(
 u:string,k:string,t:string,groupId:string,groupName:string
){
 const candidates=await phmsKnownGroupLinkCandidates(u,k);
 if(!candidates.length)return {checked:0,in_group:0,eligible:0,notified:0};

 let inGroup=0,eligible=0,notified=0;
 for(const c of candidates.slice(0,200)){
  const uid=String(c?.line_user_id||'');
  if(!uid)continue;

  const isMember=await phmsLineGroupHasMember(t,groupId,uid);
  if(!isMember)continue;
  inGroup++;

  try{
   const o=one(await rpc(u,k,'phms_line_group_setup_options',{
    p_line_user_id:uid,p_line_group_id:groupId
   }));
   const direct=Array.isArray(o?.direct_options)?o.direct_options:[];
   const requests=Array.isArray(o?.request_options)?o.request_options:[];
   const canContinue=o?.can_manage===true||direct.length>0||requests.length>0;
   if(!canContinue)continue;
   eligible++;

   // The same setup card handles both cases:
   // - Owner/Admin: link directly.
   // - Allowed member: send a link request for Owner/Admin approval.
   const sent=await phmsPushMessages(uid,t,[phmsGroupPrivateSetupFlex(o,groupId)]);
   try{
    await rpc(u,k,'phms_set_line_conversation_state',{
     p_line_user_id:uid,
     p_state_key:'line_group_private_setup',
     p_state_data:{
      line_group_id:groupId,
      group_name:groupName||String(o?.group_name||'LINE กลุ่ม'),
      opened_from:direct.length>0?'group_join_manager_detected':'group_join_requester_detected',
      private_prompt_sent:sent===true,
      private_prompt_sent_at:sent===true?new Date().toISOString():null
     },
     p_ttl_minutes:1440
    })
   }catch{}
   if(sent===true)notified++;
  }catch(err){
   const msg=String(err);
   if(!msg.includes('line_identity_not_ready')){
    console.error('group_join_link_candidate_auto_prompt_failed',uid,msg)
   }
  }
 }
 return {checked:candidates.length,in_group:inGroup,eligible,notified}
}

function phmsShortLabel(prefix:string,name:any){
 const x=(prefix+String(name||'')).trim();
 return x.length<=20?x:x.slice(0,19)+'…'
}
function phmsNotificationDaysText(v:any){
 const xs=(Array.isArray(v)?v:[]).map((x:any)=>Number(x)).filter((x:number)=>Number.isFinite(x));
 if(!xs.length)return '3 วันก่อน';
 return xs.map((x:number)=>x===0?'วันนัด':String(x)+' วันก่อน').join(' • ')
}
function phmsAppointmentNotificationWorkspaceText(w:any){
 const s=w?.settings||{};
 const users=Array.isArray(w?.users)?w.users:[];
 const groups=Array.isArray(w?.groups)?w.groups:[];
 const selectedUsers=users.filter((x:any)=>x?.selected===true);
 const selectedGroups=groups.filter((x:any)=>x?.selected===true);
 const userText=String(s?.recipient_mode||'default')==='custom'
  ?(selectedUsers.length?selectedUsers.map((x:any)=>String(x?.display_name||'สมาชิก')).slice(0,6).join(', '):'ยังไม่ได้เลือก')
  :'ตามสิทธิ์แจ้งเตือนของบุคคลนี้';
 const groupText=selectedGroups.length
  ?selectedGroups.map((x:any)=>String(x?.channel_name||'LINE กลุ่ม')).slice(0,6).join(', ')
  :'ไม่ส่งเข้ากลุ่ม';
 return '🔔 ตั้งค่าแจ้งเตือนนัด\n\n'
  +'📅 '+String(w?.title||'นัดหมาย')+'\n'
  +'⏰ '+phmsNotificationDaysText(s?.days_before)+' เวลา '+String(s?.time||'09:00')+' น.\n'
  +'🗓️ คิดแบบวันปฏิทิน • Asia/Bangkok\n\n'
  +'👤 ผู้รับ: '+userText+'\n'
  +'👥 กลุ่ม: '+groupText+'\n\n'
  +'มาตรฐาน: 3 วันก่อน เวลา 09:00 น. ไม่ได้นับย้อนหลัง 72 ชั่วโมง';
}
