    const a=Array.isArray(x?.items)?x.items:[],b=Array.isArray(x?.impacts)?x.impacts:[],ch=Array.isArray(x?.checks)?x.checks:[];
    const alert=b.filter((z:any)=>z.state==='PENDING_REVIEW').length;
