const naturalAccessTarget=c.match(/^(?:ดู|เปิด)\s*คนที่(?:ช่วยจัดการ|เข้าถึง(?:ข้อมูล)?)\s*(?:ของ)?\s*(.+)$/i);
if(naturalAccessTarget){
 try{
  const wanted=normPersonWord(String(naturalAccessTarget[1]||'').replace(/^ของ\s*/,''));
  const roster=one(await rpc(u,k,'phms_list_line_family_roster',{p_line_user_id:id}));
  const entries=Array.isArray(roster?.entries)?roster.entries:[];
  const labels=(x:any)=>[x?.display_name,x?.relationship_label,x?.shared_nickname,x?.nickname].map(normPersonWord).filter(Boolean);
  const exact=entries.filter((x:any)=>labels(x).some((v:string)=>v===wanted));
  const fuzzy=entries.filter((x:any)=>labels(x).some((v:string)=>v&&wanted&&(v.includes(wanted)||wanted.includes(v))));
  const found=exact.length?exact:fuzzy;
  if(found.length===1){
   const x=found[0],pc=String(x?.person_code||'');
   if(!pc)throw new Error('person_code_missing');
   if(x?.can_view===false){
    await reply(e.replyToken,'🔒 ตอนนี้คุณยังไม่มีสิทธิ์ดูข้อมูลของ '+String(x?.display_name||'บุคคลนี้')+'\n\nส่งคำขอสิทธิ์ได้จากปุ่มด้านล่าง',t,[pb('📥 ส่งคำขอสิทธิ์','ขอสิทธิ์ดูบุคคล '+pc),pb('👤 กลับรายชื่อ','บุคคลในครอบครัว')])
   }else{
    await rpc(u,k,'phms_select_line_context_person',{p_line_user_id:id,p_selection_code:pc});
    await replyPersonCaregiverManager(e.replyToken,u,k,id,t)
   }
  }else if(found.length>1){
   await reply(e.replyToken,'พบชื่อที่ใกล้กันมากกว่า 1 คน เลือกคนที่ต้องการดูก่อน',t,found.slice(0,8).map((x:any)=>pb(phmsPersonSelectionLabel(x?.display_name,'เลือกคน'),'เปิดสิทธิ์บุคคล '+String(x?.person_code||''))))
  }else{
   await reply(e.replyToken,'ยังจับคู่ชื่อ “'+String(naturalAccessTarget[1]||'')+'” กับบุคคลในครอบครัวไม่ได้',t,[pb('👤 เปิดรายชื่อ','บุคคลในครอบครัว')])
  }
 }catch(err){console.error('natural_person_access_summary',String(err));await reply(e.replyToken,'⚠️ ยังเปิดสรุปคนที่เข้าถึงข้อมูลบุคคลนี้ไม่ได้',t,[pb('👤 บุคคลในครอบครัว','บุคคลในครอบครัว')])}
 continue
}
