  const title=editViewLabel[2]==='display'?'🏷️ ชื่อที่ฉันใช้เรียก':'👪 ความสัมพันธ์กับฉัน';
  const currentValue=editViewLabel[2]==='display'?String(s?.display_label||'ยังไม่ได้ตั้ง'):String(s?.relationship_label||'ยังไม่ได้ตั้ง');
