  if(z[1]){await cmd(e.replyToken,u,k,id,String(z[1]),t);continue}
  let isSelf=false;
  try{const ss=one(await rpc(u,k,'phms_get_line_setup_state',{p_line_user_id:id}));isSelf=String(ss?.self_person_id||'')===String(pp?.person_id||'')}catch{}
