function appointmentReminderLabel(offsets:any,post:any,postTime:any=null){
 const xs=Array.isArray(offsets)?offsets.map((x:any)=>Number(x)).filter((x:number)=>Number.isFinite(x)).sort((a:number,b:number)=>b-a):[];
 const label=xs.length?xs.map((m:number)=>m%1440===0?(m/1440)+' วัน':m%60===0?(m/60)+' ชั่วโมง':m+' นาที').join(' + '):'ปิดเตือนก่อนนัด';
 const p=Number(post);
 const time=String(postTime||'').slice(0,5);
 const after=time?'20:00 น. ของวันนัด':Number.isFinite(p)&&p>0?(p%60===0?(p/60)+' ชั่วโมงหลังนัด':p+' นาทีหลังนัด'):'ปิด';
 return label+' ก่อนนัด • เตือนบันทึกหลังนัด '+after
}
const remindOpen=c.match(/^ตั้งเตือนนัด\s+#?([0-9a-fA-F-]{8,36})$/);
