const financeMethodPick=c.match(/^เลือกช่องทางค่าใช้จ่าย\s+#?([0-9a-fA-F-]{8,36})\s+(promptpay_qr|cash|credit_card|debit_card|bank_transfer|e_wallet|other)$/);
