if(followupYes){
 try{
   const w=one(await rpc(u,k,'phms_line_appointment_workspace',{p_line_user_id:id,p_record_code:followupYes[1]}));
   let partial:any={
     appointment_type:'follow_up',
     followup_of_appointment_id:String(w.record_id),
     title:w?.item?.title||undefined,
     hospital_name:w?.item?.hospital_name||undefined,
     department:w?.item?.department||undefined,
     doctor_name:w?.item?.doctor_name||undefined,
     location_detail:w?.item?.location_detail||undefined,
     contact_phone:w?.item?.contact_phone||undefined,
     contact_email:/^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i.test(String(w?.item?.contact_email||'').trim())?String(w.item.contact_email).trim():undefined,
     coverage_type:w?.item?.coverage_type||undefined,
     hospital_hn:w?.item?.hospital_hn||undefined,
     care_topic:w?.item?.care_topic||undefined,
     arrival_lead_minutes:Number(w?.item?.arrival_lead_minutes||0)||undefined,
     organization_id:w?.item?.organization_id||undefined,
     service_unit_id:w?.item?.service_unit_id||undefined,
     clinician_id:w?.item?.clinician_id||undefined
   };
   partial=await enrichAppointmentDoctor(u,k,id,partial);
   await state(u,k,id,'appointment_followup_confirm',{
     partial,raw_text:'นัดติดตามจาก #'+String(w.record_code||followupYes[1]),
     person_confirmed:true,source_record_code:String(w.record_code||followupYes[1])
   });
   const lines=[
    '➕ นัดติดตามต่อจากนัดเดิม',
    '',
    'อิ่มอุ่นจะใช้ข้อมูลเดิมเหล่านี้ต่อ:',
    '📌 นัดเพื่อ: '+String(partial.title||'ยังไม่ระบุ'),
    '🏥 รพ./คลินิก: '+String(partial.hospital_name||'—'),
    '🏢 แผนก: '+String(partial.department||'—'),
    '👨‍⚕️ แพทย์: '+String(partial.doctor_name||'—'),
    '🪪 สิทธิรักษา: '+String(partial.coverage_type||'—'),
    '🆔 HN: '+String(partial.hospital_hn||'—'),
    '🧭 เรื่องที่รักษา: '+String(partial.care_topic||'—'),
    '⏱️ มาก่อนเวลานัด: '+(Number(partial.arrival_lead_minutes||0)>0?String(partial.arrival_lead_minutes)+' นาที':'—'),
    '',
    'ตรวจว่าถูกต้องก่อน แล้วค่อยใส่วัน/เวลานัดใหม่'
   ].join('\n');
   await reply(e.replyToken,lines,t,[
    pb('✅ ใช้ข้อมูลเดิม','ยืนยันข้อมูลนัดติดตาม'),
    pb('✏️ เปลี่ยนบางอย่าง','แก้ข้อมูลนัดติดตาม'),
    pb('❌ ยกเลิกเพิ่มนัด','ยกเลิกเพิ่มนัด')
   ]);
 }catch(err){console.error('appointment_followup_start',String(err));await reply(e.replyToken,'⚠️ ยังเริ่มนัดติดตามไม่ได้',t)}
 continue
}

const followupNo=c.match(/^ไม่มีนัดติดตาม\s+#?([0-9a-fA-F-]{8,36})$/);
if(followupNo){
 try{
   const rr=one(await rpc(u,k,'phms_line_appointment_post_visit',{p_line_user_id:id,p_record_code:followupNo[1],p_outcome_notes:null,p_followup_required:false}));
   await reply(e.replyToken,'✅ บันทึกแล้วว่าไม่มีนัดติดตามต่อ',t,[act('📎 แนบเอกสาร','แนบเอกสารนัด '+String(rr.record_code||followupNo[1])),pb('📅 ดูนัด','ดูนัด '+String(rr.record_code||followupNo[1]))]);
 }catch(err){console.error('appointment_followup_none',String(err));await reply(e.replyToken,'⚠️ ยังบันทึกไม่ได้',t)}
 continue
}


const taskListCmd=c.match(/^สิ่งที่ต้องทำก่อนนัด\s+#?([0-9a-fA-F-]{8,36})$/);
if(taskListCmd){
 try{
   const w=one(await rpc(u,k,'phms_line_appointment_workspace',{p_line_user_id:id,p_record_code:taskListCmd[1]}));
   const tasks=Array.isArray(w?.tasks)?w.tasks:[];
   let evidenceItems:any[]=[];
   try{
    const ev=one(await rpc(u,k,'phms_line_appointment_task_evidence_list',{p_line_user_id:id,p_record_code:String(w.record_code||taskListCmd[1])}));
    evidenceItems=Array.isArray(ev?.items)?ev.items:[]
   }catch(err){console.error('appointment_task_evidence_list_for_checklist',String(err))}
   const evidenceByTask=new Map<string,any[]>();
   for(const x of evidenceItems){
    const code=String(x?.task_code||'');
    if(!code)continue;
    const xs=evidenceByTask.get(code)||[];
    xs.push(x);evidenceByTask.set(code,xs)
   }

   const cards:any[]=[{type:'bubble',size:'kilo',
    header:{type:'box',layout:'vertical',backgroundColor:'#EEF6FF',paddingAll:'18px',contents:[
     {type:'text',text:'✅ สิ่งที่ต้องทำก่อนนัด',weight:'bold',size:'xl',color:'#365F8D',wrap:true},
     {type:'text',text:String(w?.item?.title||'นัดหมาย'),size:'sm',weight:'bold',margin:'sm',wrap:true}
    ]},
    body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'16px',contents:[
     {type:'text',text:tasks.length?'ทั้งหมด '+String(tasks.length)+' รายการ':'ยังไม่มีสิ่งที่ต้องทำก่อนนัด',size:'md',weight:'bold',wrap:true},
     {type:'text',text:'กดรายการเพื่อทำเครื่องหมายหรือจัดการได้',size:'sm',color:'#667085',wrap:true}
    ]},
    footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'10px',contents:[
     {type:'button',style:'primary',action:{type:'postback',label:'➕ เพิ่มรายการ',data:'เพิ่มสิ่งที่ต้องทำ '+String(w.record_code||taskListCmd[1])}},
     {type:'button',action:{type:'postback',label:'↩️ กลับนัด',data:'ดูนัด '+String(w.record_code||taskListCmd[1])}}
    ]}
   }];

   for(const x of tasks.slice(0,8)){
    const code=String(x?.code||'');
    const evs=evidenceByTask.get(code)||[];
    const first=evs[0]||null;
    let previewUrl='';
    let previewImage=false;
    if(first?.bucket_id&&first?.object_name){
     const mime=String(first?.mime_type||'').toLowerCase(),path=String(first?.object_name||'').toLowerCase();
     previewImage=/^image\//.test(mime)||/\.(?:jpg|jpeg|png|webp)$/.test(path);
     if(previewImage){
      try{previewUrl=await signGalleryObject(u,k,String(first.bucket_id),String(first.object_name),1800)}
      catch(err){console.error('appointment_task_checklist_preview_sign',String(err))}
     }
    }
    const st=x?.status==='completed'?'✅ ทำแล้ว':x?.status==='skipped'?'↪️ ข้ามแล้ว':'⬜ รอทำ';
    // PHMS_PREP_TASK_BUTTON_STANDARD_V2: one primary and one contextual secondary.
    const foot:any[]=[
     ...(x?.status==='pending'?[{type:'button',style:'primary',height:'md',action:{type:'postback',label:'✅ ทำเสร็จแล้ว',data:'ทำแล้ว '+code}}]:[]),
     {type:'button',style:'secondary',height:'md',action:{type:'postback',label:evs.length?'📎 ดูหลักฐาน':'📎 แนบหลักฐาน',data:evs.length?'ดูหลักฐานงานเตรียม '+code:'หลักฐานงานเตรียม '+code+' 0'}}
    ];
    cards.push({type:'bubble',size:'kilo',
     ...(previewImage&&previewUrl?{hero:{type:'image',url:previewUrl,size:'full',aspectRatio:'4:3',aspectMode:'fit',backgroundColor:'#F7F9FC',action:{type:'uri',label:'เปิดรูปหลักฐาน',uri:previewUrl}}}:{}),
     header:{type:'box',layout:'vertical',paddingAll:'14px',backgroundColor:x?.status==='completed'?'#EEF8F3':'#FAFAFA',contents:[
      {type:'text',text:String(x?.title||'งานเตรียม'),weight:'bold',size:'md',wrap:true},
      {type:'text',text:st+(evs.length?' • 📎 '+String(evs.length):''),size:'xs',color:x?.status==='completed'?'#2F6B4F':'#667085',margin:'sm',wrap:true}
     ]},
     body:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'14px',contents:[
      ...(x?.instruction?[appointmentFormRow('📝','รายละเอียด',String(x.instruction))]:[]),
      ...(first?[appointmentFormRow('🖼️','ตัวอย่างหลักฐาน',String(first?.title||'รูป/เอกสาร'))]:[]),
      ...(evs.length>1?[{type:'text',text:'มีหลักฐานอีก '+String(evs.length-1)+' รูป/ไฟล์ • กด “ดูหลักฐาน” เพื่อเปิดทั้งหมด',size:'xs',color:'#667085',wrap:true}]:[]),
      ...(!evs.length?[{type:'text',text:'ยังไม่มีรูปหรือเอกสารหลักฐาน',size:'sm',color:'#777777',wrap:true}]:[])
     ]},
     footer:{type:'box',layout:'vertical',spacing:'sm',paddingAll:'10px',contents:foot.slice(0,4)}
    })
   }
   await replyMessages(e.replyToken,t,[{type:'flex',altText:'✅ สิ่งที่ต้องทำก่อนนัด '+String(w?.item?.title||''),contents:{type:'carousel',contents:cards.slice(0,10)}}])
 }catch(err){
  console.error('appointment_tasks_list',String(err));
  await reply(e.replyToken,'⚠️ ยังเปิดรายการเตรียมก่อนนัดไม่ได้',t)
 }
 continue
}

