const appointmentOpenDocumentCmd=c.match(/^เปิดไฟล์เอกสารนัด\s+#?([0-9a-fA-F-]{8,36})\s+([0-9a-fA-F-]{36})$/);
if(appointmentOpenDocumentCmd){
 try{
  const code=appointmentOpenDocumentCmd[1],linkId=appointmentOpenDocumentCmd[2];
  const out=one(await rpc(u,k,'phms_line_appointment_documents',{p_line_user_id:id,p_record_code:code}));
  const item=(Array.isArray(out?.items)?out.items:[]).find((x:any)=>String(x?.link_id||'')===linkId);
  if(!item)throw new Error('appointment_document_link_not_found');
  let url='';
  if(item?.bucket_id&&item?.object_name)url=await signGalleryObject(u,k,String(item.bucket_id),String(item.object_name),1800);
  if(!url)throw new Error('appointment_document_signed_url_missing');
  const title=String(item?.title||'เอกสารนัด');
  if(url.length>4700)throw new Error('appointment_document_signed_url_too_long');
  await reply(e.replyToken,'📎 '+title+'\n\nเปิดไฟล์จากลิงก์นี้ได้เลย (ลิงก์มีอายุประมาณ 30 นาที)\n'+url,t,[pb('📎 กลับเอกสารของนัด','เอกสารนัด '+code),pb('↩️ รายละเอียดนัด','ดูนัด '+code)])
 }catch(err){
  console.error('appointment_document_open_file',String(err));
  await reply(e.replyToken,'⚠️ ยังสร้างลิงก์เปิดเอกสารไม่ได้ แต่เอกสารยังอยู่ในระบบ',t,[pb('📎 กลับเอกสาร','เอกสารนัด '+appointmentOpenDocumentCmd[1]),pb('↩️ กลับนัด','ดูนัด '+appointmentOpenDocumentCmd[1])])
 }
 continue
}
