  const reason=String(reasonMatch?.[1]||'').trim();
  if(reason.length<2){
   await reply(e.replyToken,'⚠️ ใส่เหตุผลที่เลื่อนนัดด้วย\n\nวันใหม่: '+String(st?.state_data?.date||'')+'\nเวลาใหม่: '+String(st?.state_data?.time||'')+'\nเหตุผล: ',t,[pb('❌ ยกเลิก','ดูนัด '+code)]);
   continue
  }
