 if(!c||c.length>500||/^(?:ยืนยัน|บันทึก|ยกเลิก|กลับ|เพิ่ม|ดูรายละเอียด)/.test(c)){await reply(e.replyToken,'กรุณาพิมพ์ค่าของช่องนี้ ไม่ใช่คำสั่งเมนู (ไม่เกิน 500 ตัวอักษร)',t,[pb('❌ ยกเลิกช่องนี้','ยกเลิกช่องนี้')]);continue}
 const values={...(st.state_data?.values||{}),[key]:c};await state(u,k,id,'phms_add_menu',{type,values});
